				NIC: &SharedNICSetting{},
				AdditionalNICs: []AdditionalNICSettingHolder{
					&ConnectedNICSetting{
						SwitchID: 1111111,
					},
				},
				Client: &APIClient{
					Switch: &dummySwitchReader{
						err: errors.New("not found"),
					},
				},
			},
			err: errors.New("invalid AdditionalNICs[0]: reading switch info(id:1111111) is failed: not found"),
		},
