			msg: "plan not found",
			in: &Builder{
				CPU:      1000,
				MemoryGB: 1024,
				Client: &APIClient{
					ServerPlan: &dummyPlanFinder{},
				},
			},
			err: errors.New("server plan not found"),
		},
	}

	for _, tc := range cases {
		err := tc.in.Validate(context.Background(), "tk1v")
		require.Equal(t, tc.err, err, tc.msg)
	}
}

