func connectToServerViaSSH(t testutil.TestT, user, ip string, privateKey []byte, passPhrase []byte) error {
	signer, err := ssh.ParsePrivateKeyWithPassphrase(privateKey, passPhrase)
	if err != nil {
		return err
	}

	config := &ssh.ClientConfig{
		User: user,
		Auth: []ssh.AuthMethod{
			ssh.PublicKeys(signer),
		},
		HostKeyCallback: ssh.InsecureIgnoreHostKey(), // nolint:gosec
		Timeout:         10 * time.Second,
	}

	client, err := ssh.Dial("tcp", ip+":22", config)
	if err != nil {
		return err
	}
	defer client.Close()

	session, err := client.NewSession()
	if err != nil {
		return err
	}
	defer session.Close()

	var b bytes.Buffer
	session.Stdout = &b
	if err := session.Run("/usr/bin/whoami"); err != nil {
		return err
	}
	t.Logf("Connect to the Server via SSH: `whoami`: %s\n", b.String())
	return nil
}

func TestBuilder_IsNeedShutdown(t *testing.T) {
	cases := []struct {
		msg    string
		in     *Builder
		expect bool
		err    error
	}{
		{
			msg:    "server id is empty",
			expect: false,
			err:    errors.New("server id required"),
			in:     &Builder{},
		},
		{
			msg:    "in-place update",
			expect: false,
			err:    nil,
			in: &Builder{
				ServerID:    types.ID(1),
				Name:        "update",
				Description: "update",
				Tags:        types.Tags{"update1", "update2"},
				Client: &APIClient{
					Server: &dummyCreateServerHandler{
						server: &iaas.Server{
							ID:          types.ID(1),
							Name:        "update",
							Description: "update",
							Tags:        types.Tags{"update1", "update2-upd"},
						},
					},
				},
			},
		},
		{
			msg:    "changed: PrivateHostID",
			expect: true,
			err:    nil,
			in: &Builder{
				ServerID:      types.ID(1),
				PrivateHostID: types.ID(2),
				Client: &APIClient{
					Server: &dummyCreateServerHandler{
						server: &iaas.Server{
							ID:            types.ID(1),
							PrivateHostID: types.ID(3),
						},
					},
				},
			},
		},
		{
			msg:    "changed: InterfaceDriver",
			expect: true,
			err:    nil,
			in: &Builder{
				ServerID:        types.ID(1),
				InterfaceDriver: types.InterfaceDrivers.E1000,
				Client: &APIClient{
					Server: &dummyCreateServerHandler{
						server: &iaas.Server{
							ID:              types.ID(1),
							InterfaceDriver: types.InterfaceDrivers.VirtIO,
						},
					},
				},
			},
		},
		{
			msg:    "changed: Memory Size",
			expect: true,
			err:    nil,
			in: &Builder{
				ServerID: types.ID(1),
				MemoryGB: 1,
				Client: &APIClient{
					Server: &dummyCreateServerHandler{
						server: &iaas.Server{
							ID:       types.ID(1),
							MemoryMB: 2,
						},
					},
				},
			},
		},
		{
			msg:    "changed: CPU",
			expect: true,
			err:    nil,
			in: &Builder{
				ServerID: types.ID(1),
				CPU:      1,
				Client: &APIClient{
					Server: &dummyCreateServerHandler{
						server: &iaas.Server{
							ID:  types.ID(1),
							CPU: 2,
						},
					},
				},
			},
		},
		{
			msg:    "changed: Commitment",
			expect: true,
			err:    nil,
			in: &Builder{
				ServerID: types.ID(1),
				CPU:      1,
				Client: &APIClient{
					Server: &dummyCreateServerHandler{
						server: &iaas.Server{
							ID:                   types.ID(1),
							CPU:                  1,
							ServerPlanCommitment: types.Commitments.DedicatedCPU,
						},
					},
				},
			},
		},
		{
			msg:    "changed: add NIC",
			expect: true,
			err:    nil,
			in: &Builder{
				ServerID: types.ID(1),
				NIC:      &SharedNICSetting{},
				Client: &APIClient{
					Server: &dummyCreateServerHandler{
						server: &iaas.Server{
							ID: types.ID(1),
						},
					},
				},
			},
		},
		{
			msg:    "changed: delete NIC",
			expect: true,
			err:    nil,
			in: &Builder{
				ServerID: types.ID(1),
				Client: &APIClient{
					Server: &dummyCreateServerHandler{
						server: &iaas.Server{
							ID: types.ID(1),
							Interfaces: []*iaas.InterfaceView{
								{
									ID:             types.ID(2),
									SwitchScope:    types.Scopes.Shared,
									PacketFilterID: 0,
									UpstreamType:   types.UpstreamNetworkTypes.Shared,
								},
							},
						},
					},
				},
			},
		},
		{
			msg:    "changed: Packet Filter ID",
			expect: false,
			err:    nil,
			in: &Builder{
				ServerID: types.ID(1),
				NIC: &SharedNICSetting{
					PacketFilterID: types.ID(10),
				},
				Client: &APIClient{
					Server: &dummyCreateServerHandler{
						server: &iaas.Server{
							ID: types.ID(1),
							Interfaces: []*iaas.InterfaceView{
								{
									ID:             types.ID(2),
									SwitchScope:    types.Scopes.Shared,
									PacketFilterID: types.ID(11),
									UpstreamType:   types.UpstreamNetworkTypes.Shared,
								},
							},
						},
					},
				},
			},
		},
	}

	for _, tc := range cases {
		got, err := tc.in.IsNeedShutdown(context.Background(), testutil.TestZone())
		require.Equal(t, tc.err, err, tc.msg)
		require.Equal(t, tc.expect, got, tc.msg)
	}
}

func TestBuilder_UpdateWithPreviousID(t *testing.T) {
	ctx := context.Background()
	builder := &Builder{
		Name:            testutil.ResourceName("server-builder"),
		CPU:             1,
		MemoryGB:        1,
		Commitment:      types.Commitments.Standard,
		Generation:      types.PlanGenerations.Default,
		Tags:            types.Tags{"tag1", "tag2"},
		BootAfterCreate: false,
		Client:          NewBuildersAPIClient(testutil.SingletonAPICaller()),
		ForceShutdown:   true,
	}
	createResult, err := builder.Build(ctx, testutil.TestZone())
	if err != nil {
		t.Fatal(err)
	}

	serverOp := iaas.NewServerOp(testutil.SingletonAPICaller())
	server, err := serverOp.Read(ctx, testutil.TestZone(), createResult.ServerID)
	if err != nil {
		t.Fatal(err)
	}

	require.EqualValues(t, builder.Tags, server.Tags)

	// プラン変更
	builder.ServerID = server.ID
	builder.CPU = 2
	builder.MemoryGB = 4

	updateResult, err := builder.Update(ctx, testutil.TestZone())
	if err != nil {
		t.Fatal(err)
	}

	// IDが変更されているはず
	require.True(t, createResult.ServerID != updateResult.ServerID)
	updated, err := serverOp.Read(ctx, testutil.TestZone(), updateResult.ServerID)
	if err != nil {
		t.Fatal(err)
	}

	require.EqualValues(t, plans.AppendPreviousIDTagIfAbsent(server.Tags, server.ID), updated.Tags)

	// cleanup
	if err := serverOp.Delete(ctx, testutil.TestZone(), updated.ID); err != nil {
		t.Fatal(err)
	}
}

func TestBuilder_GPUPlan(t *testing.T) {
	if !testutil.IsAccTest() {
		t.Skip("TestBuilder_GPUPlan only exec when running an Acceptance Test")
	}

	ctx := context.Background()
	zone := "is1a"
	builder := &Builder{
		Name:            testutil.ResourceName("server-builder"),
		CPU:             4,
		MemoryGB:        56,
		GPU:             1,
		BootAfterCreate: false,
		Client:          NewBuildersAPIClient(testutil.SingletonAPICaller()),
		ForceShutdown:   true,
	}
	withGPU, err := builder.Build(ctx, zone)
	if err != nil {
		t.Fatal(err)
	}

	// for update
	builder.ServerID = withGPU.ServerID
	builder.GPU = 0
	_, err = builder.Update(ctx, zone)
	require.Error(t, err, "server plan not found")

	// cleanup
	serverOp := iaas.NewServerOp(testutil.SingletonAPICaller())
	if err := serverOp.Delete(ctx, zone, withGPU.ServerID); err != nil {
		t.Fatal(err)
	}
}

