	start := time.Now()
	b.runWorkers(base)
	newReport(b.method, b.results, b.Output, time.Now().Sub(start)).finalize()
}

// Run makes all the requests, prints the summary. It blocks until
// all work is done.
func (b *Boomer) Run() {
	switch b.Mode {
	case 1:
		b.method = "INSERT"
	case 2:
		b.method = "INSERT"
	case 3:
		b.method = "SELECT"
	case 4:
