// isValidSQLIdentifier reports whether s is a safe SQL identifier
// (letters, digits, and underscores, not starting with a digit).
func isValidSQLIdentifier(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i, r := range s {
		switch {
		case r == '_':
		case r >= 'a' && r <= 'z':
		case r >= 'A' && r <= 'Z':
		case i > 0 && r >= '0' && r <= '9':
		default:
			return false
		}
	}
	return true
}

