func init() {
    http.HandleFunc("/", handleRoot)
    http.HandleFunc("/authorize", handleAuthorize)
    http.HandleFunc("/oauth2callback", handleOAuth2Callback)

    http.HandleFunc("/photos", handleGetPhotos)

    http.HandleFunc("/follow", handleFollowUser)
