		rdr = strings.NewReader("{}")
	} else {
		defer f.Close()
		rdr = f
	}
	err = json.NewDecoder(rdr).Decode(&users)
	if err != nil {
		panic(err)
	}
	for _, u := range users {
		idUsers[u.ID] = u
	}
}

func saveUsers() {
	f, err := os.Create("users.json")
	if err != nil {
		panic(err)
	}
	defer f.Close()
	err = json.NewEncoder(f).Encode(users)
	if err != nil {
		panic(err)
	}
}

