	var username string
	c, err := req.Cookie("login")
	if err == nil {
		id := c.Value
		u, ok := idUsers[id]
		if !ok {
			log.Printf("error getting logged in user with id %s\n", id)
		} else {
			username = u.Username
		}
	}
	err = tpl.ExecuteTemplate(res, "index", username)
	if err != nil {
		http.Error(res, "Server Error", http.StatusInternalServerError)
