const winWSAETIMEDOUT syscall.Errno = 10060

// checks if the underlying error is a connectex error and if the underying cause is winsock timeout or temporary error, in which case we should retry.
func isWinsockTimeOutError(err error) net.Error {
	if uerr, ok := err.(*url.Error); ok {
		if derr, ok := uerr.Err.(*net.OpError); ok {
			if serr, ok := derr.Err.(*os.SyscallError); ok && serr.Syscall == "connectex" {
				if winerr, ok := serr.Err.(syscall.Errno); ok && (winerr == winWSAETIMEDOUT || winerr.Temporary()) {
					return &retriableError{error: err}
				}
			}
		}
	}
	return nil
}

func isDialConnectError(err error) net.Error {
	if uerr, ok := err.(*url.Error); ok {
		if derr, ok := uerr.Err.(*net.OpError); ok {
			if serr, ok := derr.Err.(*os.SyscallError); ok && serr.Syscall == "connect" {
				return &retriableError{error: err}
			}
		}
	}
	return nil
}

func isRetriableDialError(err error) net.Error {
	if derr := isWinsockTimeOutError(err); derr != nil {
		return derr
	}
	return isDialConnectError(err)
}

type retriableError struct {
	error
}

func (*retriableError) Timeout() bool {
	return false
}

func (*retriableError) Temporary() bool {
	return true
}

const tcpKeepOpenMinLength = 8 * int64(util.MB)

func (p *clientPolicy) Do(ctx context.Context, request pipeline.Request) (pipeline.Response, error) {
	req := request.WithContext(ctx)

	if req.ContentLength < tcpKeepOpenMinLength {
		req.Close = true
	}

	r, err := pipelineHTTPClient.Do(req)
	pipresp := pipeline.NewHTTPResponse(r)
	if err != nil {
		if derr := isRetriableDialError(err); derr != nil {
			return pipresp, derr
		}
		err = pipeline.NewError(err, "HTTP request failed")
	}
	return pipresp, err
}

var pipelineHTTPClient = newpipelineHTTPClient()

func newpipelineHTTPClient() *http.Client {

	return &http.Client{
		Transport: &http.Transport{
			Proxy: http.ProxyFromEnvironment,
			Dial: (&net.Dialer{
				Timeout:   30 * time.Second,
				KeepAlive: 30 * time.Second,
				DualStack: true,
			}).Dial,
			MaxIdleConns:           100,
			MaxIdleConnsPerHost:    100,
			IdleConnTimeout:        60 * time.Second,
			TLSHandshakeTimeout:    10 * time.Second,
			ExpectContinueTimeout:  1 * time.Second,
			DisableKeepAlives:      false,
			DisableCompression:     false,
			MaxResponseHeaderBytes: 0}}

}

// Add @ideaJOO
func ReBlobName(rawBlobName string) (renamedBlobNames string) {

	// 1. Parse
	// 2. Get UserID , PathKey , FileKey

	var userID string
	var pathKey string
	var fileKey string

	parseInfo, err := ParsingRawBlobName(rawBlobName)
	if err != nil {
		return rawBlobName
	}

	userID = parseInfo.User
	pathKey = CalCheckSum(parseInfo.Path)
	fileKey = CalCheckSum(parseInfo.File)

	renamedBlobNames = fmt.Sprintf("%s-%s-%s", userID, pathKey, fileKey)
	return renamedBlobNames
}

type ParsedPathInfo struct {
	User string
	Path string
	File string
}

// Add @ideaJOO
func ParsingRawBlobName(tBlobName string) (parsePathInfo ParsedPathInfo, err error) {

	// Sample
	// ParsingRawBlobName("/sijoo/path1/path2/file.png")  		=> sijoo path1/path2	file.png
	// ParsingRawBlobName("a/b/c/sijoo/path1/path2/file.png",3) => sijoo path1/path2  	file.png
	// ParsingRawBlobName("/a/c/sijoo/file.png",2)				=> sijoo "" 			file.png
	// ParsingRawBlobName("a@b@sijoo@file.png",2,"@")			=> sijoo ""				file.png

	sIndex := 0
	delimiter := "/"

	if string(tBlobName[0]) != delimiter {
		tBlobName = fmt.Sprintf("%s%s", delimiter, tBlobName)
	}

	paths := strings.Split(tBlobName[1:], delimiter)[sIndex:]
	numPaths := len(paths)
	if numPaths < 2 {
		// Default Format = {userid}{pathName}{fileName}
		// MinCase = {userid}{fileName}
		// there is case what has no pathName.
		return parsePathInfo, fmt.Errorf("incorrect your args : %s", tBlobName)
	}

	startIdx := 0 // TODO Control Index to Handle Parsed-Paths. @ideaJOO

	uID := paths[startIdx]
	pathName := strings.Join(paths[startIdx+1:numPaths-1], "/")
	fileName := paths[numPaths-1]
	parsePathInfo = ParsedPathInfo{uID, pathName, fileName}

	return parsePathInfo, nil
}

// Add @ideaJOO
func CalCheckSum(target string, algorithm ...string) string {
	var tHash hash.Hash

	tAlgorithm := "MD5"
	if len(algorithm) != 0 {
		tAlgorithm = algorithm[0]
	}

	switch strings.ToUpper(tAlgorithm) {
	case "MD5":
		tHash = md5.New()
	case "SHA256":
		tHash = sha256.New()
	default:
		return "checksum1234"
	}
	tHash.Write([]byte(target))
	return hex.EncodeToString(tHash.Sum(nil))
}

