	cases := map[string]string{
		`<EMAIL>`:                              `<EMAIL>`,
		`<<EMAIL>>`:                            `<EMAIL>`,
		`<NAME> <<EMAIL>>`:            `"<NAME>" <<EMAIL>>`,
		`"<NAME>" <<EMAIL>>`:          `"<NAME>" <<EMAIL>>`,
		`Martin العَرَبِية Tournoij <<EMAIL>>`: `"Martin العَرَبِ<NAME>" <<EMAIL>>`,
		`"<Martin; Tøurnoij>" <<EMAIL>>`:       `"<Martin; Tøurnoij>" <<EMAIL>>`,
		`"Martin \a\ \"Tournoij\"" <<EMAIL>>`:  `"Martin a \"Tournoij\"" <<EMAIL>>`,
		`"Martin" foo "Tournoij" <<EMAIL>>`:    `"Martin foo Tournoij" <<EMAIL>>`,
		`"Martin"foo"Tournoij" <<EMAIL>>`:      `"MartinfooTournoij" <<EMAIL>>`,
		`<NAME>
<<EMAIL>>`: `"<NAME>" <<EMAIL>>`,

		`=?utf-8?q?=E6=97=A5=E6=9C=AC=D0=BA=D0=B8=E6=AD=A3=E9=AB=94=E0=B8=AD?=` +
			`=?utf-8?q?=E0=B8=B1=E0=B8=81=E0=B8=A9=ED=9B=88=EB=AF=BC?= <<EMAIL>>`: `` +
			`"日本ки正體อักษ훈민" <<EMAIL>>`,

		``:                     ``,
		`,`:                    ``,
		`<EMAIL>,`:  `<EMAIL>`,
		`,<EMAIL>`:  `<EMAIL>`,
		`,<EMAIL>,`: `<EMAIL>`,
		`"<EMAIL> FOO" <<EMAIL>>`: `"<EMAIL> FOO" <<EMAIL>>`,
	}

	for test, expected := range cases {
