func GetTestPaginationSupportServers(t *testing.T) {
	opts := client.NewRequestOptions()
	opts.QueryParameters.Set("orderby", "id")
	resp, _, err := TOSession.GetServers(opts)
	if err != nil {
		t.Fatalf("cannot Get Servers: %v - alerts: %+v", err, resp.Alerts)
	}
	server := resp.Response
	if len(server) < 3 {
		t.Fatalf("Need at least 3 server in Traffic Ops to test pagination support, found: %d", len(server))
	}

	opts.QueryParameters.Set("limit", "1")
	serversWithLimit, _, err := TOSession.GetServers(opts)
	if err != nil {
		t.Fatalf("cannot Get server with Limit: %v - alerts: %+v", err, serversWithLimit.Alerts)
	}
	if !reflect.DeepEqual(server[:1], serversWithLimit.Response) {
		t.Error("expected GET server with limit = 1 to return first result")
	}

	opts.QueryParameters.Set("offset", "1")
	serversWithOffset, _, err := TOSession.GetServers(opts)
	if err != nil {
		t.Fatalf("cannot Get server with Limit and Offset: %v - alerts: %+v", err, serversWithOffset.Alerts)
	}
	if !reflect.DeepEqual(server[1:2], serversWithOffset.Response) {
		t.Error("expected GET server with limit = 1, offset = 1 to return second result")
	}

	opts.QueryParameters.Del("offset")
	opts.QueryParameters.Set("page", "2")
	serversWithPage, _, err := TOSession.GetServers(opts)
	if err != nil {
		t.Fatalf("cannot Get server with Limit and Page: %v - alerts: %+v", err, serversWithPage.Alerts)
	}
	if !reflect.DeepEqual(server[1:2], serversWithPage.Response) {
		t.Error("expected GET server with limit = 1, page = 2 to return second result")
	}

	opts.QueryParameters = url.Values{}
	opts.QueryParameters.Set("limit", "-2")
	resp, _, err = TOSession.GetServers(opts)
	if err == nil {
		t.Error("expected GET server to return an error when limit is not bigger than -1")
	} else if !alertsHaveError(resp.Alerts.Alerts, "must be bigger than -1") {
		t.Errorf("expected GET server to return an error for limit is not bigger than -1, actual error: %v - alerts: %+v", err, resp.Alerts)
	}

	opts.QueryParameters.Set("limit", "1")
	opts.QueryParameters.Set("offset", "0")
	resp, _, err = TOSession.GetServers(opts)
	if err == nil {
		t.Error("expected GET server to return an error when offset is not a positive integer")
	} else if !alertsHaveError(resp.Alerts.Alerts, "must be a positive integer") {
		t.Errorf("expected GET server to return an error for offset is not a positive integer, actual error: %v - alerts: %+v", err, resp.Alerts)
	}

	opts.QueryParameters = url.Values{}
	opts.QueryParameters.Set("limit", "1")
	opts.QueryParameters.Set("page", "0")
	resp, _, err = TOSession.GetServers(opts)
	if err == nil {
		t.Error("expected GET server to return an error when page is not a positive integer")
	} else if !alertsHaveError(resp.Alerts.Alerts, "must be a positive integer") {
		t.Errorf("expected GET server to return an error for page is not a positive integer, actual error: %v - alerts: %+v", err, resp.Alerts)
	}
}

package controller

import (
	"encoding/json"
	"errors"
	"finance-tracker/auth"
	"finance-tracker/model"
	"net/http"
)

func (s *Server) AppUserHandler(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case "POST":
		aui := model.AppUser{}
		err := json.NewDecoder(r.Body).Decode(&aui)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		err = s.validateNewAppUser(&aui)
		if err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		existingAppUser, err := s.DB.GetAppUserByEmail(*aui.Email)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		if existingAppUser != nil {
			http.Error(w, "user already exists with that email", http.StatusBadRequest)
			return
		}
		_, err = s.DB.CreateAppUser(&aui)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		w.WriteHeader(201)
		return
	}
}

func (s *Server) LoginHandler(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case "POST":
		appUser := &model.AppUser{}
		err := json.NewDecoder(r.Body).Decode(&appUser)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		u, err := s.DB.GetAppUserByEmail(*appUser.Email)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		if u == nil {
			http.Error(w, "invalid email/password", http.StatusInternalServerError)
			return
		}
		err = u.VerifyPassword(*appUser.Password)
		if err != nil {
			http.Error(w, "invalid email/password", http.StatusInternalServerError)
			return
		}
		token, err := auth.CreateToken(*u.ID, *u.Email, *u.FirstName)
		if err != nil {
			http.Error(w, err.Error(), http.StatusUnprocessableEntity)
			return
		}
		err = json.NewEncoder(w).Encode(map[string]string{
			"token": token,
		})
		if err != nil {
			http.Error(w, err.Error(), http.StatusUnprocessableEntity)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(200)
		return
	}
}

func (s *Server) validateNewAppUser(u *model.AppUser) error {
	if u.Email == nil {
		return errors.New("email cannot be empty")
	}
	if u.FirstName == nil {
		return errors.New("first name cannot be empty")
	}
	if u.Password == nil {
		return errors.New("password cannot be empty")
	}
	if *u.Password == "" {
		return errors.New("password cannot be empty")
	}
	return nil
}

package blockchain

import (
	"errors"
	"fmt"
	"strings"

	"github.com/hyperledger/fabric-sdk-go/pkg/client/channel"
	"github.com/hyperledger/fabric-sdk-go/pkg/client/event"
	caMsp "github.com/hyperledger/fabric-sdk-go/pkg/client/msp"
	"github.com/hyperledger/fabric-sdk-go/pkg/common/providers/msp"
	"github.com/hyperledger/fabric-sdk-go/pkg/fabsdk"
)

// User stuct that allow a registered user to query and invoke the blockchain
type FabricUser struct {
	Username        string
	Fabric          *FabricSetup
	SigningIdentity msp.SigningIdentity
	ChannelClient   *channel.Client
}

var sessionUser = make(map[string]string)
var secretKey = make(map[string]string)

func (s *FabricSetup) SessionUser() (*FabricUser, error) {

	if len(sessionUser["name"]) > 0 {

		var err error

		var username = sessionUser["name"]

		var user FabricUser
		user.Username = username
		user.Fabric = s

		user.SigningIdentity, err = s.CaClient.GetSigningIdentity(username)
		if err != nil {
			return nil, fmt.Errorf("failed to get signing identity for '%s': %v", username, err)
		}

		clientContext := s.sdk.ChannelContext(
			s.ChannelID, fabsdk.WithUser(username),
			fabsdk.WithOrg(s.OrgName),
			fabsdk.WithIdentity(user.SigningIdentity))

		// Channel client is used to query and execute transactions
		user.ChannelClient, err = channel.New(clientContext)
		if err != nil {
			return nil, fmt.Errorf("failed to create new channel client for '%s': %v", username, err)
		}
		fmt.Println("Channel client created")

		// Creation of the client which will enables access to our channel events
		s.event, err = event.New(clientContext)
		if err != nil {
			return nil, fmt.Errorf("failed to create new event client %v", err)
		}

		return &user, nil
	}

	return nil, nil
}

func (s *FabricUser) Logout() {

	delete(sessionUser, "name")
}

func (s *FabricUser) RevokeUser(email string) error {

	_, err := s.Fabric.CaClient.Revoke(&caMsp.RevocationRequest{
		Name: email,
	})

	if err != nil {
		return fmt.Errorf("failed to revoke signing identity for '%s': %v", email, err)
	}

	return nil
}

func (s *FabricUser) RemoveUserFromCA(email string) error {

	_, err := s.Fabric.CaClient.RemoveIdentity(&caMsp.RemoveIdentityRequest{

		ID:     email,
		Force:  true,
		CAName: s.Fabric.CaID,
	})

	if err != nil {
		return fmt.Errorf("failed to remove signing identity for '%s': %v", email, err)
	}

	return nil
}

func (s *FabricUser) RemoveUser(email string) error {

	err := s.RemoveUserFromCA(email)

	if err != nil {
		return fmt.Errorf("failed to remove signing identity for '%s': %v", email, err)
	} else {

		err = s.DeleteUserFromLedger(email)
		if err != nil {
			return fmt.Errorf("unable to delete user from blockchain:>>> %v", err)
		}

	}

	return nil

}

func (u *FabricUser) UpdateUserData(userId, name, email, company, occupation, salary, userType string) error {

	_, err := u.UpdateUserDataFromLedger(userId, name, email, company, occupation, salary, userType)

	if err != nil {
		return fmt.Errorf("unable to update user data in blockchain:>>> %v", err)
	}

	return nil
}

func (s *FabricUser) ChangePassword(email, userType, oldPwd, newPwd string) error {

	if !strings.EqualFold(oldPwd, secretKey["secret"]) {
		return errors.New("failed old password not matched, can't change pwd")
	}

	if strings.EqualFold(oldPwd, newPwd) {
		return errors.New("failed old password, new password should not be same")
	}

	err := s.RemoveUserFromCA(email)

	if err != nil {
		return fmt.Errorf("failed to remove identity '%s': %v", email, err)
	}

	fmt.Println("User Removed")

	err = s.Fabric.RegisterWithCA(email, newPwd, userType)

	if err != nil {
		return fmt.Errorf("failed to register with CA '%s': %v", email, err)
	}

	fmt.Println("User Re-Registered")

	err = s.Fabric.EnrollUser(email, newPwd)

	if err != nil {
		return fmt.Errorf("failed to enroll user '%s': %v", email, err)
	}

	fmt.Println("User Enrolled")

	err = s.Fabric.ReEnrollUser(email)

	if err != nil {
		fmt.Println("Error Re-Enroll User : %s ", err.Error())
		return fmt.Errorf("failed to re-enroll user '%s': %v", email, err)
	}

	fmt.Println("User Re-Enrolled")

	return nil
}

func (s *FabricSetup) ReEnrollUser(email string) error {

	err := s.CaClient.Reenroll(email)

	if err != nil {
		return fmt.Errorf("failed to re-enroll user '%s': %v", email, err)
	}
	return nil
}

func (s *FabricSetup) EnrollUser(email, password string) error {

	err := s.CaClient.Enroll(email, caMsp.WithSecret(password))
	if err != nil {
		return fmt.Errorf("failed to enroll identity '%s': %v", email, err)
	}

	secretKey["secret"] = password

	return nil
}

func (s *FabricSetup) LoginUser(email, password string) (*FabricUser, error) {

	err := s.EnrollUser(email, password)

	if err != nil {
		return nil, fmt.Errorf("failed to enroll user '%s': %v", email, err)
	}

	var user FabricUser
	user.Username = email
	user.Fabric = s

	user.SigningIdentity, err = s.CaClient.GetSigningIdentity(email)
	if err != nil {
		return nil, fmt.Errorf("failed to get signing identity for '%s': %v", email, err)
	}

	clientContext := s.sdk.ChannelContext(
		s.ChannelID, fabsdk.WithUser(email),
		fabsdk.WithOrg(s.OrgName),
		fabsdk.WithIdentity(user.SigningIdentity))

	// Channel client is used to query and execute transactions
	user.ChannelClient, err = channel.New(clientContext)
	if err != nil {
		return nil, fmt.Errorf("failed to create new channel client for '%s': %v", email, err)
	}
	fmt.Println("Channel client created")

	// Creation of the client which will enables access to our channel events
	s.event, err = event.New(clientContext)
	if err != nil {
		return nil, fmt.Errorf("failed to create new event client %v", err)
	}
	fmt.Println("Event client created")

	fmt.Println("Login Successful")

	sessionUser["name"] = email

	return &user, nil
}

func (s *FabricSetup) RegisterWithCA(email, password, userType string) error {

	fmt.Println("CA Register === " + s.CaID)

	_, err := s.CaClient.Register(&caMsp.RegistrationRequest{
		Name:           email,
