func main() {
	listener, err := net.Listen("tcp", "0.0.0.0:6213")
	if err != nil {
		HandleError(err)
	}
	defer listener.Close()
	println("running ...")	

	for {
		conn, err := listener.Accept()		
		if err != nil {
			HandleError(err)
		}
		// println("accept conn: ",conn)
		go handleConn(conn)
	}	
}

