package task

import (
	"fmt"
	"io"
	"net"
	"net/http"

	v1 "github.com/google/go-containerregistry/pkg/v1"
	"github.com/google/go-containerregistry/pkg/v1/tarball"
	"github.com/julienschmidt/httprouter"
	"github.com/sirupsen/logrus"
)

type LocalRegistry map[string]v1.Image

func LoadRegistry(imagePaths map[string]string) (LocalRegistry, error) {
	images := LocalRegistry{}
	for name, path := range imagePaths {
		image, err := tarball.ImageFromPath(path, nil)
		if err != nil {
			return nil, fmt.Errorf("image from path: %w", err)
		}

		images[name] = image
	}

	return images, nil
}

func ServeRegistry(reg LocalRegistry) (string, error) {
	router := httprouter.New()
	router.GET("/v2/:name/manifests/:ref", reg.GetManifest)
	router.GET("/v2/:name/blobs/:digest", reg.GetBlob)

	router.NotFound = http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		logrus.WithFields(logrus.Fields{
			"method": r.Method,
			"path":   r.URL.Path,
		}).Warnf("unknown request")
	})

	listener, err := net.Listen("tcp", ":0")
	if err != nil {
		return "", fmt.Errorf("listen: %w", err)
	}

	go http.Serve(listener, router)

	_, port, err := net.SplitHostPort(listener.Addr().String())
	if err != nil {
		return "", fmt.Errorf("split registry host/port: %w", err)
	}

	return port, nil
}

func (registry LocalRegistry) BuildArgs(port string) []string {
	var buildArgs []string
	for name := range registry {
		buildArgs = append(buildArgs, fmt.Sprintf("%s=localhost:%s/%s", name, port, name))
	}

	return buildArgs
}

func (registry LocalRegistry) GetManifest(w http.ResponseWriter, r *http.Request, p httprouter.Params) {
	name := p.ByName("name")
	ref := p.ByName("ref")

	logrus.WithFields(logrus.Fields{
		"accept": r.Header["Accept"],
	}).Debugf("get manifest for %s at %s", name, ref)

	image, found := registry[name]
	if !found {
		w.WriteHeader(http.StatusNotFound)
		return
	}

	mt, err := image.MediaType()
	if err != nil {
		logrus.Errorf("failed to get media type: %s", err)
		w.WriteHeader(http.StatusInternalServerError)
		return
	}

	blob, err := image.RawManifest()
	if err != nil {
		logrus.Errorf("failed to get manifest: %s", err)
		w.WriteHeader(http.StatusInternalServerError)
		return
	}

	digest, err := image.Digest()
	if err != nil {
		logrus.Errorf("failed to get digest: %s", err)
		w.WriteHeader(http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", string(mt))
	w.Header().Set("Content-Length", fmt.Sprintf("%d", len(blob)))
	w.Header().Set("Docker-Content-Digest", digest.String())

	if r.Method == "HEAD" {
		return
	}

	_, err = w.Write(blob)
	if err != nil {
		logrus.Errorf("write manifest blob: %s", err)
		return
	}
}

func (registry LocalRegistry) GetBlob(w http.ResponseWriter, r *http.Request, p httprouter.Params) {
	name := p.ByName("name")
	dig := p.ByName("digest")

	logrus.WithFields(logrus.Fields{
		"accept": r.Header["Accept"],
	}).Debugf("get blob %s", dig)

	image, found := registry[name]
	if !found {
		w.WriteHeader(http.StatusNotFound)
		return
	}

	hash, err := v1.NewHash(dig)
	if err != nil {
		logrus.Errorf("failed to parse digest: %s", err)
		w.WriteHeader(http.StatusInternalServerError)
		return
	}

	cfgHash, err := image.ConfigName()
	if err != nil {
		logrus.Errorf("failed to get config hash: %s", err)
		w.WriteHeader(http.StatusInternalServerError)
		return
	}

	if hash == cfgHash {
		manifest, err := image.Manifest()
		if err != nil {
			logrus.Errorf("get image manifest: %s", err)
			return
		}

		cfgBlob, err := image.RawConfigFile()
		if err != nil {
			logrus.Errorf("failed to get config file: %s", err)
			w.WriteHeader(http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", string(manifest.Config.MediaType))
		w.Header().Set("Content-Length", fmt.Sprintf("%d", len(cfgBlob)))

		if r.Method == "HEAD" {
			return
		}

		_, err = w.Write(cfgBlob)
		if err != nil {
			logrus.Errorf("write config blob: %s", err)
			return
		}

		return
	}

	layer, err := image.LayerByDigest(hash)
	if err != nil {
		logrus.Errorf("failed to get layer: %s", err)
		w.WriteHeader(http.StatusInternalServerError)
		return
	}

	size, err := layer.Size()
	if err != nil {
		logrus.Errorf("failed to get layer size: %s", err)
		w.WriteHeader(http.StatusInternalServerError)
		return
	}

	mt, err := layer.MediaType()
	if err != nil {
		logrus.Errorf("failed to get layer media type: %s", err)
		w.WriteHeader(http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", string(mt))
	w.Header().Set("Content-Length", fmt.Sprintf("%d", size))

	if r.Method == "HEAD" {
		return
	}

	blob, err := layer.Compressed()
	if err != nil {
		logrus.Errorf("failed to read layer: %s", err)
		w.WriteHeader(http.StatusInternalServerError)
		return
	}

	_, err = io.Copy(w, blob)
	if err != nil {
		logrus.Errorf("write blob: %s", err)
		return
	}
}

package assured

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net"
	"net/http"
	"strconv"
	"strings"

	"github.com/pborman/uuid"
)

// Client
type Client struct {
	Errc chan error
	Options
}

// NewClient creates a new go-rest-assured client
func NewClient(opts ...Option) *Client {
	c := Client{
		Errc:    make(chan error),
		Options: DefaultOptions,
	}
	c.Options.applyOptions(opts...)

	if c.ctx == nil {
		c.ctx = context.Background()
	}
	c.ctx, c.cancel = context.WithCancel(c.Options.ctx)

	if c.Options.Port == 0 {
		if listen, err := net.Listen("tcp", ":0"); err == nil {
			c.Options.Port = listen.Addr().(*net.TCPAddr).Port
			listen.Close()
		}
	}
	c.startApplicationHTTPListener()
	return &c
}

// url returns the url to used by the client internally
func (c *Client) url() string {
	schema := "http"
	if c.tlsCertFile != "" && c.tlsKeyFile != "" {
		schema = "https"
	}
	return fmt.Sprintf("%s://%s:%d", schema, c.host, c.Port)
}

// URL returns the url to use to test you stubbed endpoints
func (c *Client) URL() string {
	return fmt.Sprintf("%s/when", c.url())
}

// Close is used to close the running service
func (c *Client) Close() {
	c.cancel()
}

// Given stubs assured Call(s)
func (c *Client) Given(calls ...Call) error {
	for _, call := range calls {
		// Default method to GET
		if call.Method == "" {
			call.Method = http.MethodGet
		}

		// Sanitize Path
		call.Path = strings.Trim(call.Path, "/")

		req, err := http.NewRequest(call.Method, fmt.Sprintf("%s/given/%s", c.url(), call.Path), bytes.NewReader(call.Response))
		if err != nil {
			return err
		}
		if call.StatusCode != 0 {
			req.Header.Set(AssuredStatus, strconv.Itoa(call.StatusCode))
		}
		if call.Delay > 0 {
			req.Header.Set(AssuredDelay, strconv.Itoa(call.Delay))
		}
		for key, value := range call.Headers {
			req.Header.Set(key, value)
		}

		// Create callbacks
		callbacks := make([]*http.Request, len(call.Callbacks))
		callbackKey := <KEY>()
		for i, callback := range call.Callbacks {
			if callback.Target == "" {
				return fmt.Errorf("cannot stub callback without target")
			}
			callbackReq, err := http.NewRequest(callback.Method, fmt.Sprintf("%s/callback", c.url()), bytes.NewReader(callback.Response))
			if err != nil {
				return err
			}
			callbackReq.Header.Set(AssuredCallbackTarget, callback.Target)
			callbackReq.Header.Set(AssuredCallbackKey, callbackKey)
			if callback.Delay > 0 {
				callbackReq.Header.Set(AssuredCallbackDelay, strconv.Itoa(callback.Delay))
			}
			for key, value := range callback.Headers {
				callbackReq.Header.Set(key, value)
			}
			callbacks[i] = callbackReq
		}
		if len(callbacks) > 0 {
			req.Header.Set(AssuredCallbackKey, callbackKey)
		}

		if _, err = c.httpClient.Do(req); err != nil {
			return err
		}
		for _, cReq := range callbacks {
			if _, err = c.httpClient.Do(cReq); err != nil {
				return err
			}
		}
	}
	return nil
}

// Verify returns all of the calls made against a stubbed method and path
func (c *Client) Verify(method, path string) ([]Call, error) {
	req, err := http.NewRequest(method, fmt.Sprintf("%s/verify/%s", c.url(), path), nil)
	if err != nil {
		return nil, err
	}
	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, err
	}

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("failure to verify calls")
	}
	defer resp.Body.Close()

	var calls []Call
	if err = json.NewDecoder(resp.Body).Decode(&calls); err != nil {
		return nil, err
	}
	return calls, nil
}

// Clear assured calls for a Method and Path
func (c *Client) Clear(method, path string) error {
	req, err := http.NewRequest(method, fmt.Sprintf("%s/clear/%s", c.url(), path), nil)
	if err != nil {
		return err
	}
	_, err = c.httpClient.Do(req)
	return err
}

// ClearAll clears all assured calls
func (c *Client) ClearAll() error {
	req, err := http.NewRequest(http.MethodDelete, fmt.Sprintf("%s/clear", c.url()), nil)
	if err != nil {
		return err
	}
	_, err = c.httpClient.Do(req)
	return err
}

