// SetupGRPC setup and return a gRPC server
func SetupGRPC(ctx context.Context, errCh chan<- error) {
	server := &server{
		db: db.Connect(),
	}

	s := grpc.NewServer(grpc.EmptyServerOption{})
	event.RegisterEventSvcServer(s, server)

	go func() {
		lis, err := net.Listen("tcp", ":42113")
