func main() {
	lis, err := net.Listen("tcp", ":3001")
	if err != nil {
		log.Fatalf("Failed to listen: %v", err)
	}

	err = setExternalClient()
	if err != nil {
		log.Fatalf("Failed to instantiate a crypto compare client: %v", err)
