	client, ok := clients.Load(name)
	cclient, ok := client.(*lib.ChatClient)
	if ok {
		var err error
		var conn net.Conn
		*fn = func() net.Conn {
			conn, err = net.Dial(cclient.Listener.Addr().Network(), cclient.Listener.Addr().String())
