		}
		return err
	} else {
		*fn = func() net.Conn {
			return nil
		}
		return errors.New("Failed to find client")
	}
	return nil
}

func (s *Server) Deregister(name interface{}, cc *lib.ChatClient) error {
	clients.Delete(name)
	return nil
}

