package bolt

import (
	"fmt"
	"io"
	"net"
	"testing"

	"github.com/neo4j/neo4j-go-driver/v4/neo4j/internal/packstream"
)

// Fake of bolt3 server.
// Utility to test bolt3 protocol implemntation.
// Use panic upon errors, simplifies output when server is running within a go thread
// in the test.
type bolt3server struct {
	conn     net.Conn
	unpacker *packstream.Unpacker
	out      *outgoing
}

func newBolt3Server(conn net.Conn) *bolt3server {
	return &bolt3server{
		unpacker: &packstream.Unpacker{},
		conn:     conn,
		out: &outgoing{
			chunker: newChunker(),
			packer:  packstream.Packer{},
		},
	}
}

func (s *bolt3server) waitForHandshake() []byte {
	handshake := make([]byte, 4*5)
	_, err := io.ReadFull(s.conn, handshake)
	if err != nil {
		panic(err)
	}
	return handshake
}

func (s *bolt3server) assertStructType(msg *testStruct, t byte) {
	if msg.tag != t {
		panic(fmt.Sprintf("Got wrong type of message expected %d but got %d (%+v)", t, msg.tag, msg))
	}
}

func (s *bolt3server) sendFailureMsg(code, msg string) {
	s.send(msgFailure, map[string]interface{}{
		"code":    code,
		"message": msg,
	})
}

func (s *bolt3server) sendIgnoredMsg() {
	s.send(msgIgnored)
}

func (s *bolt3server) waitForHello() {
	msg := s.receiveMsg()
	s.assertStructType(msg, msgHello)
	m := msg.fields[0].(map[string]interface{})
	// Hello should contain some musts
	_, exists := m["scheme"]
	if !exists {
		s.sendFailureMsg("?", "Missing scheme in hello")
	}
	_, exists = m["user_agent"]
	if !exists {
		s.sendFailureMsg("?", "Missing user_agent in hello")
	}
}

func (s *bolt3server) receiveMsg() *testStruct {
	_, buf, err := dechunkMessage(s.conn, []byte{}, -1, nil, "")
	if err != nil {
		panic(err)
	}

	s.unpacker.Reset(buf)
	s.unpacker.Next()
	n := s.unpacker.Len()
	t := s.unpacker.StructTag()

	fields := make([]interface{}, n)
	for i := uint32(0); i < n; i++ {
		s.unpacker.Next()
		fields[i] = serverHydrator(s.unpacker)
	}
	return &testStruct{tag: t, fields: fields}
}

func (s *bolt3server) waitForRun() {
	msg := s.receiveMsg()
	s.assertStructType(msg, msgRun)
}

func (s *bolt3server) waitForReset() {
	msg := s.receiveMsg()
	s.assertStructType(msg, msgReset)
}

func (s *bolt3server) waitForTxBegin() {
	msg := s.receiveMsg()
	s.assertStructType(msg, msgBegin)
}

func (s *bolt3server) waitForTxCommit() {
	msg := s.receiveMsg()
	s.assertStructType(msg, msgCommit)
}

func (s *bolt3server) waitForTxRollback() {
	msg := s.receiveMsg()
	s.assertStructType(msg, msgRollback)
}

func (s *bolt3server) waitForPullAll() {
	msg := s.receiveMsg()
	s.assertStructType(msg, msgPullAll)
}

func (s *bolt3server) acceptVersion(ver byte) {
	acceptedVer := []byte{0x00, 0x00, 0x00, ver}
	_, err := s.conn.Write(acceptedVer)
	if err != nil {
		panic(err)
	}
}

func (s *bolt3server) rejectVersions() {
	_, err := s.conn.Write([]byte{0x00, 0x00, 0x00, 0x00})
	if err != nil {
		panic(err)
	}
}

func (s *bolt3server) closeConnection() {
	s.conn.Close()
}

func (s *bolt3server) send(tag byte, field ...interface{}) {
	s.out.appendX(byte(tag), field...)
	s.out.send(s.conn)
}

func (s *bolt3server) sendSuccess(m map[string]interface{}) {
	s.send(msgSuccess, m)
}

func (s *bolt3server) acceptHello() {
	s.send(msgSuccess, map[string]interface{}{
		"connection_id": "cid",
		"server":        "fake/3.5",
	})
}

func (s *bolt3server) rejectHelloUnauthorized() {
	s.send(msgFailure, map[string]interface{}{
		"code":    "Neo.ClientError.Security.Unauthorized",
		"message": "",
	})
}

// Utility when something else but connect is to be tested
func (s *bolt3server) accept(ver byte) {
	s.waitForHandshake()
	s.acceptVersion(ver)
	s.waitForHello()
	s.acceptHello()
}

// Utility to wait and serve a auto commit query
func (s *bolt3server) serveRun(stream []testStruct) {
	s.waitForRun()
	s.waitForPullAll()
	for _, x := range stream {
		s.send(x.tag, x.fields...)
	}
}

func (s *bolt3server) serveRunTx(stream []testStruct, commit bool, bookmark string) {
	s.waitForTxBegin()
	s.send(msgSuccess, map[string]interface{}{})
	s.waitForRun()
	s.waitForPullAll()
	for _, x := range stream {
		s.send(x.tag, x.fields...)
	}
	if commit {
		s.waitForTxCommit()
		s.out.appendX(byte(msgSuccess), map[string]interface{}{
			"bookmark": bookmark,
		})
		s.out.send(s.conn)
	} else {
		s.waitForTxRollback()
		s.send(msgSuccess, map[string]interface{}{})
	}
}

func setupBolt3Pipe(t *testing.T) (net.Conn, *bolt3server, func()) {
	l, err := net.Listen("tcp", ":0")
	if err != nil {
		t.Fatalf("Unable to listen: %s", err)
	}

	addr := l.Addr()
	clientConn, err := net.Dial(addr.Network(), addr.String())

	srvConn, err := l.Accept()
	if err != nil {
		t.Fatalf("Accept error: %s", err)
	}
	srv := newBolt3Server(srvConn)

	return clientConn, srv, func() {
		l.Close()
	}
}

package proxy_test

import (
	"fmt"
	"net"
	"net/http"
	"net/http/httptest"
	"sync"
	"testing"
	"time"

	"github.com/zalando/skipper/eskip"
	"github.com/zalando/skipper/filters"
	"github.com/zalando/skipper/filters/fadein"
	"github.com/zalando/skipper/loadbalancer"
	"github.com/zalando/skipper/proxy"
	"github.com/zalando/skipper/routing"
)

/*
Creating a separate test harness for the fade-in functionality, because the existing test proxy doesn't support
multiple proxy instances and should be wrapped anyway, while the changes in the routing in these tests are
consequences to events happening to the backend instances, and therefore the test data client should be wrapped,
too. The harness implements the following setup:

	client -> proxy -> data client <- backend
	          |-> proxy instance 1    |-> backend instance 1
	          |-> proxy instance 2    |-> backend instance 2
	          \-> proxy instance 3    |-> backend instance 3
	                                  \-> backend instance 4
*/

const (
	testFadeInDuration = 6000 * time.Millisecond
	statBucketCount    = 10
	clientRate         = time.Millisecond
	minStats           = 300
	fadeInTolerance    = 0.3
)

type fadeInDataClient struct {
	reset, update chan []*eskip.Route
}

type fadeInBackendInstance struct {
	server  *httptest.Server
	created time.Time
}

type fadeInBackend struct {
	test        *testing.T
	withFadeIn  bool
	withCreated bool
	clients     []fadeInDataClient
	instances   []fadeInBackendInstance
}

type fadeInProxyInstance struct {
	proxy  *proxy.Proxy
	server *httptest.Server
}

type fadeInProxy struct {
	test      *testing.T
	mx        *sync.Mutex
	backend   *fadeInBackend
	instances []*fadeInProxyInstance
}

type stat struct {
	timestamp time.Time
	status    int
	endpoint  string
	err       error
}

type fadeInClient struct {
	test               *testing.T
	proxy              *fadeInProxy
	httpClient         *http.Client
	statRequests       chan chan []stat
	resetStatsRequests chan struct{}
	quit               chan struct{}
}

func randomURLs(t *testing.T, n int) []string {
	var u []string
	for i := 0; i < n; i++ {
		l, err := net.Listen("tcp", ":0")
		if err != nil {
			t.Fatal(err)
		}

		_, p, err := net.SplitHostPort(l.Addr().String())
		if err != nil {
			t.Fatal(err)
		}

		l.Close()
		u = append(u, fmt.Sprintf(":%s", p))
	}

	return u
}

func createDataClient(r ...*eskip.Route) fadeInDataClient {
	var c fadeInDataClient
	c.reset = make(chan []*eskip.Route, 1)
	c.update = make(chan []*eskip.Route, 1)
	c.reset <- r
	return c
}

func (c fadeInDataClient) LoadAll() ([]*eskip.Route, error) {
	r := <-c.reset
	c.reset <- r
	return r, nil
}

func (c fadeInDataClient) LoadUpdate() ([]*eskip.Route, []string, error) {
	return <-c.update, nil, nil
}

// startBackend starts a backend representing 0 or more endpoints, added in a separate step.
func startBackend(t *testing.T, withFadeIn, withCreated bool) *fadeInBackend {
	return &fadeInBackend{
		test:        t,
		withFadeIn:  withFadeIn,
		withCreated: withCreated,
	}
}

func (b *fadeInBackend) route() *eskip.Route {
	r := &eskip.Route{
		Id:          "fadeInRoute",
		BackendType: eskip.LBBackend,
	}

	if b.withFadeIn {
		r.Filters = append(r.Filters, &eskip.Filter{
			Name: filters.FadeInName,
			Args: []interface{}{testFadeInDuration},
		})
	}

	for _, i := range b.instances {
		r.LBEndpoints = append(r.LBEndpoints, i.server.URL)
		if !i.created.IsZero() {
			r.Filters = append(r.Filters, &eskip.Filter{
				Name: filters.EndpointCreatedName,
				Args: []interface{}{
					i.server.URL,
					i.created,
				},
			})
		}
	}

	return r
}

func (b *fadeInBackend) createDataClient() routing.DataClient {
	c := createDataClient(b.route())
	b.clients = append(b.clients, c)
	return c
}

func (b *fadeInBackend) addInstances(u ...string) error {
	var instances []fadeInBackendInstance
	for _, ui := range u {
		if err := func(u string) error {
			l, err := net.Listen("tcp", u)
			if err != nil {
				return err
			}

			server := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
				w.Header().Set("X-Backend-Endpoint", u)
			}))
			server.Listener.Close()
			server.Listener = l
			server.Start()
			instance := fadeInBackendInstance{
				server: server,
			}

			if b.withCreated {
				instance.created = time.Now()
			}

			instances = append(instances, instance)
			return nil
		}(ui); err != nil {
			for _, i := range instances {
				i.server.Close()
			}

			return err
		}
	}

	b.instances = append(b.instances, instances...)
	r := []*eskip.Route{b.route()}
	for _, c := range b.clients {
		<-c.reset
		select {
		case <-c.update:
		default:
		}

		c.reset <- r
		c.update <- r
	}

	return nil
}

func (b *fadeInBackend) close() {
	for _, i := range b.instances {
		i.server.Close()
	}
}

func (p *fadeInProxyInstance) close() {
	p.server.Close()
	p.proxy.Close()
}

// startProxy starts a proxy representing 0 or more proxy instances, added in a separate step.
func startProxy(t *testing.T, b *fadeInBackend) *fadeInProxy {
	return &fadeInProxy{
		test:    t,
		mx:      &sync.Mutex{},
		backend: b,
	}
}

func (p *fadeInProxy) addInstances(n int) {
	p.mx.Lock()
	defer p.mx.Unlock()

	for i := 0; i < n; i++ {
		client := p.backend.createDataClient()
		fr := make(filters.Registry)
		fr.Register(fadein.NewFadeIn())
		fr.Register(fadein.NewEndpointCreated())
		rt := routing.New(routing.Options{
			FilterRegistry: fr,
			DataClients:    []routing.DataClient{client},
			PostProcessors: []routing.PostProcessor{
				loadbalancer.NewAlgorithmProvider(),
				fadein.NewPostProcessor(),
			},
		})

		px := proxy.WithParams(proxy.Params{
			Routing: rt,
		})

		s := httptest.NewServer(px)
		p.instances = append(p.instances, &fadeInProxyInstance{
			proxy:  px,
			server: s,
		})
	}
}

func (p *fadeInProxy) endpoints() []string {
	p.mx.Lock()
	defer p.mx.Unlock()

	var ep []string
	for _, i := range p.instances {
		ep = append(ep, i.server.URL)
	}

	return ep
}

func (p *fadeInProxy) close() {
	p.mx.Lock()
	defer p.mx.Unlock()

	for _, i := range p.instances {
		i.close()
	}
}

// startClient starts a client continously polling the available proxy instances.
// The distribution of the requests across the available backend endpoints and in
// time is measured the by the client.
func startClient(test *testing.T, p *fadeInProxy) *fadeInClient {
	c := &fadeInClient{
		test:               test,
		proxy:              p,
		httpClient:         &http.Client{},
		statRequests:       make(chan chan []stat),
		resetStatsRequests: make(chan struct{}),
		quit:               make(chan struct{}),
	}

	go c.run()
	return c
}

func (c *fadeInClient) run() {
	var (
		counter      int
		stats        []stat
		statRequests []chan []stat
	)

	for {
		proxyEndpoints := c.proxy.endpoints()
		var requestStart time.Time
		if len(proxyEndpoints) > 0 {
			endpoint := proxyEndpoints[counter%len(proxyEndpoints)]
			counter++

			requestStart = time.Now()
			if rsp, err := c.httpClient.Get(endpoint); err != nil {
				stats = append(stats, stat{
					timestamp: requestStart,
					err:       err,
				})
			} else {
				rsp.Body.Close()
				stats = append(stats, stat{
					timestamp: requestStart,
					status:    rsp.StatusCode,
					endpoint:  rsp.Header.Get("X-Backend-Endpoint"),
				})
			}
		}

		for _, sr := range statRequests {
			sr <- stats
		}

		var nextRequest <-chan time.Time
		if !requestStart.IsZero() {
			nextRequest = time.After(clientRate - time.Since(requestStart))
		} else {
			nextRequest = time.After(clientRate)
		}

		statRequests = nil
		select {
		case sr := <-c.statRequests:
			statRequests = append(statRequests, sr)
		case <-c.resetStatsRequests:
			stats = nil
		case <-c.quit:
			return
		case <-nextRequest:
		}
	}
}

func (c *fadeInClient) getStats() []stat {
	ch := make(chan []stat, 1)
	c.statRequests <- ch
	return <-ch
}

func (c *fadeInClient) resetStats() {
	c.resetStatsRequests <- struct{}{}
}

func (c *fadeInClient) warmUpD(d time.Duration) {
	time.Sleep(d)
	c.resetStats()
}

func (c *fadeInClient) warmUp() {
	c.warmUpD(testFadeInDuration)
}

func (c *fadeInClient) close() {
	close(c.quit)
}

func trimFailed(s []stat) []stat {
	for i := range s {
		if s[i].status >= 200 && s[i].status < 300 {
			return s[i:]
		}
	}

	return nil
}

func checkSuccess(t *testing.T, s []stat) {
	var foundAny bool
	for _, si := range s {
		foundAny = true
		if si.status != http.StatusOK || si.endpoint == "" {
			t.Fatalf(
				"Failed request to: '%s', with status: %d.",
				si.endpoint,
				si.status,
			)
		}
	}

	if !foundAny {
		t.Fatal("Failed to generate stats.")
	}
}

func mapStats(s []stat) map[string][]stat {
	m := make(map[string][]stat)
	for _, si := range s {
		m[si.endpoint] = append(m[si.endpoint], si)
	}

	return m
}

func statBuckets(s []stat) [][]stat {
	start := s[0].timestamp
	finish := s[len(s)-1].timestamp
	duration := finish.Sub(start)
	timeStep := duration / statBucketCount
	nextBucketStart := start.Add(timeStep)

	var (
		buckets [][]stat
		current []stat
	)

	for _, si := range s {
		for si.timestamp.After(nextBucketStart) && len(buckets) < statBucketCount-1 {
			buckets = append(buckets, current)
			current = nil
			nextBucketStart = nextBucketStart.Add(timeStep)
		}

		current = append(current, si)
	}

	buckets = append(buckets, current)
	return buckets
}

func bucketSizes(b [][]stat) []float64 {
	var sizes []float64
	for _, bi := range b {
		sizes = append(sizes, float64(len(bi)))
	}

	return sizes
}

func checkSamples(t *testing.T, s []stat) {
	if len(s) < minStats {
		t.Fatalf("No sufficient stats: %d, expected at least: %d.", len(s), minStats)
	}
}

func checkEndpointFadeIn(t *testing.T, s []stat) {
	checkSamples(t, s)
	buckets := statBuckets(s)
	sizes := bucketSizes(buckets)
	if sizes[0] >= sizes[len(sizes)/2] || sizes[len(sizes)/2] >= sizes[len(sizes)-1] {
		t.Fatal("Failed to fade-in.")
	}
}

func lessOrEqWithTolerance(left, right float64) bool {
	t := (left + right) * fadeInTolerance / 2
	return left < right+t
}

func checkStableOrDecrease(t *testing.T, s []stat) {
	checkSamples(t, s)
	buckets := statBuckets(s)
	sizes := bucketSizes(buckets)
	if !lessOrEqWithTolerance(sizes[len(sizes)/2], sizes[0]) ||
		!lessOrEqWithTolerance(sizes[len(sizes)-1], sizes[len(sizes)/2]) {
		t.Fatal("Unexpected increase.")
	}
}

func checkFadeIn(t *testing.T, u []string, stats []stat, doFade []bool) {
	checkSuccess(t, stats)
	statsByEndpoint := mapStats(stats)
	for i := range u {
		if i < len(doFade) && doFade[i] {
			checkEndpointFadeIn(t, statsByEndpoint[u[i]])
		} else if i < len(doFade) {
			checkStableOrDecrease(t, statsByEndpoint[u[i]])
		}
	}
}

func endpointStartTest(
	proxies, initialEndpoints, addEndpoints int,
	withFadeIn, withCreated bool,
	expectFadeIn ...bool,
) func(*testing.T) {
	return func(t *testing.T) {
		b := startBackend(t, withFadeIn, withCreated)
		defer b.close()

		initial := randomURLs(t, initialEndpoints)
		if err := b.addInstances(initial...); err != nil {
			t.Fatal(err)
		}

		p := startProxy(t, b)
		defer p.close()
		p.addInstances(proxies)

		c := startClient(t, p)
		defer c.close()
		c.warmUp()

		add := randomURLs(t, addEndpoints)
		b.addInstances(add...)

		time.Sleep(testFadeInDuration)
		stats := c.getStats()
		stats = trimFailed(stats)
		checkFadeIn(t, append(initial, add...), stats, expectFadeIn)
	}
}

func sub(title string, tests ...func(*testing.T)) func(*testing.T) {
	return func(t *testing.T) {
		t.Run(title, func(t *testing.T) {
			for _, test := range tests {
				test(t)
			}
		})
	}
}

func run(t *testing.T, title string, tests ...func(*testing.T)) {
	sub(title, tests...)(t)
}

package platformclientv2

import (
	"bytes"
	"net"
	"net/http"
	"sync/atomic"
	"testing"
	"time"

	"github.com/hashicorp/go-retryablehttp"
)

func TestClientRetry(t *testing.T) {
	testRetryErrorCode(t, http.StatusTooManyRequests)

	// retryablehttp retries all 500 codes except for 501, we'll test the first 10 for brevity
	for code := http.StatusInternalServerError; code <= http.StatusNotExtended; code++ {
		if code == http.StatusNotImplemented {
			continue
		}
		testRetryErrorCode(t, code)
	}
}

func TestClientDoNotRetry(t *testing.T) {
	testDoNotRetryErrorCode(t, http.StatusTooManyRequests)

	// retryablehttp retries all 500 codes except for 501, we'll test the first 10 for brevity
	for code := http.StatusInternalServerError; code <= http.StatusNotExtended; code++ {
		if code == http.StatusNotImplemented {
			continue
		}
		testDoNotRetryErrorCode(t, code)
	}
}

func testRetryErrorCode(t *testing.T, errorCode int) {
	// Test implementation adapted from https://github.com/hashicorp/go-retryablehttp/blob/master/client_test.go
	// Track the number of times the logging hook was called
	retryCount := -1
	hook := func(logger retryablehttp.Logger, req *http.Request, retryNumber int) {
		retryCount = retryNumber
	}

	APIClient := NewAPIClient(&Configuration{})
	APIClient.client.RetryWaitMin = 10 * time.Millisecond
	APIClient.client.RetryWaitMax = 50 * time.Millisecond
	APIClient.client.RetryMax = 50
	APIClient.client.RequestLogHook = hook

	// Create a request
	testBytes := []byte("hello")
	req, err := retryablehttp.NewRequest("GET", "http://127.0.0.1:28934/v1/foo", bytes.NewReader(testBytes))
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	// Send the request
	var resp *http.Response
	doneCh := make(chan struct{})
	go func() {
		defer close(doneCh)
		var err error
		resp, err = APIClient.client.Do(req)
		if err != nil {
			t.Fatalf("err: %v", err)
		}
	}()

	select {
	case <-doneCh:
		t.Fatalf("should retry on error")
	case <-time.After(200 * time.Millisecond):
		// Client should still be retrying due to connection failure.
	}

	// Create the mock handler. First we return error responses to ensure
	// that we power through and keep retrying in the face of recoverable
	// errors.
	code := int64(errorCode)
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(int(atomic.LoadInt64(&code)))
	})

	// Create a test server
	list, err := net.Listen("tcp", ":28934")
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	defer list.Close()
	go http.Serve(list, handler)

	// Wait again
	select {
	case <-doneCh:
		t.Fatalf("should retry on error codes")
	case <-time.After(200 * time.Millisecond):
		// Client should still be retrying due to error codes.
	}

	// Start returning 200's
	atomic.StoreInt64(&code, http.StatusOK)

	// Wait again
	select {
	case <-doneCh:
	case <-time.After(time.Second):
		t.Fatalf("timed out")
	}

	if resp.StatusCode != http.StatusOK {
		t.Fatalf("exected %v, got: %d", http.StatusOK, resp.StatusCode)
	}

	if retryCount < 0 {
		t.Fatal("request log hook was not called")
	}
}

func testDoNotRetryErrorCode(t *testing.T, errorCode int) {
	// Test implementation adapted from https://github.com/hashicorp/go-retryablehttp/blob/master/client_test.go
	// Track the number of times the logging hook was called
	retryCount := -1
	hook := func(logger retryablehttp.Logger, req *http.Request, retryNumber int) {
		retryCount = retryNumber
	}

	APIClient := NewAPIClient(&Configuration{})
	APIClient.client.RetryWaitMax = 0
	APIClient.client.RetryMax = 0
	APIClient.client.RequestLogHook = hook

	// Create a request
	testBytes := []byte("hello")
	req, _ := retryablehttp.NewRequest("GET", "http://127.0.0.1:28934/v1/foo", bytes.NewReader(testBytes))
	// Send the request
	doneCh := make(chan struct{})
	go func() {
		defer close(doneCh)
		var err error
		_, err = APIClient.client.Do(req)
		if err == nil {
			t.Fatalf("expected error response")
		}
	}()

	select {
	case <-doneCh:
		//no-op
	case <-time.After(200 * time.Millisecond):
		t.Fatalf("should not retry on error")
	}

	// Create the mock handler. First we return error responses to ensure
	// that we power through and keep retrying in the face of recoverable
	// errors.
	code := int64(errorCode)
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(int(atomic.LoadInt64(&code)))
	})

	// Create a test server
	list, err := net.Listen("tcp", ":28934")
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	defer list.Close()
	go http.Serve(list, handler)

	// Wait again
	select {
	case <-doneCh:
		//no-op
	case <-time.After(200 * time.Millisecond):
		t.Fatalf("should not retry on error")
	}

	// Start returning 200's
	atomic.StoreInt64(&code, http.StatusOK)

	// Wait again
	select {
	case <-doneCh:
	case <-time.After(time.Second):
		t.Fatalf("timed out")
	}

	if retryCount > 0 {
		t.Fatal("request log hook should not have been called")
	}
}

package main

import (
	"fmt"
	"log"
	"net"
	"time"

	helloworldpb "github.com/MickiFoerster/protobuf/hello_world/protoc-helloworld"
	proto "github.com/golang/protobuf/proto"
)

func main() {
	fmt.Println("proto buf hello world")
	go client()
	server_done := server()
	<-server_done
}

func server() chan struct{} {
	ch := make(chan struct{})
	go func() {
		listener, err := net.Listen("tcp", ":12345")
		if err != nil {
			log.Fatalf("error: Could not create passive socket: %v\n", err)
		}
		defer listener.Close()
		fmt.Println("servers listens on ", listener.Addr())
		for {
			conn, err := listener.Accept()
			if err != nil {
				log.Println("error: could not accept client connection: %v\n", err)
			}
			go handleConnection(conn)
		}
		ch <- struct{}{}
	}()
	return ch
}

func handleConnection(conn net.Conn) {
	log.Println("Received client connection:")
	log.Printf("local address: %v\n", conn.LocalAddr())
	log.Printf("remote address: %v\n", conn.RemoteAddr())

	buf := make([]byte, 4096)
	n, err := conn.Read(buf)
	if err != nil {
		log.Fatalf("error: could not read from connection: %v\n", err)
	}
	log.Println(n, "bytes have been read from connection")

	msg := &helloworldpb.HelloWorld{}
	err = proto.Unmarshal(buf[:n], msg)
	if err != nil {
		log.Println("unmarshal() data failed")
	}
	log.Println("unmarshaling succeeded")
	fmt.Println(msg.GetId())
	fmt.Println(msg.GetMessage())
	for _, i := range msg.GetRandomNumber() {
		fmt.Print(i, " ")
	}
	fmt.Println()

	log.Printf("closing connection ... ")
	err = conn.Close()
	if err != nil {
		log.Printf("error: could not close connection: %v\n", err)
	}
	log.Println("done")
}

func client() {
	var id int32 = 23
	numbers := []int32{2, 3, 5, 7, 11, 13, 17, 19}
	for {
		msg := &helloworldpb.HelloWorld{
			Id:           id,
			Message:      "Primzahlen",
			RandomNumber: numbers,
		}
		fmt.Println("client:", msg)
		time.Sleep(time.Second)
		conn, err := net.Dial("tcp", "localhost:12345")
		if err != nil {
			log.Fatalf("error: could not create client connection: %v\n", err)
		}
		log.Println("client connection established")

		data, err := proto.Marshal(msg)
		if err != nil {
			log.Fatalf("error: could not serialize message: %v\n", err)
		}
		log.Println("protobuf message has been marshalled")

		n, err := conn.Write(data)
		if err != nil {
			log.Fatalf("error: could not write message to connection", err)
		}
		log.Println(n, "bytes have been written. Now close the connection.")
		conn.Close()
		id = (id * 1333) % 1335
	}
}

