}

func (c *FakeConnectionProvider) ProvideConnection() (*warden.Connection, error) {
	return warden.NewConnection(
		&fakeConn{
			ReadBuffer:  c.ReadBuffer,
			WriteBuffer: c.WriteBuffer,
