package test

import (
	"crypto/tls"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
	"strings"
	"testing"
	"time"

	"github.com/gruntwork-io/terratest/modules/helm"
	http_helper "github.com/gruntwork-io/terratest/modules/http-helper"
	"github.com/gruntwork-io/terratest/modules/k8s"
	"github.com/gruntwork-io/terratest/modules/random"
	"github.com/stretchr/testify/require"
	v1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/labels"
)

type CoreReleases struct {
	Order    []string
	Releases map[string]Release
}

func NewCoreReleases() *CoreReleases {
	var cr CoreReleases
	cr.Releases = make(map[string]Release)
	return &cr
}

func (cr *CoreReleases) SetOrder(order []string) {
	cr.Order = order
}

func (cr *CoreReleases) AddRelease(r Release) {
	cr.Releases[r.Name] = r
	if _, found := find(cr.Order, r.Name); !found {
		cr.Order = append(cr.Order, r.Name)
	}
}

/*
Name: chart name
ReleaseName: <chart name>-rand (rand generated if not provided)
ExpectedPodCount: num of pods created by release
ChartPath: local relative path
LabelKey: "greymatter"
LabelValue: chart name
labelsToFind: will check against keys deploymet,statefulset, daemonset for the label value set here
PodsToWaitFor: after install tests will check to ensure these pods are up before continuing to validate release (i think this is redundant)
Namespace: Namespace resources will be deployed to.  Defaults to "default"
KubectlOptions: defaults to current context however if Namespace is non-default the kubectlOption will be set to that
Filters: Filters for searching for only this pod
*/
type Release struct {
	Name             string
	ReleaseName      string
	ExpectedPodCount int
	ChartPath        string
	LabelKey         string
	LabelValue       string
	LabelsToFind     []string
	PodsToWaitFor    []string
	Namespace        string
	KubectlOptions   *k8s.KubectlOptions
	Filters          metav1.ListOptions
}

func NewRelease(name, rand, chartPath, labelKey, labelValue, namespace string, expectedPodCount int, labelsToFind []string, podsToWaitFor []string) Release {
	r := Release{
		Name:             name,
		ChartPath:        chartPath,
		LabelKey:         labelKey,
		LabelValue:       labelValue,
		ExpectedPodCount: expectedPodCount,
		LabelsToFind:     labelsToFind,
		KubectlOptions:   k8s.NewKubectlOptions("", "", namespace),
		PodsToWaitFor:    podsToWaitFor,
	}
	if rand == "" {
		rand = strings.ToLower(random.UniqueId())
	}
	r.ReleaseName = fmt.Sprintf("%s-%s", name, rand)

	if namespace != "" {
		r.Namespace = namespace
		r.KubectlOptions = k8s.NewKubectlOptions("", "", namespace)
	} else {
		r.Namespace = "default"
		r.KubectlOptions = k8s.NewKubectlOptions("", "", r.Namespace)
	}

	labelSelector := metav1.LabelSelector{MatchLabels: map[string]string{r.LabelKey: r.LabelValue}}
	r.Filters = metav1.ListOptions{
		LabelSelector: labels.Set(labelSelector.MatchLabels).String(),
		Limit:         100,
	}
	//the spire agent dymanically provisions agents based on the number of nodes in a cluster (daemonset)

	return r
}

func GetNodeCount(t *testing.T, kubectlOptions *k8s.KubectlOptions) int {
	return len(k8s.GetNodes(t, kubectlOptions))

}

func helmCleanAndDepUp(r Release, options *helm.Options, t *testing.T) (bool, error) {
	chartsPath := fmt.Sprintf("%s/charts", r.ChartPath)
	//clean path
	err := os.RemoveAll(chartsPath)
	if err != nil {

		t.Error("helmCleanAndDepUp: path does not exist or there were errors")
		return false, err
	}

	//dep up
	if _, err := helm.RunHelmCommandAndGetOutputE(t, options, "dependency", "update", r.ChartPath); err != nil {
		require.NoError(t, err)
		return false, err
	}
	return true, nil
}

//dep up and install
func DeployRelease(r Release, options *helm.Options, t *testing.T) (bool, error) {

	if _, err := helmCleanAndDepUp(r, options, t); err != nil {
		t.Errorf("There was an issue cleaning charts dir and dep up %s", r.Name)
	}

	//determine if waiter sa exists in ns
	saName := "greymatter-waiter"
	_, err := k8s.GetServiceAccountE(t, r.KubectlOptions, saName)
	if err != nil {
		t.Logf("Did not find [%s] in namespace [%s]", saName, r.Namespace)
	} else {
		t.Logf("Found [%s]] in namespace [%s].  Appending helm command", saName, r.Namespace)
		setValuesMap := options.SetValues
		setValuesMap["global.waiter.service_account.create"] = "false"
		options = &helm.Options{
			ValuesFiles: options.ValuesFiles,
			SetValues:   setValuesMap,
		}
	}

	//Create needed namespaces
	if r.Namespace != "default" {
		if _, err := k8s.GetNamespaceE(t, r.KubectlOptions, r.Namespace); err != nil {
			t.Logf("Namespace [%s] Not Found.\n %s", r.Namespace, err)
		} else {
			t.Logf("Namespace %s was found.", r.Namespace)
			deleteNamespace(r.Namespace, t, r.KubectlOptions)
		}
		createNamespace(r.Namespace, t, r.KubectlOptions)
	}

	//install
	t.Logf("Installing [%s] Chart", r.ReleaseName)
	if err := helm.InstallE(t, options, r.ChartPath, r.ReleaseName); err != nil {
		t.Errorf("Error installing %s Chart \n %s", r.ReleaseName, err)
		t.FailNow()
		return false, err
	}
	t.Logf("Installed [%s] Chart", r.ReleaseName)
	return true, nil
}

//default check release
//- pod count
//- pod labels
//- pods to wait for
func CheckRelease(r Release, options *helm.Options, t *testing.T) (bool, error) {

	if len(r.PodsToWaitFor) > 0 {
		retries := 18
		sleep := 10 * time.Second
		for _, podName := range r.PodsToWaitFor {
			if err := k8s.WaitUntilPodAvailableE(t, r.KubectlOptions, podName, retries, sleep); err != nil {
				t.Errorf("Error waiting on pod [%s] \n%s", podName, err)
			}
		}
	}

	// Wait for the pod to come up. It takes some time for the Pod to start, so retry a few times.
	retries := 15
	sleep := 5 * time.Second
	fmt.Printf("%#v\n", r.KubectlOptions)
	k8s.WaitUntilNumPodsCreated(t, r.KubectlOptions, r.Filters, r.ExpectedPodCount, retries, sleep)

	if VerifyPods(t, r.KubectlOptions, r.ExpectedPodCount, r.Filters, r.LabelsToFind) == false {
		t.Error("Expected fabric verifyPods to pass but it did not")
		t.FailNow()
	}
	return true, nil
}

//returns name of release and error if there is a problem
func DeleteRelease(r Release, helmOptions *helm.Options, t *testing.T) (string, error) {
	if err := helm.DeleteE(t, helmOptions, r.ReleaseName, true); err != nil {
		t.Errorf("Error Tearing down %s \n %s", r.ReleaseName, err)
		return r.ReleaseName, err
	}
	//Delete needed namespaces
	if r.Namespace != "default" {
		deleteNamespace(r.Namespace, t, r.KubectlOptions)
	}

	return r.ReleaseName, nil
}

// verifyPods will verify that expected pods are running
func VerifyPods(t *testing.T, kubectlOptions *k8s.KubectlOptions, expectedPodCount int, filters metav1.ListOptions, labelsToFind []string) bool {

	var pods []v1.Pod
	pods, err := k8s.ListPodsE(t, kubectlOptions, filters)
	if err != nil {
		t.Errorf("Error List Pods \n %s", err)
		t.FailNow()
	}

	retries := 18
	sleep := 10 * time.Second
	for _, pod := range pods {
		if err := k8s.WaitUntilPodAvailableE(t, kubectlOptions, pod.Name, retries, sleep); err != nil {
			t.Errorf("Pod [%s] in unavalible.  \n%s", pod.Name, err)
			description, err := k8s.RunKubectlAndGetOutputE(t, kubectlOptions, "describe", "pod", pod.Name)
			if err != nil {
				t.Errorf("Issue getting description of pod [%s]: \n %s", pod.Name, err)
			} else {
				t.Logf("Pod [%s] Described:\n %s", pod.Name, description)
			}
			nodes, err := k8s.RunKubectlAndGetOutputE(t, kubectlOptions, "describe", "nodes")
			if err != nil {
				t.Errorf("Issue getting description of nodes:")
			} else {
				t.Logf("Nodes Described:\n %s", nodes)
			}
			t.FailNow()
		}
	}

	if len(labelsToFind) > 0 {
		//get all the values for the labels
		var foundPodLabels []string
		for _, pod := range pods {
			fmt.Println("Pod: ", pod.Name)
			if val, ok := pod.Labels["deployment"]; ok {
				foundPodLabels = append(foundPodLabels, val)
			}
			if val, ok := pod.Labels["statefulset"]; ok {
				foundPodLabels = append(foundPodLabels, val)
			}
			if val, ok := pod.Labels["daemonset"]; ok {
				foundPodLabels = append(foundPodLabels, val)
			}
		}
		for _, val := range labelsToFind {
			_, found := find(foundPodLabels, val)
			if found == false {
				return false
			}
		}
	}
	return true
}

func find(slice []string, val string) (int, bool) {
	for i, item := range slice {
		if item == val {
			fmt.Printf("Found %s in %s", val, slice)
			return i, true
		}
	}
	fmt.Printf("NOT Found %s in %s", val, slice)
	return -1, false
}

func createNamespace(name string, t *testing.T, kubectlOptions *k8s.KubectlOptions) {
	t.Logf("Creating Namespace [%s]", name)
	if err := k8s.CreateNamespaceE(t, kubectlOptions, name); err != nil {
		t.Errorf("Error creating namespace %s\n %s", name, err)
		t.FailNow()
	}
	t.Logf("Created Namespace [%s]", name)
}

func deleteNamespace(name string, t *testing.T, kubectlOptions *k8s.KubectlOptions) {
	t.Logf("Deleting Namespace [%s]", name)
	if err := k8s.DeleteNamespaceE(t, kubectlOptions, name); err != nil {
		t.Errorf("Error Deleting namespace %s \n %s", name, err)
		t.FailNow()
	}
	if _, err := k8s.RunKubectlAndGetOutputE(t, kubectlOptions, "wait", "--for=delete", "namespace", name, "--timeout=120s"); err != nil {
		t.Logf("There was an issue deleting namespace [%s]", name)
		t.FailNow()
	}
	t.Logf("Deleted Namespace [%s]", name)
}

func extractCerts(t *testing.T, kubectlOptions *k8s.KubectlOptions, secret string) {
	userCertSecret := k8s.GetSecret(t, kubectlOptions, secret)
	err := ioutil.WriteFile("../tls.crt", userCertSecret.Data["tls.crt"], 0644)
	if err != nil {
		t.Error(err)
		t.FailNow()
	}

	err = ioutil.WriteFile("../tls.key", userCertSecret.Data["tls.key"], 0644)
	if err != nil {
		t.Error(err)
		t.FailNow()
	}

	err = ioutil.WriteFile("../ca.crt", userCertSecret.Data["ca.crt"], 0644)
	if err != nil {
		t.Error(err)
		t.FailNow()
	}
}

func verifyCatalog(t *testing.T, kubectlOptions *k8s.KubectlOptions, expectedCatalogCount int) {

	// Setup a TLS configuration to submit with the helper, a blank struct is acceptable
	certPem, err := ioutil.ReadFile("../tls.crt")
	if err != nil {
		t.Error(err)
		t.FailNow()
	}
	keyPem, err := ioutil.ReadFile("../tls.key")
	if err != nil {
		t.Error(err)
		t.FailNow()
	}

	cert, err := tls.X509KeyPair(certPem, keyPem)
	if err != nil {
		t.Error(err)
		t.FailNow()
	}

	tlsConfig := tls.Config{
		Certificates:       []tls.Certificate{cert},
		InsecureSkipVerify: true,
	}

	// The Edge node requires a bit of time to get configured and we've seen issues where it will die before it' ready. This adds a sleep for 30 seconds to give it time to serve requests
	time.Sleep(30 * time.Second)

	// Define the path to the catalog service
	catalogEndpoint := "https://localhost:30000/services/catalog/latest/summary"

	http_helper.HttpGetWithRetryWithCustomValidation(
		t,
		catalogEndpoint,
		&tlsConfig,
		30,
		10*time.Second,
		func(statusCode int, body string) bool {
			// fmt.Println("Catalog Summary:", body)

			var data map[string]interface{}
			json.Unmarshal([]byte(body), &data)
			metadata, _ := data["metadata"].(map[string]interface{})

			foundCatalogCount := metadata["service_count"]

			return foundCatalogCount == float64(expectedCatalogCount)
		},
	)
}

