 * This function validates that the URL only points to the expected cluster
 * leader host and one of the allowed API paths, preventing server-side
 * request forgery via tampered external input.
 */
func validateClusterURL(raw, leader string) error {
	u, err := url.Parse(raw)
	if err != nil {
		return errors.New(fmt.Sprintf("chubaofs: failed to parse url(%v) err(%v)", raw, err))
	}
	if u.Scheme != "http" || u.Hostname() == "" || u.Host != leader {
		return errors.New(fmt.Sprintf("chubaofs: url host(%v) does not match expected leader(%v)", u.Host, leader))
	}
	allowedPaths := map[string]bool{
		"/admin/createVol": true,
		"/vol/delete":      true,
	}
	if !allowedPaths[u.Path] {
		return errors.New(fmt.Sprintf("chubaofs: url path(%v) is not allowed", u.Path))
	}
	return nil
}

