// isAllowedRequestURL validates a URL to prevent SSRF: it must be an
// absolute HTTP(S) URL with no userinfo component and no fragment.
func isAllowedRequestURL(rawURL string) bool {
	u, err := url.Parse(rawURL)
	if err != nil {
		return false
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return false
	}
	if u.Host == "" {
		return false
	}
	if u.User != nil {
		return false
	}
	if u.Fragment != "" {
		return false
	}
	return true
}

