							CreateTime: time.Time{},
						})
					}
					cSubStreet = 0
					dCode := fmt.Sprintf("%s01", c.AdCode[:len(c.AdCode)-2])
					if j < 9 {
						dCode = fmt.Sprintf("%s0%d", dCode, j+1)
					} else {
						dCode = fmt.Sprintf("%s%d", dCode, j+1)
					}
					toWriteArea = append(toWriteArea, &areaDBModel{
						Code:       dCode,
						Name:       d.Name,
						Center:     d.Center,
						ParentCode: fmt.Sprintf("%s0100", c.AdCode[:len(c.AdCode)-2]),
						ParentName: fmt.Sprintf("%s区", c.Name),
						CreateTime: time.Time{},
					})
				} else {
					if cSubStreet == 0 {
						// https://lbs.amap.com/api/webservice/guide/api/district:
						// 目前部分城市和省直辖县因为没有区县的概念，故在市级下方直接显示街道。例如：广东-东莞、海南-文昌市。
						return nil, fmt.Errorf("both street and district under %s", c.Name)
					}
					cSubStreet = 1
					dCode := fmt.Sprintf("%s00", d.AdCode)
					toWriteArea = append(toWriteArea, &areaDBModel{
						Code:       dCode,
						Name:       d.Name,
						Center:     d.Center,
						ParentCode: cCode,
						ParentName: c.Name,
						CreateTime: time.Time{},
					})
					for i, s := range d.Districts {
						// 街道级
						sCode := s.AdCode
						if i < 9 {
							sCode = fmt.Sprintf("%s0%d", sCode, i+1)
						} else {
							sCode = fmt.Sprintf("%s%d", sCode, i+1)
						}
						toWriteArea = append(toWriteArea, &areaDBModel{
							Code:       sCode,
							Name:       s.Name,
							Center:     s.Center,
							ParentCode: dCode,
							ParentName: d.Name,
							CreateTime: time.Time{},
						})
					}
				}
			}
		}
	}
	return toWriteArea, nil
}
func initDBEnv(dbInfo *ezMySQL.Info) (*xorm.Engine, error) {
	if dbInfo.PasswordBase64Str == "" {
		return nil, fmt.Errorf("empty password base64 str")
	}
	password, err := ezPasswordEncoder.GetPasswordFromEncodedStr(dbInfo.PasswordBase64Str)
	if err != nil {
		return nil, err
	}
	eng, err := xorm.NewEngine("mysql", fmt.Sprintf("%s:%s@tcp(%s:%s)/%s?charset=utf8",
		dbInfo.Account, password, dbInfo.Host, dbInfo.Port, dbInfo.DatabaseName))
	if err != nil {
		return nil, fmt.Errorf("db engine init failed ,err:%s", err.Error())
	}
	loc, _ := time.LoadLocation("Asia/Shanghai")
	eng.SetTZLocation(loc)
	eng.SetTZDatabase(loc)
	err = eng.Sync2(&areaDBModel{})
	if err != nil {
		return nil, err
	}
	return eng, nil
}

