func register(addr, path string, i interface{}) error {

	b, err := json.Marshal(i)
	if err != nil {
		return err
	}
	url := fmt.Sprintf("http://%s%s", addr, path)
	req, err := http.NewRequest("PUT", url, bytes.NewBuffer(b))
	if err != nil {
		return err
