var allowedProxyHosts = map[string]bool{
	"xicidaili.com": true,
	"www.xicidaili.com": true,
}

// validateProxyURL parses rawURL and allows the request only when the scheme
// is http/https, the host is in the allow-list, and the host is not an
// internal (private/loopback/link-local) IP address.
func validateProxyURL(rawURL string) error {
	u, err := url.Parse(rawURL)
	if err != nil {
		return err
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return errors.New("only http and https schemes are allowed")
	}
	host := u.Hostname()
	if !allowedProxyHosts[host] {
		return errors.New("host is not in the allowed list")
	}
	if ip := net.ParseIP(host); ip != nil {
		if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
			return errors.New("internal network addresses are not allowed")
		}
	}
	return nil
}

