// validateUrl validates the target URL to prevent SSRF.
func validateUrl(rawURL string) (string, error) {
	u, err := url.Parse(rawURL)
	if err != nil {
		return "", err
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return "", fmt.Errorf("invalid url scheme: %s", u.Scheme)
	}
	host := u.Hostname()
	if host == "" {
		return "", fmt.Errorf("invalid url host")
	}
	// Allow only domain names / IPv4; block internal hosts (loopback,
	// link-local, private networks, metadata endpoints) to prevent SSRF.
	if host == "localhost" {
		return "", fmt.Errorf("invalid url host: localhost")
	}
	if ip := net.ParseIP(host); ip != nil {
		if ip.IsLoopback() || ip.IsLinkLocalUnicast() || ip.IsPrivate() {
			return "", fmt.Errorf("invalid url host: private or internal address")
		}
	}
	return rawURL, nil
}

func (red *RedLineClient) GetApiVersion() (error, string) {
	postUrl := fmt.Sprintf("http://%v/master/redlineSimpleVersion", red.EndPoints)
	safeUrl, err := validateUrl(postUrl)
	if err != nil {
		log.Errorf("GetApiVersion: invalid url %s err %s", postUrl, err)
		return fmt.Errorf("Failed to request %s err %s ", postUrl, err.Error()), ""
	}
	requestBody := "{}"
	httpReq, err := http.NewRequest("GET", safeUrl, strings.NewReader(requestBody))

