package alert

import (
	"crypto/md5"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

var bufPool = sync.Pool{}

func getBuf() []byte {
	b := bufPool.Get()
	if b == nil {
		return make([]byte, 0, 1024)
	}
	return b.([]byte)
}

func putBuf(b []byte) {
	b = b[:0]
	bufPool.Put(b)
}

func (a *Alert) names() []string {
	ret := make([]string, 0, len(a.Labels))

	for k := range a.Labels {
		ret = append(ret, k)
	}

	sort.Strings(ret)

	return ret
}

// Hash returns an md5 hash from alert labels.
func (a *Alert) Hash() [16]byte {
	b := getBuf()
	defer putBuf(b)

	for _, k := range a.names() {
		b = append(b, k...)
		b = append(b, a.Labels[k]...)
	}

	return md5.Sum(b)
}

func truncate(t time.Duration) time.Duration {
	return t - t%time.Second
}

func (a *Alert) Since() time.Duration {
	return truncate(time.Now().UTC().Sub(a.StartsAt))
}

func (a *Alert) Lasted() time.Duration {
	return truncate(a.EndsAt.Sub(a.StartsAt))
}

// SetCurrent sets the current expected responder for alert to i atomically.
func (a *Alert) SetCurrent(i int) {
	atomic.StoreInt32(&a.current, int32(i))
}

// Current returns the current expected responder for alert atomically.
func (a *Alert) Current() int {
	return int(atomic.LoadInt32(&a.current))
}

// AllFail returns true when SetAllFail has been called.
func (a *Alert) AllFail() bool {
	return atomic.LoadInt32(&a.allfail) == 1
}

// SetAllFails sets status to allfailed.
func (a *Alert) SetAllFail() {
	atomic.StoreInt32(&a.allfail, 1)
}

package merkletree

// xlattice_go/util/merkletree/merkletree.go

import (
	"crypto/sha1"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	xu "github.com/jddixon/xlUtil_go"
	xf "github.com/jddixon/xlUtil_go/lfs"
	"golang.org/x/crypto/sha3"
	"io/ioutil"
)

var _ = fmt.Print

type MerkleLeaf struct {
	MerkleNode
}

// Creates a MerkleTree leaf node.

func NewMerkleLeaf(name string, hash []byte, whichSHA int) (
	ml *MerkleLeaf, err error) {

	mn, err := NewMerkleNode(name, hash, whichSHA)
	if err == nil {
		ml = &MerkleLeaf{*mn}
	}
	return
}

// Create a MerkleTree leaf node corresponding to a file in the file
// system.  To simplify programming, the base name of the file, which is
// part of the path, is also passed as a separate argument.

func CreateMerkleLeafFromFileSystem(pathToFile, name string, whichSHA int) (
	ml *MerkleLeaf, err error) {

	var hash []byte
	if whichSHA == xu.USING_SHA1 {
		hash, err = SHA1File(pathToFile)
	} else if whichSHA == xu.USING_SHA2 {
		hash, err = SHA2File(pathToFile)
	} else {
		hash, err = SHA3File(pathToFile)
	}
	if err == nil {
		ml, err = NewMerkleLeaf(name, hash, whichSHA)
	}
	return
}
func (ml *MerkleLeaf) IsLeaf() bool {
	return true
}
func (ml *MerkleLeaf) Equal(any interface{}) bool {
	if any == ml {
		return true
	}
	if any == nil {
		return false
	}
	switch v := any.(type) {
	case *MerkleLeaf:
		_ = v
	default:
		return false
	}
	other := any.(*MerkleLeaf) // type assertion
	myNode := &ml.MerkleNode
	return myNode.Equal(&other.MerkleNode)
}

// Serialize the leaf node, prefixing it with 'indent', which should
// conventionally be a number of spaces.

func (ml *MerkleLeaf) ToString(indent, deltaIndent string) (
	str string, err error) {

	var shash string
	hash := ml.hash
	if len(hash) == 0 {
		switch ml.whichSHA {
		case xu.USING_SHA1:
			shash = SHA1_NONE
		case xu.USING_SHA2:
			shash = SHA2_NONE
		case xu.USING_SHA3:
			shash = SHA3_NONE
			// XXX DEFAULT => ERROR
		}
	} else {
		shash = hex.EncodeToString(hash)
	}
	str = fmt.Sprintf("%s%s %s", indent, shash, ml.name)
	return
}

func (ml *MerkleLeaf) ToStrings(indent, deltaIndent string, ss *[]string) (
	err error) {

	str, err := ml.ToString(indent, deltaIndent)
	if err == nil {
		*ss = append(*ss, str)
	}
	return
}

// Return the SHA1 hash of a file.  This is a sequence of 20 bytes.

func SHA1File(pathToFile string) (hash []byte, err error) {
	var data []byte
	found, err := xf.PathExists(pathToFile)
	if err == nil && !found {
		err = FileNotFound
	}
	if err == nil {
		data, err = ioutil.ReadFile(pathToFile)
		if err == nil {
			digest := sha1.New()
			digest.Write(data)
			hash = digest.Sum(nil)
		}
	}
	return
}

// Return the SHA256 hash of a file.  This is a sequence of 32 bytes.

func SHA2File(pathToFile string) (hash []byte, err error) {
	var data []byte
	found, err := xf.PathExists(pathToFile)
	if err == nil && !found {
		err = FileNotFound
	}
	if err == nil {
		data, err = ioutil.ReadFile(pathToFile)
		if err == nil {
			digest := sha256.New()
			digest.Write(data)
			hash = digest.Sum(nil)
		}
	}
	return
}

// Return the SHA3-256 hash of a file.  This is a sequence of 32 bytes.

func SHA3File(pathToFile string) (hash []byte, err error) {
	var data []byte
	found, err := xf.PathExists(pathToFile)
	if err == nil && !found {
		err = FileNotFound
	}
	if err == nil {
		data, err = ioutil.ReadFile(pathToFile)
		if err == nil {
			digest := sha3.New256()
			digest.Write(data)
			hash = digest.Sum(nil)
		}
	}
	return
}

