	m := make(util.Map)
	m.Set("mch_id", s.Get("mch_id"))
	m.Set("nonce_str", util.GenerateNonceStr())
	sign := util.GenerateSignature(m, s.GetString("key"), util.MakeSignMD5)
	m.Set("sign", sign)
	resp := core.PostXML(Link(sandboxSignKeyURLSuffix), nil, m)

	return resp

}

