package cloudtail

import (
	"crypto/sha1"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/luci/luci-go/common/logging"
)

// drainChannel reads non-empty log lines from a channel (until it is closed),
// extracts logging metadata from them (severity, timestamp, etc) via given
// parser and pushes log entries to the push buffer. Doesn't return errors: use
// buf.Stop() to check for any errors during sending.
func drainChannel(src chan string, parser LogParser, buf PushBuffer, logger logging.Logger) {
	batch := []Entry(nil)

	// Helper function to parse log line into an Entry and add it to 'batch'.
	addEntry := func(line string) {
		line = strings.TrimSpace(line)
		if line == "" {
			return
		}
		entry := parser.ParseLogLine(line)
		if entry == nil {
			if logger != nil {
				logger.Errorf("skipping line, unrecognized format: %s", line)
			}
			return
		}
		if entry.InsertID == "" {
			insertID, err := computeInsertID(entry)
			if err != nil {
				if logger != nil {
					logger.Errorf("skipping line, can't compute insertId: %s", err)
				}
				return
			}
			entry.InsertID = insertID
		}
		batch = append(batch, *entry)
	}

	line := ""
	alive := true

	for alive {
		// Wait for the first entry.
		line, alive = <-src
		if !alive {
			return
		}
		addEntry(line)

		// Fetch the rest of them in non blocking way.
		blocks := false
		for alive && !blocks {
			select {
			case line, alive = <-src:
				if alive {
					addEntry(line)
				}
			default:
				blocks = true
			}
		}

		// Send them all.
		if len(batch) != 0 {
			buf.Add(batch)
			batch = nil
		}
	}
}

// computeInsertID takes a LogEntry and deterministically combines its fields
// to come up with an identifier used for log deduplication. Used only if parser
// doesn't implement something more smart or efficient.
func computeInsertID(e *Entry) (string, error) {
	hasher := sha1.New()
	hasher.Write([]byte(e.TextPayload))
	if e.StructPayload != nil {
		if err := json.NewEncoder(hasher).Encode(e.StructPayload); err != nil {
			return "", err
		}
	}
	ts := ""
	if !e.Timestamp.IsZero() {
		ts = fmt.Sprintf("%d", e.Timestamp.UnixNano())
	}
	return ts + ":" + base64.StdEncoding.EncodeToString(hasher.Sum(nil)[:12]), nil
}

package husky

import (
	"crypto/sha1"
	"encoding/hex"
	"errors"
	"fmt"
	"golang.org/x/net/websocket"
	"log"
	"time"
)

type WebSocketManager struct {
	clients map[string]*WebSocketDispatcher
}

func (wm *WebSocketManager) broadcast(message []byte, ignores ...string) {
	for connId, dispatcher := range wm.clients {
		canSend := true
		for _, id := range ignores {
			if dispatcher.Id == id {
				canSend = false
			}
		}
		if !canSend {
			continue
		}
		if err := dispatcher.Send(message); err != nil {
			log.Printf("[WebSocket] message send error to %s\n", connId)
		}
	}
}

type WebSocketDispatcher struct {
	conn      *websocket.Conn
	Id        string
	OnMessage func(msg string)
	OnOpen    func()
	OnClose   func()
	isClosed  bool
	manager   *WebSocketManager
}

func NewWebSocketDispatcher(ws *websocket.Conn) *WebSocketDispatcher {
	hash := sha1.Sum([]byte(fmt.Sprint(time.Now().UnixNano())))
	id := hex.EncodeToString(hash[:len(hash)])

	return &WebSocketDispatcher{
		Id:   id,
		conn: ws,
	}
}

func (w *WebSocketDispatcher) Broadcast(message []byte, ignores ...string) (err error) {
	if w.isClosed {
		return errors.New("Connection Closed")
	}

	w.manager.broadcast(message, ignores...)
	return nil
}

func (w *WebSocketDispatcher) Send(message []byte) (err error) {
	if w.isClosed {
		return errors.New("Connection Closed")
	}

	if err := websocket.Message.Send(w.conn, message); err != nil {
		return err
	}

	return nil
}

func (w *WebSocketDispatcher) Close() {
	if err := w.conn.Close(); err == nil {
		w.isClosed = true

		if w.OnClose != nil {
			w.OnClose()
		}
	}
}

func (w *WebSocketDispatcher) receive() (msg string, err error) {
	err = websocket.Message.Receive(w.conn, &msg)

	if err == nil && w.OnMessage != nil {
		w.OnMessage(msg)
	}

	return msg, err
}

func NewWebSocketHandler(handler HuskyWebSocketHandler) websocket.Handler {
	manager := &WebSocketManager{
		clients: make(map[string]*WebSocketDispatcher),
	}

	return websocket.Handler(func(ws *websocket.Conn) {
		dispatcher := NewWebSocketDispatcher(ws)
		dispatcher.manager = manager
		id := dispatcher.Id

		manager.clients[id] = dispatcher
		log.Printf("[WebSocket] id: %s connected.\n", id)

		defer func() {
			if err := ws.Close(); err == nil {
				if _, ok := manager.clients[id]; ok {
					if dispatcher.OnClose != nil {
						dispatcher.OnClose()
					}
					delete(manager.clients, id)
				}
			}
		}()

		handler(dispatcher)

		for {
			if dispatcher.isClosed {
				return
			}
			if msg, err := dispatcher.receive(); err != nil {
				log.Printf("[WebSocket] id: %s id disconnected.\n", id)
				delete(manager.clients, id)
				return
			} else {
				log.Printf("[WebSocket] message: %s\n", msg)
				manager.broadcast([]byte(msg))
			}
		}
	})
}

package main

import (
	"crypto/hmac"
	"crypto/sha1"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"strings"

	"github.com/aisola/log"
	"github.com/aisola/log/http"
	"gopkg.in/go-playground/webhooks.v3/github"
)

type Options struct {
	App *App
	Secret string
}

func NewHookHandler(options *Options) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		eventName := r.Header.Get("X-Github-Event")
		if eventName != "push" {
			log.Infof("Ignoring '%s' event", eventName)
			return
		}

		body, err := ioutil.ReadAll(r.Body)
		if err != nil {
			loghttp.Error(w, 500, "Internal Server Error", err)
			return
		}

		if options.Secret != "" {
			ok := false
			for _, sig := range strings.Fields(r.Header.Get("X-Hub-Signature")) {
				if !strings.HasPrefix(sig, "sha1=") {
					continue
				}
				sig = strings.TrimPrefix(sig, "sha1=")
				mac := hmac.New(sha1.New, []byte(options.Secret))
				mac.Write(body)
				if sig == hex.EncodeToString(mac.Sum(nil)) {
					ok = true
					break
				}
			}
			if !ok {
				log.Infof("Ignoring '%s' event with incorrect signature", eventName)
				return
			}
		}

		event := new(github.PushPayload)
		if err := json.Unmarshal(body, event); err != nil {
			log.Infof("Ignoring '%s' event with invalid payload", eventName)
			http.Error(w, "Bad Request", http.StatusBadRequest)
			return
		}

		repoFullName := fmt.Sprintf("%s/%s", options.App.User, options.App.Name)
		if  event.Repository.FullName != repoFullName {
			log.Infof("Ignoring '%s' event with incorrect repository name", eventName)
			http.Error(w, "Bad Request", http.StatusBadRequest)
			return
		}

		log.Infof("Handling '%s' event for %s", eventName, repoFullName)

		if err := options.App.Update(); err != nil {
			loghttp.Error(w, 500, "Internal Server Error", err)
			return
		}
	})
}

