func FileLoad(filepath string) []byte {
	privatefile, err := os.Open(filepath)
	defer privatefile.Close()
	if err != nil {
		return nil
	}
	privateKey := make([]byte, 2048)
	num, err := privatefile.Read(privateKey)
	return privateKey[:num]
}

