func TestFuzzDump(t *testing.T) {
	if err := os.MkdirAll("fuzz-workdir/corpus", 0755); err != nil {
		t.Fatal(err)
	}

	seen := make(map[[sha1.Size]byte]bool)

	for _, test := range vomtest.AllPass() {
