	defer file.Close()
	fileBuf := bufio.NewWriter(file)
	defer fileBuf.Flush()
	writer, err := flate.NewWriter(fileBuf, flate.BestCompression)
	if err != nil {
		return err
	}
	_, err = WriteFull(data, writer)
	if err != nil {
		return err
	}
	return writer.Close()
}

