// FileCopy copies file source to destination dest.
// Based on <NAME>'s code which can be found at http://jayblog.jaybill.com/post/id/26
func FileCopy(source string, dest string) (err error) {
	sourceFile, err := os.Open(source)
	if err != nil {
		return err
	}
	defer sourceFile.Close()
	destFile, err := os.Create(dest)
	if err != nil {
		return err
	}
	defer destFile.Close()
	_, err = io.Copy(destFile, sourceFile)
	if err == nil {
		si, err := os.Stat(source)
		if err == nil {
			err = os.Chmod(dest, si.Mode())
		}
	}
	return err
}

// FileCopyDir recursively copies a directory tree, attempting to preserve permissions.
// Source directory must exist, destination directory must *not* exist.
// Based on <NAME>'s code which can be found at http://jayblog.jaybill.com/post/id/26
func FileCopyDir(source string, dest string) (err error) {
	// get properties of source dir
	fileInfo, err := os.Stat(source)
	if err != nil {
		return err
	}
	if !fileInfo.IsDir() {
		return &FileCopyError{"Source is not a directory"}
	}
	// ensure dest dir does not already exist
	_, err = os.Open(dest)
	if !os.IsNotExist(err) {
		return &FileCopyError{"Destination already exists"}
	}
	// create dest dir
	err = os.MkdirAll(dest, fileInfo.Mode())
	if err != nil {
		return err
	}
	entries, err := ioutil.ReadDir(source)
	for _, entry := range entries {
		sourcePath := filepath.Join(source, entry.Name())
		destinationPath := filepath.Join(dest, entry.Name())
		if entry.IsDir() {
			err = FileCopyDir(sourcePath, destinationPath)
		} else {
			// perform copy
			err = FileCopy(sourcePath, destinationPath)
		}
		if err != nil {
			return err
		}
	}
	return err
}

// FileCopyError is a struct for returning file copy error messages
type FileCopyError struct {
	What string
}

func (e *FileCopyError) Error() string {
	return e.What
}

package main

import (
	"crypto/hmac"
	"crypto/sha1"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"github.com/google/uuid"
	"html/template"
	"log"
	"net/http"
	"net/url"
	"os"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

type Chat struct {
	sync.RWMutex
	Turnstile *Turnstile
	Channels  map[string]*Channel
}

var tmpchat = &Chat{
	Turnstile: &Turnstile{m: make(map[string]struct{})},
	Channels:  make(map[string]*Channel),
}

func (ch *Chat) Get(channelName string) (*Channel, bool) {
	ch.RLock()
	channel, ok := ch.Channels[channelName]
	ch.RUnlock()
	return channel, ok
}

func (ch *Chat) Set(channelName string, channel *Channel) {
	ch.Lock()
	ch.Channels[channelName] = channel
	ch.Unlock()
}

func (ch *Chat) Delete(channelName string) {
	ch.Lock()
	delete(ch.Channels, channelName)
	ch.Unlock()
}

type Channel struct {
	Members  *Members
	Messages chan Message
}

type Members struct {
	sync.RWMutex
	m map[string]*websocket.Conn
}

func (m *Members) Get(id string) (*websocket.Conn, bool) {
	m.RLock()
	member, ok := m.m[id]
	m.RUnlock()
	return member, ok
}

func (m *Members) Set(id string, member *websocket.Conn) {
	m.Lock()
	m.m[id] = member
	m.Unlock()
}

func (m *Members) Delete(id string) {
	m.Lock()
	delete(m.m, id)
	m.Unlock()
}

func (m *Members) Count() int {
	var n int
	m.Range(func(member *websocket.Conn) bool {
		if member != nil {
			n++
		}
		return true
	})
	return n
}

func (m *Members) Range(f func(*websocket.Conn) bool) {
	m.RLock()
	defer m.RUnlock()
	for _, member := range m.m {
		if next := f(member); !next {
			return
		}
	}
}

func Materialize(channelName string) *Channel {
	c := &Channel{
		Members:  &Members{m: make(map[string]*websocket.Conn)},
		Messages: make(chan Message),
	}
	if existing, ok := tmpchat.Get(channelName); !ok {
		go c.Run()
		tmpchat.Set(channelName, c)
		return c
	} else {
		return existing
	}
}

func Collect(channelName string, userID string) {
	if ch, ok := tmpchat.Get(channelName); ok {
		ch.Broadcast(Message{Type: Exit, From: userID})
		ch.Members.Delete(userID)
		if ch.Members.Count() == 0 {
			close(ch.Messages)
			tmpchat.Delete(channelName)
		}
	}
}

func GetTURNCreds(userID string) TURNCreds {
	expiresAt := time.Now().Add(24 * time.Hour).Unix()
	turnUserName := fmt.Sprintf("%d:%s", expiresAt, userID)
	h := hmac.New(sha1.New, []byte(os.Getenv("TURN_AUTH_SECRET")))
	h.Write([]byte(turnUserName))
	password := base64.StdEncoding.EncodeToString(h.Sum(nil))
	return TURNCreds{turnUserName, password}
}

type TURNCreds struct {
	Username string `json:"username"`
	Password string `json:"credential"`
}

func (c *Channel) Run() {
	for msg := range c.Messages {
		switch msg.Type {
		case TURNCredRequest:
			if member, ok := c.Members.Get(msg.From); ok {
				Message{
					Type:    TURNCredResponse,
					Content: GetTURNCreds(msg.From),
				}.SendTo(member)
			}
			c.Broadcast(
				Message{
					Type: Entrance,
					Content: struct {
						ID   string `json:"id"`
						Name string `json:"name"`
					}{
						msg.From,
						msg.Content.(string),
					},
				})
		case RTCOffer, RTCAnswer, RTCICECandidate:
			if member, ok := c.Members.Get(msg.To); ok {
				msg.SendTo(member)
			}
		}
	}
}

type Message struct {
	To      string      `json:"to,omitempty"`
	From    string      `json:"from,omitempty"`
	Type    EventType   `json:"type"`
	Content interface{} `json:"content"`
}

type EventType int

const (
	Entrance EventType = iota
	Exit
	RTCOffer
	RTCAnswer
	RTCICECandidate
	TURNCredRequest
	TURNCredResponse
)

func (m Message) SendTo(member *websocket.Conn) {
	message, _ := json.Marshal(m)
	if err := member.WriteMessage(1, message); err != nil {
		log.Println("write:", err)
	}
}

func (c *Channel) Broadcast(msg Message) {
	message, _ := json.Marshal(msg)
	c.Members.Range(func(member *websocket.Conn) bool {
		if err := member.WriteMessage(1, message); err != nil {
			log.Println("write:", err)
		}
		return true
	})
}

func signalingHandler(w http.ResponseWriter, r *http.Request) {
	params := r.URL.Query()
	var channelName, userID string
	if vals, ok := params["channelName"]; ok {
		channelName = vals[0]
	}
	if vals, ok := params["userID"]; ok {
		userID = vals[0]
	}
	if ok := tmpchat.Turnstile.Admit(userID); !ok {
		w.WriteHeader(http.StatusForbidden)
		return
	}
	upgrader := websocket.Upgrader{
		CheckOrigin: func(*http.Request) bool {
			var origin string
			if vals, ok := r.Header["Origin"]; ok {
				origin = vals[0]
			}
			originURL, err := url.Parse(origin)
			if err != nil {
				return false
			}
			return originURL.String() == os.Getenv("TMPCHAT_URL")
		},
	}
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Print("upgrade:", err)
		return
	}
	Materialize(channelName).Members.Set(userID, conn)
	defer Collect(channelName, userID)
	for {
		_, rawSignal, err := conn.ReadMessage()
		if err != nil {
			log.Println("read:", err)
			break
		}
		message := Message{}
		if err := json.Unmarshal(rawSignal, &message); err != nil {
			continue
		}
		if ch, ok := tmpchat.Get(channelName); ok {
			ch.Messages <- message
		}
	}
}

type Turnstile struct {
	sync.RWMutex
	m map[string]struct{}
}

func (t *Turnstile) Register(userID string) bool {
	t.RLock()
	_, ok := t.m[userID]
	t.RUnlock()
	if ok {
		return false
	}
	t.Lock()
	t.m[userID] = struct{}{}
	t.Unlock()
	return true
}

func (t *Turnstile) Admit(userID string) bool {
	t.RLock()
	_, ok := t.m[userID]
	t.RUnlock()
	if ok {
		t.Lock()
		delete(t.m, userID)
		t.Unlock()
		return true
	}
	return false
}

type tmpchatPageData struct {
	ChannelName  string
	UserID       string
	AppURL       string
	SignalingURL string
}

func tmpchatHandler(w http.ResponseWriter, r *http.Request) {
	channelName := r.URL.Path[1:] // Omit leading slash in path
	var tmpl *template.Template
	fm := template.FuncMap{
		"safeURL": func(u string) template.URL { return template.URL(u) },
	}
	if channelName == "" {
		tmpl = getTemplate("tmpchat-index", fm)
	} else {
		tmpl = getTemplate("tmpchat-channel", fm)
	}
	userID := uuid.New().String()
	if ok := tmpchat.Turnstile.Register(userID); !ok {
		w.WriteHeader(http.StatusNoContent)
		return
	}
	d := tmpchatPageData{
		channelName,
		userID,
		os.Getenv("TMPCHAT_URL"),
		os.Getenv("TMPCHAT_SIGNALING_URL"),
	}
	_ = tmpl.Execute(w, d)
}

package s3_test

import (
	"crypto/sha1"
	"encoding/hex"
	"fmt"
	"io"
	"io/ioutil"
	"os"

	. "github.com/onsi/ginkgo"
	. "github.com/onsi/gomega"
	"testing"

	"github.com/jhunt/ssg/pkg/ssg/providers/s3"
)

func TestSuite(t *testing.T) {
	RegisterFailHandler(Fail)
	RunSpecs(t, "S3 Provider Test Suite")
}

var _ = Describe("S3 Provider", func() {
	Context("full stack", func() {
		var provider s3.Provider

		BeforeEach(func() {
			if v := os.Getenv("TEST_S3_LIVE"); v != "yes" {
				Skip("TEST_S3_LIVE not found in environment")
				return
			}

			Ω(os.Getenv("TEST_S3_BUCKET")).ShouldNot(Equal(""))
			Ω(os.Getenv("TEST_S3_REGION")).ShouldNot(Equal(""))
			Ω(os.Getenv("TEST_S3_AKI")).ShouldNot(Equal(""))
			Ω(os.Getenv("TEST_S3_KEY")).ShouldNot(Equal(""))

			p, err := s3.Configure(s3.Endpoint{
				Bucket:          os.Getenv("TEST_S3_BUCKET"),
				Region:          os.Getenv("TEST_S3_REGION"),
				AccessKeyID:     os.Getenv("TEST_S3_AKI"),
				SecretAccessKey: os.Getenv("TEST_S3_KEY"),
				Prefix:          os.Getenv("TEST_S3_PREFIX"),
			})
			Ω(err).ShouldNot(HaveOccurred())
			provider = p
		})

		It("should be able to download an uploaded file", func() {
			uploader, err := provider.Upload(s3.RandomKey)
			Ω(err).ShouldNot(HaveOccurred())

			fmt.Fprintf(uploader, "The best laid schemes o’ Mice an’ Men\n")
			fmt.Fprintf(uploader, "  Gang aft agley.\n")
			uploader.Close()

			downloader, err := provider.Download(uploader.Path())
			Ω(err).ShouldNot(HaveOccurred())

			b, err := ioutil.ReadAll(downloader)
			Ω(err).ShouldNot(HaveOccurred())

			Ω(string(b)).Should(Equal("The best laid schemes o’ Mice an’ Men\n" +
				"  Gang aft agley.\n"))

			err = provider.Expunge(uploader.Path())
			Ω(err).ShouldNot(HaveOccurred())

			_, err = provider.Download(uploader.Path())
			Ω(err).Should(HaveOccurred())
		})

		It("should be able to handle really large files", func() {
			uploader, err := provider.Upload(s3.RandomKey)
			Ω(err).ShouldNot(HaveOccurred())

			// generate 10M of data
			// checksum 872e2c6727b8e809cbe5baf15f05997753cd7818
			for i := 0; i < 10240; i++ {
				b := make([]byte, 1024)
				fill := []byte("jrh")
				for j := range b {
					b[j] = fill[j%3]
				}
				uploader.Write(b)
			}
			uploader.Close()

			downloader, err := provider.Download(uploader.Path())
			Ω(err).ShouldNot(HaveOccurred())

			ck := sha1.New()
			io.Copy(ck, downloader)
			Ω(hex.EncodeToString(ck.Sum(nil))).Should(Equal("872e2c6727b8e809cbe5baf15f05997753cd7818"))
		})
	})
})

