	// project name
	Name string
	// mod prefix
	ModPrefix string
	// project dir
	path     string
	none     bool
	onlyGRPC bool
	onlyHTTP bool
}

var p project

//go:generate packr2
func create() (err error) {
	box := packr.New("all", "./templates/all")
	if p.onlyHTTP {
		box = packr.New("http", "./templates/http")
	} else if p.onlyGRPC {
		box = packr.New("grpc", "./templates/grpc")
	}
	if err = os.MkdirAll(p.path, 0755); err != nil {
		return
	}
	for _, name := range box.List() {
		if p.ModPrefix != "" && name == "go.mod.tmpl" {
			continue
		}

		if name == "zoneinfo.tar.gz" {
			targz, _ := box.Find(name)
			if err = ioutil.WriteFile(filepath.Join(p.path, name), targz, 0644); err != nil {
				break
			}
			continue
		}

		tmpl, _ := box.FindString(name)
		i := strings.LastIndex(name, string(os.PathSeparator))
		if i > 0 {
			dir := name[:i]
			if err = os.MkdirAll(filepath.Join(p.path, dir), 0755); err != nil {
				return
			}
		}
		if strings.HasSuffix(name, ".tmpl") {
			name = strings.TrimSuffix(name, ".tmpl")
		}
		if err = write(filepath.Join(p.path, name), tmpl); err != nil {
			return
		}
	}

	if err = generate("./..."); err != nil {
		return
	}
	if err = generate("./internal/dao/wire.go"); err != nil {
		return
	}
	return
}

func generate(path string) error {
	cmd := exec.Command("go", "generate", "-x", path)
	cmd.Dir = p.path
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

func write(path, tpl string) (err error) {
	data, err := parse(tpl)
	if err != nil {
		return
	}
	return ioutil.WriteFile(path, data, 0644)
}

func parse(s string) ([]byte, error) {
	t, err := template.New("").Parse(s)
	if err != nil {
		return nil, err
	}
	var buf bytes.Buffer
	if err = t.Execute(&buf, p); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

package email

import (
	"bytes"
	"errors"
	"fmt"
	"mime"
	"net/smtp"
	"strings"
	"text/template"

	"github.com/ovh/utask/pkg/plugins/taskplugin"
)

// the email plugin send email
var (
	Plugin = taskplugin.New("email", "0.1", exec,
		taskplugin.WithConfig(validConfig, Config{}),
	)
)

// Config is the configuration needed to send an email
type Config struct {
	SMTPUsername string   `json:"smtp_username"`
	SMTPPassword string   `json:"smtp_password"`
	SMTPPort     uint16   `json:"smtp_port,omitempty"`
	SMTPHostname string   `json:"smtp_hostname"`
	From         string   `json:"from"`
	To           []string `json:"to"`
	Subject      string   `json:"subject"`
	Body         string   `json:"body"`
}

const emailTemplate = "From: {{.From}}\r\n" +
	"To: {{.To}}\r\n" +
	"Subject: {{.Subject}}\r\n" +
	"MIME-version: 1.0\r\n" +
	"Content-Type: text/html; charset=\"UTF-8\"\r\n" +
	"\r\n" +
	"{{.Body}}"

func validConfig(config interface{}) error {
	cfg := config.(*Config)

	if cfg.SMTPUsername == "" {
		return errors.New("smtp_username is missing")
	}
	if cfg.SMTPPassword == "" {
		return errors.New("smtp_password is missing")
	}
	if cfg.From == "" {
		return errors.New("from is missing")
	}
	if len(cfg.To) == 0 {
		return errors.New("to is missing")
	}
	if cfg.SMTPHostname == "" {
		return errors.New("smtp_hostname is missing")
	}
	if cfg.Subject == "" {
		return errors.New("subject is missing")
	}
	if cfg.Body == "" {
		return errors.New("body is missing")
	}

	return nil
}

func exec(stepName string, config interface{}, ctx interface{}) (interface{}, interface{}, error) {
	cfg := config.(*Config)

	parameters := struct {
		From    string `json:"from"`
		To      string `json:"to"`
		Subject string `json:"subject"`
		Body    string `json:"body"`
	}{
		cfg.From,
		strings.Join(cfg.To, ","),
		mime.BEncoding.Encode("UTF-8", cfg.Subject),
		cfg.Body,
	}

	buffer := new(bytes.Buffer)

	template := template.Must(template.New("emailTemplate").Parse(emailTemplate))
	template.Execute(buffer, &parameters)

	auth := smtp.PlainAuth("", cfg.SMTPUsername, cfg.SMTPPassword, cfg.SMTPHostname)

	port := cfg.SMTPPort
	if port == 0 {
		port = 25
	}

	err := smtp.SendMail(
		fmt.Sprintf("%s:%d", cfg.SMTPHostname, cfg.SMTPPort),
		auth,
		cfg.From,
		cfg.To,
		buffer.Bytes())
	if err != nil {
		return nil, nil, fmt.Errorf("Send email failed: %s", err.Error())
	}

	return &parameters, nil, nil
}

