package main

import (
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"io/ioutil"
	"log"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"text/template"
)

func main() {
	if len(os.Args) < 3 {
		fmt.Fprintf(os.Stderr, "Usage: %s [var] [file]...\n", os.Args[0])
	}

	data := struct {
		Var   string            // name for generated variable
		Hash  string            // hash of file names and contents
		Files map[string]string // keys are base filenames, values are data
	}{
		Var:   os.Args[1],
		Files: make(map[string]string),
	}

	// Keep a running hash of null-terminated file names and base64-encoded contents.
	hash := sha256.New()

	paths := append([]string{}, os.Args[2:]...)
	sort.Strings(paths)
	for _, p := range paths {
		b, err := ioutil.ReadFile(p)
		if err != nil {
			log.Fatal("Failed reading file: ", err)
		}
		name := filepath.Base(p)
		data.Files[name] = string(b)

		println(name)
		hash.Write([]byte(name))
		hash.Write([]byte{0})
		hash.Write([]byte(base64.StdEncoding.EncodeToString(b)))
		hash.Write([]byte{0})
	}

	data.Hash = hex.EncodeToString(hash.Sum(nil))

	if err := template.Must(template.New("").Parse(strings.TrimLeft(`
// Code generated by gen_filemap.go from {{.Hash}}. DO NOT EDIT.

package render

var {{.Var}} = map[string]string{
{{- range $name, $val := .Files}}
	{{printf "%q" $name}}: {{printf "%q" $val}},
{{- end -}}
}
`, "\n"))).Execute(os.Stdout, &data); err != nil {
		log.Fatal("Failed executing template: ", err)
	}
}

package newsletter

import (
	"bytes"
	"io"
	"os"
	"text/template"
	"time"

	"github.com/AlecAivazis/survey/v2"
	"gopkg.in/yaml.v3"
)

type Newsletter struct {
	Title    string   `yaml:"title"`
	Date     string   `yaml:"date"`
	Articles []string `yaml:"articles"`
	Template string   `yaml:"template"`
}

func New(w io.Writer) error {
	newsletter := Newsletter{
		Date: time.Now().Format("2006-01-02"),
		Template: `<tr>
		<td align="center">
			<h1>{{.Title}}</h1>
		</td>
	</tr>
	<tr>
		<td align="center">
			<p>{{.Date}}</p>
		</td>
	</tr>`,
		Articles: []string{},
	}
	if err := survey.Ask([]*survey.Question{
		{
			Name: "Title",
			Prompt: &survey.Input{
				Message: "Title:",
			},
		},
	}, &newsletter); err != nil {
		return err
	}
	encoder := yaml.NewEncoder(w)
	encoder.SetIndent(2)
	if err := encoder.Encode(newsletter); err != nil {
		return err
	}
	return nil
}

func Load(name string) (*Newsletter, error) {
	f, err := os.Open(name)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	newsletter := Newsletter{}
	decoder := yaml.NewDecoder(f)
	if err := decoder.Decode(&newsletter); err != nil {
		return nil, err
	}
	return &newsletter, nil
}

func (n *Newsletter) Parse() string {
	template, err := template.New("newsletter").Parse(n.Template)
	if err != nil {
		panic(err)
	}
	buf := bytes.NewBuffer(nil)
	if err := template.Execute(buf, n); err != nil {
		panic(err)
	}
	return buf.String()
}

