import (
	"encoding/json"
	"io/ioutil"
	"log"
	"net/http"

	"text/template"
)

type httpError struct {
	Error   error
	Message string
	Code    int
}

type httpHandler func(http.ResponseWriter, *http.Request) *httpError

func (fn httpHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if err := fn(w, r); err != nil {
		log.Println(err)
		http.Error(w, err.Message, err.Code)
	}
}

func factsHandler(w http.ResponseWriter, r *http.Request) *httpError {
	f := getFacts()

	body, err := ioutil.ReadAll(r.Body)
	if err != nil {
		return &httpError{err, "Can't process template string", 500}
	}
	defer r.Body.Close()

	if string(body) != "" {
		tmpl, err := template.New("format").Parse(string(body))
		if err != nil {
			return &httpError{err, "Can't process template string", 500}
		}
		err = tmpl.Execute(w, &f.Facts)
		if err != nil {
			return &httpError{err, "Can't process template string", 500}
		}
		return nil
	}

	data, err := json.MarshalIndent(&f.Facts, " ", "  ")
	if err != nil {
		return &httpError{err, "Error processing facts", 500}
	}
	w.Header().Set("Server", "Teminus 1.0.0")
	w.Header().Set("Content-Type", "application/json")
	w.Write(data)
	return nil
}

package markdown

import (
	_ "embed"
	"text/template"

	"github.com/Code-Hex/gqldoc/internal/introspection"
	"github.com/pkg/errors"
)

//go:embed queries.md
var queries string

type (
	Query struct {
		Description string
		Fields      []*QueryField
	}

	QueryField struct {
		Name        string
		Description string
		Args        []*QueryFieldArg
		Return      *QueryFieldReturn
	}

	QueryFieldArg struct {
		Name        string
		Description string
		Type        string
		TypeLink    string
	}

	QueryFieldReturn struct {
		Type     string
		TypeLink string
	}
)

func (m *Config) renderQuery(s *introspection.Schema) error {
	t, err := template.New("queries").Parse(queries)
	if err != nil {
		return errors.WithStack(err)
	}

	types, err := s.FindTypes(s.QueryType.Name)
	if err != nil {
		return errors.WithStack(err)
	}

	mf := make([]*QueryField, 0, len(types.Fields))
	for _, f := range types.Fields {
		mfa := make([]*QueryFieldArg, 0, len(f.Args))
		for _, arg := range f.Args {
			link, err := m.MakeLinkFromType(arg.Type)
			if err != nil {
				return errors.Wrapf(err, "argument %q has caused error", arg.Type.UnderlyingName())
			}
			mfa = append(mfa, &QueryFieldArg{
				Name:        arg.Name,
				Description: renderHTML(arg.Description),
				Type:        arg.Type.String(),
				TypeLink:    link,
			})
		}

		fieldTypeLink, err := m.MakeLinkFromType(f.Type)
		if err != nil {
			return errors.Wrapf(err, "field %q has caused error", f.Type.UnderlyingName())
		}
		mf = append(mf, &QueryField{
			Name:        f.Name,
			Description: f.Description,
			Args:        mfa,
			Return: &QueryFieldReturn{
				Type:     f.Type.String(),
				TypeLink: fieldTypeLink,
			},
		})
	}

	f, err := m.Create("queries.md")
	if err != nil {
		return errors.WithStack(err)
	}
	defer f.Close()

	if err := t.Execute(f, &Query{
		Description: types.Description,
		Fields:      mf,
	}); err != nil {
		return errors.WithStack(err)
	}
	return nil
}

