package generator

import (
	"strconv"
	"strings"
	"text/template"

	"github.com/suchwerk/caddy-docker-proxy/plugin/v2/caddyfile"
)

type targetsProvider func() ([]string, error)

func labelsToCaddyfile(labels map[string]string, templateData interface{}, getTargets targetsProvider) (*caddyfile.Container, error) {
	funcMap := template.FuncMap{
		"upstreams": func(options ...interface{}) (string, error) {
			targets, err := getTargets()
			transformed := []string{}
			for _, target := range targets {
				for _, param := range options {
					if protocol, isProtocol := param.(string); isProtocol {
						target = protocol + "://" + target
					} else if port, isPort := param.(int); isPort {
						target = target + ":" + strconv.Itoa(port)
					}
				}
				transformed = append(transformed, target)
			}
			return strings.Join(transformed, " "), err
		},
		"http": func() string {
			return "http"
		},
		"https": func() string {
			return "https"
		},
	}

	return caddyfile.FromLabels(labels, templateData, funcMap)
}

package adsearch

import (
	"embed"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"text/template"

	"github.com/linuxexam/goweb/router"
)

//embed resource files
//go:embed *.html *.png
var webUI embed.FS

var (
	appName = "ActiveDirectorySearch"
	tpls    = template.Must(template.ParseFS(webUI, "*.html"))
)

type PageIndex struct {
	Title    string
	UserName string
	Result   string
}

func init() {
	router.RegisterApp(appName, http.HandlerFunc(appHandler))
}

func appHandler(w http.ResponseWriter, r *http.Request) {
	path := r.URL.Path
	if strings.HasPrefix(path, "/"+appName+"/static/") {
		fs := http.StripPrefix("/"+appName+"/static/", http.FileServer(http.FS(webUI)))
		fs.ServeHTTP(w, r)
		return
	}
	_appHandler(w, r)
}

func getDNInfo(s *Session, DN string) string {
	var sb strings.Builder
	// basic info
	sb.WriteString("Basic Info:\n")
	email, err := s.FindEmail(DN)
	sb.WriteString("Email: ")

	if err != nil {
		sb.WriteString(err.Error() + "\n")
	} else {
		sb.WriteString(email + "\n")
	}

	sam, err := s.FindSAM(DN)
	sb.WriteString("sAMAccountName: ")
	if err != nil {
		sb.WriteString(err.Error() + "\n")
	} else {
		sb.WriteString(sam + "\n")
	}

	sb.WriteString("\n")
	// managers info
	mgrs := s.FindManagers(DN)
	sb.WriteString(fmt.Sprintf("Managers (%d):\n", len(mgrs)))
	for _, mgr := range mgrs {
		sb.WriteString(mgr + "\n")
	}

	// groups info
	sb.WriteString("\n")
	grps, err := s.FindGroups(DN)
	sb.WriteString(fmt.Sprintf("Groups (%d):\n", len(grps)))
	if err != nil {
		sb.WriteString("No groups")
	}
	for _, grp := range grps {
		sb.WriteString(grp + "\n")
	}
	return sb.String()
}

// config file priority order: current work dir, exe's dir
func getConfigFile(filename string) string {

	configFile := filepath.Join("config", "adsearch", filename)

	_, err := os.Stat(configFile)
	if err != nil {
		selfPath, _ := os.Executable()
		selfDir := filepath.Dir(selfPath)
		configFile = filepath.Join(selfDir, "config", "adsearch", filename)
	}

	return configFile
}
func _appHandler(w http.ResponseWriter, r *http.Request) {
	pd := &PageIndex{
		Title:    appName,
		UserName: "<NAME>",
	}
	username := strings.TrimSpace(r.FormValue("username"))

	// get and no input
	if username == "" && r.Method == "GET" {
		tpls.ExecuteTemplate(w, "index.html", pd)
		return
	}

	// post
	pd.UserName = username

	names := strings.Fields(username)
	if len(names) < 2 {
		pd.Result = "Name format wrong! Correct format is 'GivenName Surname'"
		tpls.ExecuteTemplate(w, "index.html", pd)
		return
	}
	givenName := names[0]
	surname := names[1]

	s, err := NewSessionFromJson(getConfigFile("bcit-session.json"))
	if err != nil {
		pd.Result = err.Error()
		tpls.ExecuteTemplate(w, "index.html", pd)
		return
	}
	defer s.Close()

	DNs, err := s.FindDNsByName(givenName, surname)
	if err != nil {
		pd.Result = err.Error()
		tpls.ExecuteTemplate(w, "index.html", pd)
		return
	}

	n := len(DNs)
	pd.Result += fmt.Sprintf("Found %d records\n", n)

	for i, DN := range DNs {
		pd.Result += fmt.Sprintf("---------------------------------------Record: %d/%d---------------------------------------\n", i+1, n)
		pd.Result += getDNInfo(s, DN)
	}
	tpls.ExecuteTemplate(w, "index.html", pd)
}

package engine

import (
	"bufio"
	"flag"
	"fmt"
	"github.com/omakoto/go-common/src/textio"
	"io"
	"math"
	"strconv"
	"strings"
	"text/template"
)

var (
	StandardColors = []int{
		// Standard VGA (http://en.wikipedia.org/wiki/ANSI_escape_code#Colors)
		rgb(0, 0, 0),
		rgb(170, 0, 0),
		rgb(0, 170, 0),
		rgb(170, 85, 0),
		rgb(0, 0, 170),
		rgb(170, 0, 170),
		rgb(0, 170, 170),
		rgb(170, 170, 170),
	}

	BrightColors = []int{
		rgb(85, 85, 85),
		rgb(255, 85, 85),
		rgb(85, 255, 85),
		rgb(255, 255, 85),
		rgb(85, 85, 255),
		rgb(255, 85, 255),
		rgb(85, 255, 255),
		rgb(255, 255, 255),
	}
)

var (
	gamma             = flag.Float64("gamma", 1.0, "gamma value for RGB conversion")
	title             = flag.String("title", "A2H", "HTML Title")
	bgColor           = flag.String("bg-color", "#000000", "Background color")
	textColor         = flag.String("text-color", "#ffffff", "Background color")
	fontSize          = flag.String("font-size", "9pt", "Font size)")
	autoFlash         = flag.Bool("auto-flush", false, "Auto flush")
	noConvertControls = flag.Bool("no-convert-controls", false, "Don't convert control characters")
)

// Color manipulation

func rgb(r, g, b int) int {
	return r<<16 | g<<8 | b
}

func gammaConv(v float64) float64 {
	return math.Max(0, math.Min(1, math.Pow(v, *gamma)))
}

func gammaRgb(rgbValue int) int {
	r := gammaConv(float64((rgbValue>>16)&255) / 255.0)
	g := gammaConv(float64((rgbValue>>8)&255) / 255.0)
	b := gammaConv(float64((rgbValue)&255) / 255.0)
	return rgb(int(r*255), int(g*255), int(b*255))
}

func xterm256ColortoRgb(value int) int {
	if value < 8 {
		return StandardColors[value]
	}
	if value < 16 {
		return BrightColors[value-8]
	}
	if 232 <= value && value <= 256 {
		// Gray
		level := (value-232)*10 + 8
		return rgb(level, level, level)
	}

	value -= 16

	b := value % 6
	g := (value / 6) % 6
	r := (value / 36) % 6
	return rgb(int(float64(r)*42.5), int(float64(g)*42.5), int(float64(b)*42.5))
}

func getIndexColor(index int, bold bool) int {
	if bold {
		return BrightColors[index]
	}
	return StandardColors[index]
}

// Converter
const (
	defaultColor = -1000
)

type Converter struct {
	fg, bg int // positive: rgb, negative: index, -1000

	bold      bool
	faint     bool
	italic    bool
	underline bool
	blink     bool
	negative  bool
	conceal   bool
	crossout  bool

	inDiv  bool
	inSpan bool

	rows int

	buf *bufio.Writer
}

func NewConverter(w io.Writer) Converter {
	c := Converter{buf: bufio.NewWriter(w)}
	c.reset()
	return c
}

func (c *Converter) reset() {
	c.fg = defaultColor
	c.bg = defaultColor
	c.bold = false
	c.faint = false
	c.italic = false
	c.underline = false
	c.blink = false
	c.negative = false
	c.conceal = false
	c.crossout = false
}

func (c *Converter) hasAttr() bool {
	return (c.fg != defaultColor ||
		c.bg != defaultColor ||
		c.bold ||
		c.faint ||
		c.italic ||
		c.underline ||
		c.blink ||
		c.negative ||
		c.conceal ||
		c.crossout)
}

func (c *Converter) startDiv() {
	if !c.inDiv {
		c.inDiv = true
		c.buf.WriteString("<div>")
		c.rows++
	}
}

func (c *Converter) closeDiv() {
	c.closeSpan()
	if c.inDiv {
		c.inDiv = false
		c.buf.WriteString("</div>\n")
	}
}

func (c *Converter) closeSpan() {
	if c.inSpan {
		c.inSpan = false
		c.buf.WriteString("</span>")
	}
}

func parseInt(s string, defValue int) int {
	v, err := strconv.Atoi(s)
	if err == nil {
		return v
	}
	return defValue
}

func setColorForRgb(i int, vals []string) (int, int) {
	ret := 0
	next := vals[i]
	if next == "5" {
		if i+1 < len(vals) {
			// Xterm 256 colors
			i++
			ret = xterm256ColortoRgb(parseInt(vals[i], 0))
			i++
		}
	} else if next == "2" {
		// Kterm 24 bit color
		if i+3 < len(vals) {
			i++
			ret = rgb(parseInt(vals[i], 0), parseInt(vals[i+1], 0), parseInt(vals[i+2], 0))
			i += 3
		}
	}
	return ret, i
}

func (c *Converter) convertCsi(csi string) {
	vals := strings.Split(csi, ";")

	for i := 0; i < len(vals); {
		code := parseInt(string(vals[i]), 0) // first code
		i++
		if code == 0 {
			c.reset()
		} else if code == 1 {
			c.bold = true
		} else if code == 2 {
			c.faint = true
		} else if code == 3 {
			c.italic = true
		} else if code == 4 {
			c.underline = true
		} else if code == 5 {
			c.blink = true
		} else if code == 7 {
			c.negative = true
		} else if code == 8 {
			c.conceal = true
		} else if code == 9 {
			c.crossout = true
		} else if code == 21 {
			c.bold = false
		} else if code == 22 {
			c.bold = false
			c.faint = false
		} else if code == 23 {
			c.italic = false
		} else if code == 24 {
			c.underline = false
		} else if code == 25 {
			c.blink = false
		} else if code == 27 {
			c.negative = false
		} else if code == 28 {
			c.conceal = false
		} else if code == 29 {
			c.crossout = false
		} else if 30 <= code && code <= 37 {
			c.fg = -(code - 30 + 1) // FG color, index
		} else if 40 <= code && code <= 47 {
			c.bg = -(code - 40 + 1) // BG color, index
		} else if 90 <= code && code <= 97 { // used by rustc
			c.fg = -(code - 90 + 1) // FG color, index
		} else if 100 <= code && code <= 107 { // used by rustc
			c.bg = -(code - 100 + 1) // BG color, index
		} else if code == 38 {
			c.fg, i = setColorForRgb(i, vals)
		} else if code == 48 {
			c.bg, i = setColorForRgb(i, vals)
		}
	}
	c.startSpanIfNeeded()
}

func (c *Converter) startSpanIfNeeded() {
	c.closeSpan()
	if !c.hasAttr() {
		return
	}

	fg := c.fg
	bg := c.bg
	// Convert index color to RGB
	if fg < 0 && fg != defaultColor {
		fg = getIndexColor(-fg-1, c.bold)
	}
	if bg < 0 && bg != defaultColor {
		bg = getIndexColor(-bg-1, false)
	}

	c.buf.WriteString("<span ")
	if c.blink {
		c.buf.WriteString("class=\"blink\" ")
	}
	c.buf.WriteString("style=\"")
	c.inSpan = true

	if c.bold {
		c.buf.WriteString("font-weight:bold;")
	}
	if c.faint {
		c.buf.WriteString("opacity:0.5;")
	}
	if c.italic {
		c.buf.WriteString("font-style:italic;")
	}
	if c.underline {
		c.buf.WriteString("text-decoration:underline;")
	}
	if c.crossout {
		c.buf.WriteString("text-decoration:line-through;")
	}
	var b, f string
	if bg == defaultColor {
		b = *bgColor
	} else {
		b = fmt.Sprintf("#%06x", gammaRgb(bg))
	}

	if fg == defaultColor {
		f = *textColor
	} else {
		f = fmt.Sprintf("#%06x", gammaRgb(fg))
	}
	if c.negative {
		f, b = b, f
	}
	if c.conceal {
		f = b
	}

	if f != *textColor {
		c.buf.WriteString(fmt.Sprintf("color:%s;", f))
	}
	if b != *bgColor {
		c.buf.WriteString(fmt.Sprintf("background-color:%s;", b))
	}

	c.buf.WriteString("\">")

}

func isCsiEnd(b byte) bool {
	return 64 <= b && b <= 126
}

func peek(line []byte, index int) int {
	if index < len(line) {
		return int(line[index])
	}
	return -1
}

func (c *Converter) convert(line []byte) {
	c.startDiv()
	c.startSpanIfNeeded()

	size := len(line)
outer:
	for i := 0; i < size; i++ {
		b := line[i]
		switch b {
		case '&':
			c.buf.WriteString("&amp;")
			continue
		case '<':
			c.buf.WriteString("&lt;")
			continue
		case '>':
			c.buf.WriteString("&gt;")
			continue
		case '\a': // bell, ignore.
			continue
		case 0x0d:
			if peek(line, i+1) == 0x0a {
				// CR followed by LF, ignore.
				continue
			}
			fallthrough
		case 0x0a:
			c.closeDiv()
			if peek(line, i+1) != -1 {
				c.startDiv()
				c.startSpanIfNeeded()
			}
			continue
		case '\x1b':
			i++
			switch peek(line, i) {
			case -1:
				continue
			case '[': // CSI
				i++
				csiStart := i
				for i < size && !isCsiEnd(line[i]) {
					i++
				}
				if i >= size {
					continue
				}
				if line[i] == 'm' {
					c.convertCsi(string(line[csiStart:i]))
				}
				continue
			case ']':
				i++
				for {
					n := peek(line, i)
					if n == -1 || n == '\a' {
						break
					}
					if n == '\x1b' && peek(line, i+1) == '\\' {
						i++
						break
					}
					i++
				}
				continue outer
			case '(':
				i++
				continue
			case 'c':
				c.reset()
				c.closeSpan()
				continue
			}
			continue
		}
		if !*noConvertControls && b <= 31 && b != '\t' {
			c.buf.WriteByte('^')
			c.buf.WriteByte(b + '@')
			continue
		}
		c.buf.WriteByte(b)
	}
	c.closeDiv()
}

type TemplateParams struct {
	Title           string
	BackgroundColor string
	TextColor       string
	FontSize        string
	RowCount        int
}

func (c *Converter) Convert(files []string) {
	defer c.buf.Flush()

	// Header
	params := TemplateParams{
		Title:           *title,
		BackgroundColor: *bgColor,
		TextColor:       *textColor,
		FontSize:        *fontSize,
	}

	tmpl, err := template.New("h").Parse(HTMLHeader)
	check(err, "template.Parse failed")
	err = tmpl.Execute(c.buf, params)
	check(err, "template.Execute failed")

	textio.ReadFiles(files, func(line []byte, lineNo int, filename string) error {
		if lineNo == 1 {
			c.reset()
		}
		c.convert(line)
		if *autoFlash {
			c.buf.Flush()
		}
		return nil
	})

	// Footer
	params.RowCount = c.rows
	tmpl, err = template.New("f").Parse(HTMLFooter)
	check(err, "template.Parse failed")
	err = tmpl.Execute(c.buf, params)
	check(err, "template.Execute failed")
}

package template

import (
	"strconv"
	"text/template"

	"github.com/replicatedhq/kots/kotskinds/apis/kots/v1beta1"
	"github.com/replicatedhq/kots/pkg/crypto"
	identitytypes "github.com/replicatedhq/kots/pkg/identity/types"
)

type identityCtx struct {
	identityConfig *v1beta1.IdentityConfig
	appInfo        *ApplicationInfo
	cipher         *crypto.AESCipher
}

func newIdentityCtx(identityConfig *v1beta1.IdentityConfig, appInfo *ApplicationInfo, cipher *crypto.AESCipher) identityCtx {
	return identityCtx{
		identityConfig: identityConfig,
		appInfo:        appInfo,
		cipher:         cipher,
	}
}

// FuncMap represents the available functions in the identityCtx.
func (ctx identityCtx) FuncMap() template.FuncMap {
	return template.FuncMap{
		"IdentityServiceEnabled":      ctx.identityServiceEnabled,
		"IdentityServiceClientID":     ctx.identityServiceClientID,
		"IdentityServiceClientSecret": ctx.identityServiceClientSecret,
		"IdentityServiceRoles":        ctx.identityServiceRoles,
		"IdentityServiceName":         ctx.identityServiceName,
		"IdentityServicePort":         ctx.identityServicePort,
	}
}

func (ctx identityCtx) identityServiceEnabled() bool {
	if ctx.identityConfig == nil {
		return false
	}
	return ctx.identityConfig.Spec.Enabled
}

func (ctx identityCtx) identityServiceClientID() string {
	if ctx.identityConfig == nil {
		return ""
	}
	return ctx.identityConfig.Spec.ClientID
}

func (ctx identityCtx) identityServiceClientSecret() (string, error) {
	if ctx.identityConfig == nil || ctx.cipher == nil {
		return "", nil
	}
	return ctx.identityConfig.Spec.ClientSecret.GetValue(*ctx.cipher)
}

func (ctx identityCtx) identityServiceRoles() map[string]interface{} {
	m := map[string]interface{}{}

	if ctx.identityConfig != nil {
		for _, g := range ctx.identityConfig.Spec.Groups {
			m[g.ID] = g.RoleIDs
		}
	}

	return m
}

func (ctx identityCtx) identityServiceName() string {
	if ctx.appInfo == nil {
		return ""
	}
	return identitytypes.ServiceName(ctx.appInfo.Slug)
}

func (ctx identityCtx) identityServicePort() string {
	if ctx.appInfo == nil {
		return ""
	}
	return strconv.Itoa(int(identitytypes.ServicePort()))
}

