const (
	apiIdHeader       = "ID"
	apiNameHeader     = "NAME"
	apiContextHeader  = "CONTEXT"
	apiVersionHeader  = "VERSION"
	apiProviderHeader = "PROVIDER"
	apiStatusHeader   = "STATUS"

	defaultApiTableFormat = "table {{.Id}}\t{{.Name}}\t{{.Version}}\t{{.Context}}\t{{.LifeCycleStatus}}\t{{.Provider}}"
)

var queryParamAdded bool = false

// api holds information about an API for outputting
type api struct {
	id              string
	name            string
	context         string
	version         string
	provider        string
	lifeCycleStatus string
}

// creates a new api from utils.API
func newApiDefinitionFromAPI(a utils.API) *api {
	return &api{a.ID, a.Name, a.Context, a.Version, a.Provider,
		a.LifeCycleStatus}
}

// Id of api
func (a api) Id() string {
	return a.id
}

// Name of api
func (a api) Name() string {
	return a.name
}

// Context of api
func (a api) Context() string {
	return a.context
}

// Version of api
func (a api) Version() string {
	return a.version
}

// Lifecycle Status of api
func (a api) LifeCycleStatus() string {
	return a.lifeCycleStatus
}

// Provider of api
func (a api) Provider() string {
	return a.provider
}

// MarshalJSON marshals api using custom marshaller which uses methods instead of fields
func (a *api) MarshalJSON() ([]byte, error) {
	return formatter.MarshalJSON(a)
}

// GetAPIListFromEnv
// @param accessToken : Access Token for the environment
// @param environment : Environment name to use when getting the API List
// @param query : string to be matched against the API names
// @param limit : total # of results to return
// @return count (no. of APIs)
// @return array of API objects
// @return error
func GetAPIListFromEnv(accessToken, environment, query, limit string) (count int32, apis []utils.API, err error) {
	apiListEndpoint := utils.GetApiListEndpointOfEnv(environment, utils.MainConfigFilePath)
	return GetAPIList(accessToken, apiListEndpoint, query, limit)
}

// PrintAPIs
func PrintAPIs(apis []utils.API, format string) {
	if format == "" {
		format = defaultApiTableFormat
	} else if format == utils.JsonArrayFormatType {
		utils.ListArtifactsInJsonArrayFormat(apis, utils.ProjectTypeApi)
		return
	}

	// create api context with standard output
	apiContext := formatter.NewContext(os.Stdout, format)

	// create a new renderer function which iterate collection
	renderer := func(w io.Writer, t *template.Template) error {
		for _, a := range apis {
			if err := t.Execute(w, newApiDefinitionFromAPI(a)); err != nil {
				return err
			}
			_, _ = w.Write([]byte{'\n'})
		}
		return nil
	}

	// headers for table
	apiTableHeaders := map[string]string{
		"Id":              apiIdHeader,
		"Name":            apiNameHeader,
		"Context":         apiContextHeader,
		"Version":         apiVersionHeader,
		"LifeCycleStatus": apiStatusHeader,
		"Provider":        apiProviderHeader,
	}

	// execute context
	if err := apiContext.Write(renderer, apiTableHeaders); err != nil {
		fmt.Println("Error executing template:", err.Error())
	}
}

package html5

import (
	"bytes"
	"html/template"
	texttemplate "text/template"

	"github.com/bytesparadise/libasciidoc/pkg/renderer"
	"github.com/bytesparadise/libasciidoc/pkg/types"
	"github.com/pkg/errors"
	log "github.com/sirupsen/logrus"
)

var boldTextTmpl texttemplate.Template
var italicTextTmpl texttemplate.Template
var monospaceTextTmpl texttemplate.Template
var subscriptTextTmpl texttemplate.Template
var superscriptTextTmpl texttemplate.Template

// initializes the templates
func init() {
	boldTextTmpl = newTextTemplate("bold text", "<strong>{{ . }}</strong>")
	italicTextTmpl = newTextTemplate("italic text", "<em>{{ . }}</em>")
	monospaceTextTmpl = newTextTemplate("monospace text", "<code>{{ . }}</code>")
	subscriptTextTmpl = newTextTemplate("subscript text", "<sub>{{ . }}</sub>")
	superscriptTextTmpl = newTextTemplate("superscript text", "<sup>{{ . }}</sup>")
}

func renderQuotedText(ctx *renderer.Context, t *types.QuotedText) ([]byte, error) {
	elementsBuffer := bytes.NewBuffer(nil)
	for _, element := range t.Elements {
		b, err := renderElement(ctx, element)
		if err != nil {
			return nil, errors.Wrapf(err, "unable to render text quote")
		}
		_, err = elementsBuffer.Write(b)
		if err != nil {
			return nil, errors.Wrapf(err, "unable to render text quote")
		}
	}
	result := bytes.NewBuffer(nil)
	var tmpl texttemplate.Template
	switch t.Kind {
	case types.Bold:
		tmpl = boldTextTmpl
	case types.Italic:
		tmpl = italicTextTmpl
	case types.Monospace:
		tmpl = monospaceTextTmpl
	case types.Subscript:
		tmpl = subscriptTextTmpl
	case types.Superscript:
		tmpl = superscriptTextTmpl
	default:
		return nil, errors.Errorf("unsupported quoted text kind: '%v'", t.Kind)
	}
	err := tmpl.Execute(result, template.HTML(elementsBuffer.String())) //nolint: gosec
	if err != nil {
		return nil, errors.Wrapf(err, "unable to render monospaced quote")
	}
	log.Debugf("rendered bold quote: %s", result.Bytes())
	return result.Bytes(), nil
}

