	"gopkg.in/urfave/cli.v2"
)

// tmplProfileShow represents a profile within details view.
var tmplProfileShow = "Slug: \x1b[33m{{ .Slug }} \x1b[0m" + `
ID: {{ .ID }}
Username: {{ .Username }}
Email: {{ .Email }}
Active: {{ .Active }}
Admin: {{ .Admin }}
Created: {{ .CreatedAt.Format "Mon Jan _2 15:04:05 MST 2006" }}
Updated: {{ .UpdatedAt.Format "Mon Jan _2 15:04:05 MST 2006" }}
`

// Profile provides the sub-command for the profile API.
func Profile() *cli.Command {
	return &cli.Command{
		Name:  "profile",
		Usage: "Profile related sub-commands",
		Subcommands: []*cli.Command{
			{
				Name:  "show",
				Usage: "Show profile details",
				Flags: []cli.Flag{
					&cli.StringFlag{
						Name:  "format",
						Value: tmplProfileShow,
						Usage: "Custom output format",
					},
					&cli.BoolFlag{
						Name:  "json",
						Value: false,
						Usage: "Print in JSON format",
					},
					&cli.BoolFlag{
						Name:  "xml",
						Value: false,
						Usage: "Print in XML format",
					},
				},
				Action: func(c *cli.Context) error {
					return Handle(c, ProfileShow)
				},
			},
			{
				Name:  "token",
				Usage: "Show your token",
				Flags: []cli.Flag{
					&cli.StringFlag{
						Name:  "username",
						Value: "",
						Usage: "Username for authentication",
					},
					&cli.StringFlag{
						Name:  "password",
						Value: "",
						Usage: "Password for authentication",
					},
				},
				Action: func(c *cli.Context) error {
					return Handle(c, ProfileToken)
				},
			},
			{
				Name:  "update",
				Usage: "Update profile details",
				Flags: []cli.Flag{
					&cli.StringFlag{
						Name:  "slug",
						Value: "",
						Usage: "Provide a slug",
					},
					&cli.StringFlag{
						Name:  "username",
						Value: "",
						Usage: "Provide a username",
					},
					&cli.StringFlag{
						Name:  "email",
						Value: "",
						Usage: "Provide a email",
					},
					&cli.StringFlag{
						Name:  "password",
						Value: "",
						Usage: "Provide a password",
					},
				},
				Action: func(c *cli.Context) error {
					return Handle(c, ProfileUpdate)
				},
			},
		},
	}
}

// ProfileShow provides the sub-command to show profile details.
func ProfileShow(c *cli.Context, client umschlag.ClientAPI) error {
	record, err := client.ProfileGet()

	if err != nil {
		return err
	}

	if c.IsSet("json") && c.IsSet("xml") {
		return fmt.Errorf("conflict, you can only use json or xml at once")
	}

	if c.Bool("xml") {
		res, err := xml.MarshalIndent(record, "", "  ")

		if err != nil {
			return err
		}

		fmt.Fprintf(os.Stdout, "%s\n", res)
		return nil
	}

	if c.Bool("json") {
		res, err := json.MarshalIndent(record, "", "  ")

		if err != nil {
			return err
		}

		fmt.Fprintf(os.Stdout, "%s\n", res)
		return nil
	}

	tmpl, err := template.New(
		"_",
	).Funcs(
		globalFuncMap,
	).Funcs(
		sprigFuncMap,
	).Parse(
		fmt.Sprintf("%s\n", c.String("format")),
	)

	if err != nil {
		return err
	}

	return tmpl.Execute(os.Stdout, record)
}

// ProfileToken provides the sub-command to show your token.
func ProfileToken(c *cli.Context, client umschlag.ClientAPI) error {
	if !client.IsAuthenticated() {
		if !c.IsSet("username") {
			return fmt.Errorf("please provide a username")
		}

		if !c.IsSet("password") {
			return fmt.Errorf("please provide a password")
		}

		login, err := client.AuthLogin(
			c.String("username"),
			c.String("password"),
		)

		if err != nil {
			return err
		}

		client = umschlag.NewClientToken(
			c.String("server"),
			login.Token,
		)
	}

	record, err := client.ProfileToken()

	if err != nil {
		return err
	}

	fmt.Fprintf(os.Stdout, "%s\n", record.Token)
	return nil
}

// ProfileUpdate provides the sub-command to update the profile.
func ProfileUpdate(c *cli.Context, client umschlag.ClientAPI) error {
	record, err := client.ProfileGet()

	if err != nil {
		return err
	}

	changed := false

	if val := c.String("slug"); c.IsSet("slug") && val != record.Slug {
		record.Slug = val
		changed = true
	}

	if val := c.String("username"); c.IsSet("username") && val != record.Username {
		record.Username = val
		changed = true
	}

	if val := c.String("email"); c.IsSet("email") && val != record.Email {
		record.Email = val
		changed = true
	}

	if val := c.String("password"); c.IsSet("password") {
		record.Password = val
		changed = true
	}

	if changed {
		_, patch := client.ProfilePatch(
			record,
		)

		if patch != nil {
			return patch
		}

		fmt.Fprintf(os.Stderr, "Successfully updated\n")
	} else {
		fmt.Fprintf(os.Stderr, "Nothing to update...\n")
	}

	return nil
}

/*
Package el provides an interface and default implementation of expression
language (EL) interpreter for struct tags.

Default implementation is simply based on "text/template".
*/
package el

import (
	"bytes"
	"fmt"
	"strings"
	"text/template"

	"github.com/nikolay-turpitko/structor/funcs/use"
)

// Interpreter is an interface of EL interpreter.
type Interpreter interface {
	// Execute parses and executes expression with a given context.
	Execute(expression string, ctx *Context) (result interface{}, err error)
}

// The InterpreterFunc type is an adapter to allow the use of ordinary
// functions as EL interpreter. If f is a function with the appropriate
// signature, InterpreterFunc(f) is a Interpreter that calls f.
type InterpreterFunc func(string, *Context) (interface{}, error)

// Execute calls f(s, ctx).
func (f InterpreterFunc) Execute(s string, ctx *Context) (interface{}, error) {
	return f(s, ctx)
}

// Context is a context, passed to interpreter.
// It contains information about currently processed field, struct and extra.
type Context struct {
	// Name of the currently processed field.
	Name string
	// Name of the currently processed field including type.
	LongName string
	// Current value of the currently processed filed.
	Val interface{}
	// All other tags of the currently processed field.
	Tags map[string]string
	// Currently processed struct.
	Struct interface{}
	// Extra context structure.
	Extra interface{}
	// Temporary partial result evaluated on the current substruct.
	Sub interface{}
	// Function, which knows how to evaluate expression with different
	// interpreter.
	EvalExpr EvalExprFunc
}

// EvalExprFunc is a type of function, which knows how to evaluate given
// expression using given interpreter name and context.
// It is used to implement special predefined custom function "eval", available
// within EL.
type EvalExprFunc func(
	interpreterName, expression string,
	context *Context) (interface{}, error)

// DefaultInterpreter is a default implementation of Interpreter,
// which is based on "text/template".
//
// Besides Funcs passed to it, DefaultInterpreter creates these additional
// custom function for use in EL expressions:
//
//  - set
//  - eval
//
// Function "set" with signature `func (r interface{}) interface{}` passes
// argument to result, but stores it internally to be used as an expression
// result. It's intention is to set expression result to some concrete type,
// other than string (which is only type "text/template" allows by design).
// Simply put, when you interested in interface{} result and not in it's
// default string representation, use "set" to store result at the end of
// expression.
//
// Function "eval" with signature `func(intrpr, expr string) (interface{}, error)`
// can be used to evaluate given expression with given interpreter.
// This can be useful to evaluate expression passed as a string within context.
// This feature works with support of the calling code, which passes actual
// implementation of the "eval" function in Context.EvalExpr().
// Interpreter name should be known to calling code. For example, for known
// implementation (structor.NewEvaluator()) interpreter name is a tag name,
// onto which given interpreter is mapped during creation of evaluator.
//
// Restrictions of "text/template" package applied to custom functions.
type DefaultInterpreter struct {
	// Custom functions, available for use in EL expressions.
	Funcs use.FuncMap
	// Left delimiter for templates.
	LeftDelim string
	// Right delimiter for templates.
	RightDelim string
	// Automatically enclose passed expression into delimiters before
	// interpretation (if it is not already enclosed). This allows to pass
	// simplified expressions. For example, `atoi "42"` instead of
	// `{{atoi "42"}}`.
	AutoEnclose bool
}

// Execute implements Interpreter.Execute()
func (i *DefaultInterpreter) Execute(
	expression string,
	ctx *Context) (interface{}, error) {
	funcs := template.FuncMap{}
	for k, v := range i.Funcs {
		funcs[k] = v
	}
	var res interface{}
	resultEvaluated := false
	funcs["set"] = func(r interface{}) interface{} {
		res = r
		resultEvaluated = true
		return r
	}
	funcs["eval"] = func(intrpr, expr string) (interface{}, error) {
		return ctx.EvalExpr(intrpr, expr, ctx)
	}
	templName := fmt.Sprintf("<<%s>>", ctx.LongName)
	left := i.LeftDelim
	right := i.RightDelim
	if left == "" {
		left = "{{"
	}
	if right == "" {
		right = "}}"
	}
	if i.AutoEnclose &&
		!(strings.HasPrefix(expression, left) &&
			strings.HasSuffix(expression, right)) {
		expression = fmt.Sprintf("%s%s%s", left, expression, right)
	}
	t, err := template.
		New(templName).
		Delims(left, right).
		Funcs(funcs).
		Parse(expression)
	if err != nil {
		return nil, err
	}
	var buf bytes.Buffer
	err = t.Execute(&buf, ctx)
	if err != nil {
		return nil, err
	}
	if resultEvaluated {
		return res, nil
	}
	return buf.String(), nil
}

package calldata

import (
	"bytes"
	"fmt"
	"io"
	"text/tabwriter"
	"text/template"
	"time"

	"github.com/google/uuid"
)

var (
	tmpl *template.Template
)

func init() {
	fnMap := make(template.FuncMap, len(funcs))
	for _, fn := range funcs {
		fnMap[fn.Name] = fn.Func
	}

	tmpl = template.New("calldata").Funcs(fnMap)
}

type Var struct {
	Name string
	Desc string
}

var (
	variables = []Var{
		{Name: "RequestNumber", Desc: "Request number for data"},
		{Name: "Timestamp", Desc: "Timestamp in RFC3339 format"},
		{Name: "TimestampUnix", Desc: "Timestamp as unix time in seconds"},
		{Name: "TimestampUnixMilli", Desc: "Timestamp as unix time in milliseconds"},
		{Name: "TimestampUnixNano", Desc: "Timestamp as unix time in nanoseconds"},
		{Name: "UUID", Desc: "Generated UUIDv4"},
	}
)

type CallData struct {
	RequestNumber      int64
	Timestamp          string
	TimestampUnix      int64
	TimestampUnixMilli int64
	TimestampUnixNano  int64
	UUID               string
}

func ParseTemplate(data []byte) (*template.Template, error) {
	t, err := tmpl.Parse(string(data))
	if err != nil {
		return nil, err
	}

	return t, nil
}

// PrintFuncs prints list of functions to output.
func PrintFuncs(output io.Writer) {
	w := tabwriter.NewWriter(output, 0, 0, 4, ' ', 0)

	fmt.Fprintln(w, "Template variables:\t")
	for _, vr := range variables {
		fmt.Fprintf(w, "  .%s\t%s\n", vr.Name, vr.Desc)
	}

	fmt.Fprintln(w, "\t")
	fmt.Fprintln(w, "Template functions:\t")
	for _, fn := range funcs {
		fmt.Fprintf(w, "  %s\t%s\n", fn.Name, fn.Desc)
	}
	w.Flush()
}

func NewCallData(reqNum int) *CallData {
	now := time.Now()
	nowNano := now.UnixNano()

	return &CallData{
		RequestNumber:      int64(reqNum),
		Timestamp:          now.Format(time.RFC3339),
		TimestampUnix:      now.Unix(),
		TimestampUnixMilli: nowNano / 1e6,
		TimestampUnixNano:  nowNano,
		UUID:               uuid.NewString(),
	}
}

func (c *CallData) Execute(tmpl *template.Template) (*bytes.Buffer, error) {
	b := new(bytes.Buffer)
	if err := tmpl.Execute(b, c); err != nil {
		return nil, err
	}

	return b, nil
}

package main

import (
	"bytes"
	"fmt"
	"log"
	"net/http"
	"regexp"
	"strings"
	"sync"
	"text/template"
	"time"
)

type handler struct {
	cfg       config
	mu        sync.Mutex
	repoCache struct {
		repos   []repo
		updated time.Time
	}
	templateCache struct {
		data    []byte
		updated time.Time
	}
}

func (h *handler) handle(w http.ResponseWriter, req *http.Request) {
	h.mu.Lock()
	defer h.mu.Unlock()

	// Check if we need to reload Github data.
	// FIXME: Should happen in the background as it can take quite a while.
	repoDataUpdated := false
	if time.Since(h.repoCache.updated) > h.cfg.RepoCacheTime {
		h.repoCache.repos = getAllRepositories(h.cfg)
		h.repoCache.updated = time.Now()
		repoDataUpdated = true
	}

	// Check if we need to re-evaluate the template.
	if repoDataUpdated || time.Since(h.templateCache.updated) > h.cfg.TemplateCacheTime {
		bs, err := generateOverview(h.repoCache.repos)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		h.templateCache.data = bs
		h.templateCache.updated = time.Now()
	}

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Write(h.templateCache.data)
}

func getAllRepositories(cfg config) []repo {
	var rs []repo
	for _, rc := range cfg.Repos {
		r, err := getRepository(rc)
		if err != nil {
			log.Printf("Getting %s: %v", rc.GithubName, err)
			continue
		}
		rs = append(rs, r)
	}

	return rs
}

func getRepository(rc repoCfg) (repo, error) {
	gr, err := getRepo(rc.GithubName)
	if err != nil {
		return repo{}, err
	}

	rs, err := gr.getReleases(5) // At most five releases per repo
	if err != nil {
		return repo{}, err
	}

	r := repo{
		FriendlyName: rc.FriendlyName,
		GithubName:   gr.FullName,
		CssName:      strings.ToLower(strings.Replace(rc.FriendlyName, " ", "-", -1)),
		IsSyncthing:  strings.Compare(rc.FriendlyName, "Syncthing")==0,
		Description:  gr.Description,
		GithubURL:    gr.URL,
	}

	for _, rel := range rs {
		ver := version{
			Version: rel.Tag,
		}
		for _, as := range rel.Assets {
			ast := asset{
				URL: as.URL,
			}

			if val, err := extractExpr(rc.NameExpr, as.Name); err != nil {
				log.Printf("%s %s: %v (skipping)", rc.GithubName, rel.Tag, err)
				continue
			} else {
				ast.Name = val
			}

			if val, err := extractExpr(rc.OSExpr, as.Name); err != nil {
				log.Printf("%s %s: %v (skipping)", rc.GithubName, rel.Tag, err)
				continue
			} else {
				ast.OS = val
			}

			if val, err := extractExpr(rc.ArchExpr, as.Name); err != nil {
				log.Printf("%s %s: %v (skipping)", rc.GithubName, rel.Tag, err)
				continue
			} else {
				ast.Arch = val
			}

			ver.Assets = append(ver.Assets, ast)
		}
		r.Versions = append(r.Versions, ver)
	}

	return r, nil
}

func generateOverview(repos []repo) ([]byte, error) {
	fm := template.FuncMap{
		"now": time.Now,
	}
	tmpl := template.Must(template.New("index.go.html").Funcs(fm).ParseGlob("*.go.html"))

	buf := new(bytes.Buffer)
	if err := tmpl.Execute(buf, repos); err != nil {
		log.Printf("Template execution: %s", err)
		return nil, err
	}

	return buf.Bytes(), nil
}

func extractExpr(expr, val string) (string, error) {
	if !strings.HasPrefix(expr, "/") {
		return expr, nil
	}

	re, err := regexp.Compile(expr[1 : len(expr)-1])
	if err != nil {
		return "", err
	}

	ms := re.FindStringSubmatch(val)
	if len(ms) != 2 {
		return "", fmt.Errorf("%s doesn't match %q", expr, val)
	}

	return ms[1], nil
}

