package util

import (
	"bytes"
	"fmt"
	"math"
	"os"
	"os/exec"
	"os/user"
	"runtime"
	"sort"
	"strings"
	"text/template"

	"github.com/pkg/errors"
)

type Data map[string]interface{}

// Render text template with given `variables` Render-context
func Render(tmpl *template.Template, variables map[string]interface{}) (string, error) {

	var buf strings.Builder

	if err := tmpl.Execute(&buf, variables); err != nil {
		return "", errors.Wrap(err, "Failed to render template")
	}
	return buf.String(), nil
}

// Home returns the home directory for the executing user.
func Home() (string, error) {
	u, err := user.Current()
	if nil == err {
		return u.HomeDir, nil
	}

	if "windows" == runtime.GOOS {
		return homeWindows()
	}

	return homeUnix()
}

func homeUnix() (string, error) {
	if home := os.Getenv("HOME"); home != "" {
		return home, nil
	}

	var stdout bytes.Buffer
	cmd := exec.Command("sh", "-c", "eval echo ~$USER")
	cmd.Stdout = &stdout
	if err := cmd.Run(); err != nil {
		return "", err
	}

	result := strings.TrimSpace(stdout.String())
	if result == "" {
		return "", errors.New("blank output when reading home directory")
	}

	return result, nil
}

func homeWindows() (string, error) {
	drive := os.Getenv("HOMEDRIVE")
	path := os.Getenv("HOMEPATH")
	home := drive + path
	if drive == "" || path == "" {
		home = os.Getenv("USERPROFILE")
	}
	if home == "" {
		return "", errors.New("HOMEDRIVE, HOMEPATH, and USERPROFILE are blank")
	}

	return home, nil
}

func GetArgs(argsMap map[string]string, args []string) ([]string, map[string]string) {
	targetMap := make(map[string]string, len(argsMap))
	for k, v := range argsMap {
		targetMap[k] = v
	}
	targetSlice := make([]string, len(args))
	copy(targetSlice, args)

	for _, arg := range targetSlice {
		splitArg := strings.SplitN(arg, "=", 2)
		if len(splitArg) < 2 {
			continue
		}
		targetMap[splitArg[0]] = splitArg[1]
	}

	for arg, value := range targetMap {
		cmd := fmt.Sprintf("%s=%s", arg, value)
		targetSlice = append(targetSlice, cmd)
	}
	sort.Strings(targetSlice)
	return targetSlice, targetMap
}

// Round returns the result of rounding 'val' according to the specified 'precision' precision (the number of digits after the decimal point)。
// and precision can be negative number or zero
func Round(val float64, precision int) float64 {
	p := math.Pow10(precision)
	return math.Floor(val*p+0.5) / p
}

// ArchAlias returns the alias of cpu's architecture.
// amd64: x86_64
// arm64: aarch64
func ArchAlias(arch string) string {
	switch arch {
	case "amd64":
		return "x86_64"
	case "arm64":
		return "aarch64"
	default:
		return ""
	}
}

package expand

import (
	"bytes"
	"fmt"
	sprig "github.com/Masterminds/sprig/v3"
	"github.com/mmlt/kubectl-tmplt/pkg/expand/files"
	"github.com/mmlt/kubectl-tmplt/pkg/util/yamlx"
	"path/filepath"
	"strings"
	"text/template"
)

// Run expands a template text with values and returns the resulting text.
// Path is used to support {{ .Files }}.
// See https://golang.org/pkg/text/template/
func Run(environ []string, path string, text []byte, values, passed yamlx.Values, customFn template.FuncMap) ([]byte, error) {
	env := OSEnvironment(environ)

	// get template functions
	functions := getDefaultFunctions()
	// override Sprig function to make sure a sanitized environment is used.
	functions["env"] = func(s string) string { return env[s] }
	functions["expandenv"] = func(s string) string { return "<expandenv is not supported>" }
	// add custom functions
	for n, f := range customFn {
		functions[n] = f
	}

	// params contains values and methods that are accessed via {{ .Values }}, {{ .Get }} and {{ .Files }}
	var params = struct {
		Values yamlx.Values
		Get    yamlx.Values
		Files  files.Dir
	}{
		Values: values,
		Get:    passed,
		Files:  files.Dir(filepath.Dir(path)),
	}

	return expand(path, text, functions, params)
}

// Expand expands a template text with functions and params and returns the resulting text.
// Missing keys result in an error.
func expand(path string, text []byte, functions template.FuncMap, params interface{}) ([]byte, error) {
	// Create template with functions and text.
	tmpl, err := template.New("input").Funcs(functions).Option("missingkey=invalid").Parse(string(text))
	if err != nil {
		return nil, fmt.Errorf("parse: %w", err)
	}

	var out bytes.Buffer
	err = tmpl.Execute(&out, &params)
	if err != nil {
		return nil, fmt.Errorf("execute: %w", err)
	}

	return out.Bytes(), nil
}

// GetDefaultFunctions returns a map with functions that are commonly used in templates.
// It consists of Sprig (generic)functions and TOML,JSON,YAML conversion functions.
func getDefaultFunctions() template.FuncMap {
	answer := sprig.TxtFuncMap()

	// add extra functionality
	answer["toToml"] = files.ToToml
	answer["toYaml"] = files.ToYaml
	answer["fromYaml"] = files.FromYaml
	answer["toJson"] = files.ToJson
	answer["fromJson"] = files.FromJson
	answer["indexOrDefault"] = indexOrDefault

	// add functions that sprig doesn't implement cross-platform (that don't work on windows)
	answer["filebase"] = filepath.Base
	answer["filedir"] = filepath.Dir
	answer["fileclean"] = filepath.Clean
	answer["fileext"] = filepath.Ext

	return answer
}

// OSEnvironment converts a []string with "key=value" items to a map["key"]="value".
func OSEnvironment(environ []string) map[string]string {
	result := make(map[string]string)
	for _, s := range environ {
		sl := strings.SplitN(s, "=", 2)
		if len(sl) != 2 {
			continue
		}
		result[sl[0]] = sl[1]
	}
	return result
}

package utils

import (
	"bytes"
	"github.com/kakuilan/kgo"
	"strings"
	"text/template"
)

func UnicodeIndex(str, substr string) int {
	// 子串在字符串的字节位置
	result := strings.Index(str, substr)
	if result >= 0 {
		// 获得子串之前的字符串并转换成[]byte
		prefix := []byte(str)[0:result]
		// 将子串之前的字符串转换成[]rune
		rs := []rune(string(prefix))
		// 获得子串之前的字符串的长度，便是子串在字符串的字符位置
		result = len(rs)
	}

	return result
}

func ReplaceString(pattern, replace, src string) (string, error) {
	if r, err := GetRegexp(pattern); err == nil {
		return r.ReplaceAllString(src, replace), nil
	} else {
		return "", err
	}
}

func Contains(haystack, needle string, startOffset ...int) int {
	length := len(haystack)
	offset := 0
	if len(startOffset) > 0 {
		offset = startOffset[0]
	}
	if length == 0 || offset > length || -offset > length {
		return -1
	}

	if offset < 0 {
		offset += length
	}
	pos := strings.Index(strings.ToLower(haystack[offset:]), strings.ToLower(needle))
	if pos == -1 {
		return -1
	}
	return pos + offset
}

// 字符串模板解析
func TemplateResolve(temp string, data interface{}) string {
	t, _ := template.New("string-temp").Parse(temp)
	var tmplBytes bytes.Buffer

	err := t.Execute(&tmplBytes, data)
	if err != nil {
		panic(err)
	}
	return tmplBytes.String()
}

func ReverStrTemplate(temp, str string, res map[string]interface{}) {
	index := UnicodeIndex(temp, "{")
	ei := UnicodeIndex(temp, "}") + 1
	next := kgo.KStr.Trim(temp[ei:], " ")
	nextContain := UnicodeIndex(next, "{")
	nextIndexValue := next
	if nextContain != -1 {
		nextIndexValue = kgo.KStr.Substr(next, 0, nextContain)
	}
	key := temp[index+1 : ei-1]
	// 如果后面没有内容了，则取字符串的长度即可
	var valueLastIndex int
	if nextIndexValue == "" {
		valueLastIndex = kgo.KStr.MbStrlen(str)
	} else {
		valueLastIndex = UnicodeIndex(str, nextIndexValue)
	}
	value := kgo.KStr.Trim(kgo.KStr.Substr(str, index, valueLastIndex), " ")
	res[key] = value
	// 如果后面的还有需要解析的，则递归调用解析
	if nextContain != -1 {
		ReverStrTemplate(next, kgo.KStr.Trim(kgo.KStr.Substr(str, UnicodeIndex(str, value)+kgo.KStr.MbStrlen(value), kgo.KStr.MbStrlen(str))), res)
	}
}

func B2S(bs []uint8) string {
	ba := []byte{}
	for _, b := range bs {
		ba = append(ba, byte(b))
	}
	return string(ba)
}

func IdsStrToIdsIntGroup(keys string) []int64 {
	IDS := make([]int64, 0)
	ids := strings.Split(keys, ",")
	for i := 0; i < len(ids); i++ {
		ID := kgo.KConv.Str2Int(ids[i])
		IDS = append(IDS, int64(ID))
	}
	return IDS
}

// 获取部门
// isP 是父ID 否则子ID
func DeptPCIds(deptIds []string, id int64, isP bool) []int64 {
	pRes := make([]int64, 0)
	cRes := make([]int64, 0)
	is := true
	for _, deptId := range deptIds {
		did := kgo.KConv.Str2Int64(deptId)
		if is {
			pRes = append(pRes, did)
		}
		if kgo.KConv.Str2Int64(deptId) == id {
			is = false
		}
		if !is {
			cRes = append(cRes, did)
		}
	}
	if isP {
		return pRes
	} else {
		return cRes
	}
}

