		called = true
		v := &engine.Env{}
		v.SetInt("Containers", 1)
		v.SetInt("Images", 42000)
		if _, err := v.WriteTo(job.Stdout); err != nil {
			return job.Error(err)
		}
		return engine.StatusOK
	})

	r := httptest.NewRecorder()
	req, err := http.NewRequest("GET", "/info", nil)
	if err != nil {
		t.Fatal(err)
	}
	// FIXME getting the version should require an actual running Server
	if err := ServeRequest(eng, api.APIVERSION, r, req); err != nil {
		t.Fatal(err)
	}
	if !called {
		t.Fatalf("handler was not called")
	}

	out := engine.NewOutput()
	i, err := out.AddEnv()
	if err != nil {
		t.Fatal(err)
	}
	if _, err := io.Copy(out, r.Body); err != nil {
		t.Fatal(err)
	}
	out.Close()
	{
		expected := 42000
		result := i.GetInt("Images")
		if expected != result {
			t.Fatalf("%#v\n", result)
		}
	}
	{
		expected := 1
		result := i.GetInt("Containers")
		if expected != result {
			t.Fatalf("%#v\n", result)
		}
	}
	{
		expected := "application/json"
		if result := r.HeaderMap.Get("Content-Type"); result != expected {
			t.Fatalf("%#v\n", result)
		}
	}
}

package main

import (
	"context"
	"os"
	"os/signal"

	"github.com/spf13/cobra"
	"go.uber.org/zap"

	"github.com/anexia-it/go-quickstart"
)

var cmdLock = &cobra.Command{
	Use:   "lock <key>",
	Short: "Acquires and holds lock for given key until canceled",
	Run: func(cmd *cobra.Command, args []string) {
		logger := quickstart.GetLogger("watch")

		if len(args) != 1 {
			logger.Error("Required argument missing (key)")
			return
		}

		address, _ := cmd.Flags().GetString("address")

		consulAPI, err := quickstart.NewConsulAPI(address)
		if err != nil {
			logger.Error("Could not initialize consul API", zap.Error(err))
			return
		}

		// Handle CTRL+C
		sigChan := make(chan os.Signal, 1)
		defer close(sigChan)
		signal.Notify(sigChan, os.Interrupt)

		cancelContext, cancel := context.WithCancel(context.Background())
		defer cancel()

		go func() {
			sig := <-sigChan
			logger.Info("Signal received", zap.Stringer("signal", sig))
			cancel()
		}()

		// Obtain the lock...
		err = consulAPI.WithLock(args[0], func() error {
			logger.Info("Lock obtained")

			// ... and hold it until this command is canceled
			<-cancelContext.Done()
			return nil
		})

		if err != nil {
			logger.Error("Failed to obtain lock", zap.Error(err))
			return
		}
		logger.Info("Lock released")
	},
}

func init() {
	cmdLock.Flags().StringP("address", "a", "192.168.56.101:8500", "Consul address")
	cmdRoot.AddCommand(cmdLock)
}

