package main

import (
	"fmt"
	"log"
	"net"
	"unsafe"

	"encoding/binary"

	"golang.org/x/sys/unix"
)

// Params of a Jail
type Params map[string]interface{}

func main() {
	params := make(Params)
	params["name"] = "teste"
	params["host.hostname"] = "teste.bla"
	params["path"] = "/jails/katz"
	params["persist"] = ""
	// TODO: IP does not work. jail_set accepts but doesnt sets anything
	params["ip4.addr"] = "192.168.0.222"
	params["ip6.addr"] = "fd00:1234:abcd::1"
	params["securelevel"] = 3

	iov, err := params.buildIovec()
	if err != nil {
		log.Fatalf("%v\n", err)
	}
	for k, v := range iov {
		fmt.Printf("%d %v\n", k, v)
	}
	err = getSet(sysJailSet, iov, CreateFlag)
	if err != nil {
		log.Fatalf("%v\n", err)
	}

}

func (p Params) buildIovec() ([]unix.Iovec, error) {
	iovSize := (len(p)) * 2
	iovec := make([]unix.Iovec, iovSize)
	var itr int
	for paramKey, paramValue := range p {

		// Add Key to IOV
		keyBytes, err := unix.ByteSliceFromString(paramKey)
		if err != nil {
			return nil, err
		}
		pKey := (*byte)(unsafe.Pointer(&keyBytes[0]))

		iovec[itr] = unix.Iovec{
			Base: pKey,
			Len:  uint64(len(keyBytes)),
		}
		itr++

		var valLen uint64
		var valBytes []byte
		var pVal *byte
		// Add Value to IOV
		if paramValue != nil {
			switch v := paramValue.(type) {
			case string:
				if paramKey == "ip4.addr" || paramKey == "ip6.addr" {
					ip := net.ParseIP(v)
					if ip == nil {
						return nil, fmt.Errorf("Unparseable IP")
					}
					pVal = (*byte)(unsafe.Pointer(&ip[0]))
					valLen = uint64(len(valBytes))
				} else {
					valBytes, err = unix.ByteSliceFromString(v)
					if err != nil {
						return nil, err
					}
					pVal = (*byte)(unsafe.Pointer(&valBytes[0]))
					valLen = uint64(len(valBytes))
				}
			case int:
				//valBytes = IntToByteArray(int64(v))
				val := uint32(v)
				a := make([]byte, 4)
				binary.BigEndian.PutUint32(a, val)
				pVal = (*byte)(unsafe.Pointer(&a[0]))
				valLen = uint64(len(a))
			}

		}

		iovec[itr] = unix.Iovec{
			Base: pVal,
			Len:  valLen,
		}
		itr++
	}
	return iovec, nil
}

// getSet performas the given syscall with the params and flags provided
func getSet(call int, iov []unix.Iovec, flags uintptr) error {
	_, _, e1 := unix.Syscall(uintptr(call), uintptr(unsafe.Pointer(&iov[0])), uintptr(len(iov)), flags)
	if e1 != 0 {
		switch call {
		case sysJailGet:
			switch int(e1) {
			case ErrJailGetFaultOutsideOfAllocatedSpace:
				return fmt.Errorf("fault outside of allocated space: %d", e1)
			case enoent:
				return fmt.Errorf("jail referred to either does not exist or is inaccessible: %d", e1)
			case einval:
				return fmt.Errorf("invalid param provided: %d", e1)
			}
		case sysJailSet:
			switch int(e1) {
			case eperm:
				return fmt.Errorf("not allowed or restricted: %d", e1)
			case ErrJailSetFaultOutsideOfAllocatedSpace:
				return fmt.Errorf("fault outside of allocated space: %d", e1)
			case ErrJailSetParamNotExist, ErrJailSetParamWrongSize:
				return fmt.Errorf("invalid param provided: %d", e1)
			case ErrJailSetUpdateFlagNotSet:
				return fmt.Errorf("set update flag not set: %d", e1)
			case ErrJailSetNameTooLong:
				return fmt.Errorf("set name too long: %d", e1)
			case ErrJailSetNoIDsLeft:
				return fmt.Errorf("no JID's left: %d", e1)
			}
		}
	}
	return nil
}

func IntToByteArray(num int64) []byte {
	size := int(unsafe.Sizeof(num))
	arr := make([]byte, size)
	for i := 0; i < size; i++ {
		byt := *(*uint8)(unsafe.Pointer(uintptr(unsafe.Pointer(&num)) + uintptr(i)))
		arr[i] = byt
	}
	return arr
}

package sqlserver_extended

import (
	"database/sql"
	"strconv"
	"sync"
	"time"
	"strings"

	_ "github.com/denisenkom/go-mssqldb" // go-mssqldb initialization
	"github.com/influxdata/telegraf"
	"github.com/influxdata/telegraf/plugins/inputs"
)

// SQLServerExtended struct
type SQLServerExtended struct {
	Servers       []string `toml:"servers"`
	Queries       []string `toml:"queries"`
	ResultByRow   bool `toml:"result_by_row"`
	queries       MapQuery
	isInitialized bool
}

// Query struct
type Query struct {
	Script         string
	ResultByRow    bool
	OrderedColumns []string
}

// MapQuery type
type MapQuery map[string]Query

const defaultServer = "Server=.;app name=telegraf;log=1;"

const sampleConfig = `
  ## Specify instances to monitor with a list of connection strings.
  ## All connection parameters are optional.
  ## By default, the host is localhost, listening on default port, TCP 1433.
  ##   for Windows, the user is the currently running AD user (SSO).
  ##   See https://github.com/denisenkom/go-mssqldb for detailed connection
  ##   parameters, in particular, tls connections can be created like so:
  ##   "encrypt=true;certificate=<cert>;hostNameInCertificate=<SqlServer host fqdn>"
  # servers = [
  #  "Server=192.168.1.10;Port=1433;User Id=<user>;Password=<pw>;app name=telegraf;log=1;",
  # ]

  # queries = ["select 'measurement_name' as measurement, some_data as value FROM your_table", "add one more query"]
`

// SampleConfig return the sample configuration
func (s *SQLServerExtended) SampleConfig() string {
	return sampleConfig
}

// Description return plugin description
func (s *SQLServerExtended) Description() string {
	return "Read metrics from Microsoft SQL Server"
}

type scanner interface {
	Scan(dest ...interface{}) error
}

func initQueries(s *SQLServerExtended) {
	s.queries = make(MapQuery)
	queries := s.queries

	i := 0
	for _, quer := range s.Queries {
		queries["custom_"+strconv.Itoa(i)] = Query{Script: sqlPrefix + quer, ResultByRow: s.ResultByRow}
		i += 1
	}

	// Set a flag so we know that queries have already been initialized
	s.isInitialized = true
}

// Gather collect data from SQL Server
func (s *SQLServerExtended) Gather(acc telegraf.Accumulator) error {
	if !s.isInitialized {
		initQueries(s)
	}

	if len(s.Servers) == 0 {
		s.Servers = append(s.Servers, defaultServer)
	}

	var wg sync.WaitGroup

	for _, serv := range s.Servers {
		for _, query := range s.queries {
			wg.Add(1)
			go func(serv string, query Query) {
				defer wg.Done()
				acc.AddError(s.gatherServer(serv, query, acc))
			}(serv, query)
		}
	}

	wg.Wait()
	return nil
}

func (s *SQLServerExtended) gatherServer(server string, query Query, acc telegraf.Accumulator) error {
	// deferred opening
	conn, err := sql.Open("mssql", server)
	if err != nil {
		return err
	}
	defer conn.Close()

	// execute query
	rows, err := conn.Query(query.Script)
	if err != nil {
		return err
	}
	defer rows.Close()

	// grab the column information from the result
	query.OrderedColumns, err = rows.Columns()
	if err != nil {
		return err
	}

	for rows.Next() {
		err = s.accRow(query, acc, rows)
		if err != nil {
			return err
		}
	}
	return rows.Err()
}

func (s *SQLServerExtended) accRow(query Query, acc telegraf.Accumulator, row scanner) error {
	var columnVars []interface{}
	var fields = make(map[string]interface{})

	// store the column name with its *interface{}
	columnMap := make(map[string]*interface{})
	for _, column := range query.OrderedColumns {
		columnMap[column] = new(interface{})
	}
	// populate the array of interface{} with the pointers in the right order
	for i := 0; i < len(columnMap); i++ {
		columnVars = append(columnVars, columnMap[query.OrderedColumns[i]])
	}
	// deconstruct array of variables and send to Scan
	err := row.Scan(columnVars...)
	if err != nil {
		return err
	}

	// measurement: identified by the header
	// tags: all other fields with column name != 'field_%'
	tags := map[string]string{}
	var measurement string
	for header, val := range columnMap {
		if str, ok := (*val).(string); ok {
			if header == "measurement" {
				measurement = str
			} else if !strings.HasPrefix(header, "field_") {
				tags[header] = str
			}
		}
	}

	if measurement == "" {
		measurement = "sqlserver_extended"
	}

	if query.ResultByRow {
		acc.AddFields(measurement,
			map[string]interface{}{"value": *columnMap["value"]},
			tags, time.Now())
	} else {
		// values
		for header, val := range columnMap {
		    if strings.HasPrefix(header, "field_"){
				fields[strings.Split(header, "_")[1]] = (*val)
			}
		}
		acc.AddFields(measurement, fields, tags, time.Now())
	}
	return nil
}

func init() {
	inputs.Add("sqlserver_extended", func() telegraf.Input {
		return &SQLServerExtended{}
	})
}

