package httpresolver

import (
	"errors"
	"fmt"
	"net"
	"net/http"
	"strings"
	"time"

	"github.com/etf1/kafka-message-scheduler-admin/server/helper"
	"github.com/etf1/kafka-message-scheduler-admin/server/resolver/schedulers"
	log "github.com/sirupsen/logrus"
)

const (
	SchedulerDefaultPort = "8000"
	DefaultTimeout       = 2 * time.Second
)

var (
	ErrPartialResults = errors.New("resolver: partial results")
	ErrNoResults      = errors.New("resolver: no results")
)

type Scheduler struct {
	HostName  string     `json:"name"`
	HTTPPort  string     `json:"http_port"`
	Instances []Instance `json:"instances"`
}

type Instance struct {
	IP               net.IP   `json:"ip"`
	HostNames        []string `json:"hostname"`
	Topics           []string `json:"topics"`
	HistoryTopic     string   `json:"history_topic"`
	BootstrapServers string   `json:"bootstrap_servers"`
}

func (s Scheduler) Name() string {
	return s.HostName
}

func (s Scheduler) BootstrapServers() string {
	if len(s.Instances) > 0 {
		return s.Instances[0].BootstrapServers
	}
	return ""
}

func (s Scheduler) Topics() []string {
	if len(s.Instances) > 0 {
		return s.Instances[0].Topics
	}
	return nil
}

func (s Scheduler) History() string {
	if len(s.Instances) > 0 {
		return s.Instances[0].HistoryTopic
	}
	return ""
}

func (i Instance) Name() string {
	if len(i.HostNames) > 0 {
		return i.HostNames[0]
	}
	return i.IP.String()
}

type Resolver struct {
	Hosts []string
}

func NewResolver(hosts []string) Resolver {
	return Resolver{
		Hosts: hosts,
	}
}

func GetInfo(host string, timeout time.Duration) (resp *http.Response, err error) {
	return helper.Get(host, "/info", timeout)
}

func (r Resolver) List() ([]schedulers.Scheduler, error) {
	if len(r.Hosts) == 0 {
		return nil, fmt.Errorf("hosts undefined")
	}

	result := []schedulers.Scheduler{}

	for _, shost := range r.Hosts {
		host := shost

		log.Printf("scheduler host=>%v<", shost)

		port := SchedulerDefaultPort
		if strings.Contains(shost, ":") {
			host = strings.Split(shost, ":")[0]
			port = strings.Split(shost, ":")[1]
		}

		// renvoie la liste des ips pour un host donné: ex: google.com => [172.16.17.32 fd00:a516:7c1b:17cd:6d81:2137:bd2a:2c5b]
		ips, err := net.LookupIP(host)
		if err != nil {
			log.Errorf("unable to lookup ip for host %v: %v", host, err)
		}

		sch := Scheduler{
			HostName: host,
			HTTPPort: port,
		}

		log.Infof("ips: %+v", ips)

		for _, ip := range ips {
			log.Printf("ip: %v", ip)

			// keep only v4 ips
			if ip.To4() != nil {
				log.Printf("ip is v4: %v", ip)
				names, err := net.LookupAddr(ip.String())
				if err != nil {
					log.Errorf("unable to lookup addr for ip %v: %v", ip, err)
					continue
				}

				instance := Instance{
					IP:        ip,
					HostNames: names,
				}

				info, err := getKafkaInfo(instance.Name() + ":" + port)
				if err != nil {
					log.Errorf("unable to get kafka info for instance %v: %v", instance, err)
					continue
				}

				log.Printf("received info: %+v", info)

				instance.BootstrapServers = info.BootstrapServers
				instance.Topics = info.Topics
				instance.HistoryTopic = info.HistoryTopic
				sch.Instances = append(sch.Instances, instance)

				log.Printf("instances: %+v", sch.Instances)
			}
		}
		if len(sch.Instances) > 0 {
			result = append(result, sch)
		}
	}

	if len(result) == 0 && len(r.Hosts) > 0 {
		return result, ErrNoResults
	}

	if len(result) != len(r.Hosts) {
		return result, ErrPartialResults
	}

	return result, nil
}

type kafka struct {
	BootstrapServers string   `json:"bootstrap_servers"`
	Topics           []string `json:"topics"`
	HistoryTopic     string   `json:"history_topic"`
}
type info struct {
	Host          string   `json:"hostname"`
	Address       []net.IP `json:"address"`
	ServerAddress string   `json:"server_address"`
	kafka         `json:"kafka"`
}

func getKafkaInfo(host string) (info, error) {
	result := info{}

	err := helper.DecodeJSON(host, "/info", DefaultTimeout, &result)
	if err != nil {
		return result, fmt.Errorf("cannot get info from host %v: %v", host, err)
	}
	return result, nil
}

// Package exporter defines the implementation of dmesg_exporter's
// prometheus exporter internals, providing means for it to gather
// metrics from the registered collectors.
//
// ps.: The package is meant to be used by the main command only as it
//      doesn't provide any interface for generic loggers.
package exporter

import (
	"context"
	"net"
	"net/http"

	"github.com/pkg/errors"
	"github.com/prometheus/client_golang/prometheus/promhttp"
)

type Exporter struct {
	// ListenAddress is the full address used by prometheus
	// to listen for scraping requests.
	//
	// Examples:
	// - :8080
	// - 127.0.0.2:1313
	ListenAddress string

	// TelemetryPath configures the path under which
	// the prometheus metrics are reported.
	//
	// For instance:
	// - /metrics
	// - /telemetry
	TelemetryPath string

	listener net.Listener
}

// Listen initiates the HTTP server using the configurations
// provided via ExporterConfig.
//
// This is a blocking method - make sure you either make use of
// goroutines to not block if needed.
func (e *Exporter) Listen(ctx context.Context) (err error) {
	http.Handle(e.TelemetryPath, promhttp.Handler())

	e.listener, err = net.Listen("tcp", e.ListenAddress)
	if err != nil {
		err = errors.Wrapf(err,
			"failed to listen on address %s", e.ListenAddress)
		return
	}

	doneChan := make(chan error, 1)

	go func() {
		defer close(doneChan)

		err := http.Serve(e.listener, nil)
		if err != nil {
			doneChan <- errors.Wrapf(err,
				"failed listening on address %s",
				e.ListenAddress)
			return
		}
	}()

	select {
	case err = <-doneChan:
	case <-ctx.Done():
		err = ctx.Err()
	}

	return
}

// Close gracefully closes the tcp listener associated with it.
func (e *Exporter) Close() (err error) {
	if e.listener == nil {
		return
	}

	err = e.listener.Close()
	return
}

