	if err != nil {
		fmt.Printf("%+v", err)
	}
	a.StreamFile("/var/lib/asterisk/sounds/tqcenglish", "", 0)
	fmt.Print("record demo end\n")
	kaldi("/var/lib/asterisk/sounds/tqcenglish.wav")
	fmt.Print("end all\n")
	a.Hangup()
}

func kaldi(path string) {
	u := url.URL{Scheme: "ws", Host: Host + ":" + Port, Path: ""}
	log.Info("connecting to ", u.String())

	// Opening websocket connection
	c, _, err := websocket.DefaultDialer.Dial(u.String(), nil)
	check(err)
	defer c.Close()

	f, err := os.Open(path)
	check(err)

	for {
		buf := make([]byte, buffsize)
		dat, err := f.Read(buf)

		if dat == 0 && err == io.EOF {
			err = c.WriteMessage(websocket.TextMessage, []byte("{\"eof\" : 1}"))
			check(err)
			break
		}
		check(err)

		err = c.WriteMessage(websocket.BinaryMessage, buf)
		check(err)

		// Read message from server
		_, _, err = c.ReadMessage()
		check(err)
	}

	// Read final message from server
	_, msg, err := c.ReadMessage()
	check(err)

	// Closing websocket connection
	c.WriteMessage(websocket.CloseMessage, websocket.FormatCloseMessage(websocket.CloseNormalClosure, ""))

	// Unmarshalling received message
	err = json.Unmarshal(msg, &m)
	check(err)
	log.Info(m.Text)
}

func check(err error) {

	if err != nil {
		log.Error(err)
	}
}

package service

import (
	"fmt"
	"io/ioutil"
	"net/http"

	"github.com/soulski/dmp-service/dmp"
	"github.com/streadway/amqp"
)

const (
	DMP_PORT     = 8080
	SERVICE_PORT = 80

	JSON_CONTENT_TYPE = "application/json"
)

type action struct {
	url    string
	action func(w http.ResponseWriter, r *http.Request)
}

var serverUrlAction = []*action{
	{url: "/dmp", action: actionDMP},
}

type Server struct {
	ns string
}

func CreateServer(ns string) *Server {
	return &Server{
		ns: ns,
	}
}

func (s *Server) Start() {
	for _, action := range serverUrlAction {
		http.HandleFunc(action.url, action.action)
	}

	service := &dmp.Service{
		Namespace:    s.ns,
		ContactPoint: fmt.Sprintf("http://127.0.0.1:%d/dmp", SERVICE_PORT),
	}

	if result, err := dmp.RegisterService(service); !result {
		if err != nil {
			panic("Fail to register DMP \n Eror : " + err.Error())
		}
		panic("Fail to register DMP")
	}

	fmt.Println("[Service][Info]Service is started...")

	go startMsgQ()
	http.ListenAndServe(fmt.Sprintf(":%d", SERVICE_PORT), nil)
}

func actionDMP(w http.ResponseWriter, r *http.Request) {
	if r.Method != "PUT" {
		w.WriteHeader(http.StatusNotFound)
		fmt.Fprintf(w, "DMP receiver serve on HTTP Method 'PUT'")
		return
	}

	ioutil.ReadAll(r.Body)
	//	fmt.Printf("[Service][Info]Receive msg : %s \n", string(bodyBytes))

	w.WriteHeader(http.StatusOK)
	w.Write([]byte("Thank for message."))
}

func startMsgQ() {
	conn, err := amqp.Dial("amqp://guest:guest@192.168.127.12:5672")
	if err != nil {
		fmt.Println("Error : ", err.Error())
		return
	}

	defer conn.Close()

	ch, err := conn.Channel()
	if err != nil {
		fmt.Println("Error : ", err.Error())
		return
	}
	defer ch.Close()

	q, err := ch.QueueDeclare(
		"rpc_queue", // name
		false,       // durable
		false,       // delete when usused
		false,       // exclusive
		false,       // no-wait
		nil,         // arguments
	)
	if err != nil {
		fmt.Println("Error : ", err.Error())
		return
	}

	err = ch.Qos(
		1,     // prefetch count
		0,     // prefetch size
		false, // global
	)
	if err != nil {
		fmt.Println("Error : ", err.Error())
		return
	}

	msgs, err := ch.Consume(
		q.Name, // queue
		"",     // consumer
		false,  // auto-ack
		false,  // exclusive
		false,  // no-local
		false,  // no-wait
		nil,    // args
	)
	if err != nil {
		fmt.Println("Error : ", err.Error())
		return
	}

	forever := make(chan bool)

	go func() {
		for d := range msgs {
			n := string(d.Body)
			fmt.Printf("Recv : %s\n", n)

			response := "Hi There!"

			err = ch.Publish(
				"",        // exchange
				d.ReplyTo, // routing key
				false,     // mandatory
				false,     // immediate
				amqp.Publishing{
					ContentType:   "text/plain",
					CorrelationId: d.CorrelationId,
					Body:          []byte(response),
				})
			if err != nil {
				fmt.Println("Error : ", err.Error())
				continue
			}

			d.Ack(false)
		}
	}()

	fmt.Println(" [*] Awaiting RPC requests")
	<-forever
}

