	c.Domain = strings.Split(u.Host, ":")[0]
	c.Port = strings.Split(u.Host, ":")[1]
	c.DecayDuration = 0
	url := fmt.Sprintf(`/_template/%s`, filename)
	if _, err := c.DoCommand(`PUT`, url, nil, data); err != nil {
		http.Error(w, err.Error(), 500)
		return
	}
