	}
	var dBody interface{}
	if err := json.Unmarshal(result, &dBody); err != nil {
		w.Write(jsonEncode(1, map[string]interface{}{"info": err.Error()}))
		return
	}
	w.Write(jsonEncode(0, dBody))
}

