package main

import (
	"fmt"
	"net"
	"encoding/hex"
	"time"

	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/brontide"
	"github.com/btcsuite/btcd/connmgr"
	"github.com/btcsuite/btcd/btcec"
)

func main() {
	var s *server
	s, _ = NewSimpleServer()

	println("start connection by noise protocol")

	// It defines a connection node
	addr, _ := net.ResolveTCPAddr("tcp", "172.16.58.3:9735")
        hexPubkey, _ := hex.DecodeString("<KEY>")

	var hexPubkey33 *btcec.PublicKey
	hexPubkey33, _ = btcec.ParsePubKey(hexPubkey, btcec.S256())
	var peerAddr = &lnwire.NetAddress{
                IdentityKey: hexPubkey33,
                Address:     addr,
        }
	conn, _ := brontide.Dial(s.identityPriv, peerAddr, cfg.net.Dial)

	var connReq *connmgr.ConnReq
	connReq = nil
	var inbound = false

        // With the brontide connection established, we'll now craft the local
        // feature vector to advertise to the remote node.
        localFeatures := lnwire.NewRawFeatureVector()

        // We'll signal that we understand the data loss protection feature,
        // and also that we support the new gossip query features.
        localFeatures.Set(lnwire.DataLossProtectOptional)
        localFeatures.Set(lnwire.GossipQueriesOptional)

        // We'll only request a full channel graph sync if we detect that that
        // we aren't fully synced yet.
        if s.shouldRequestGraphSync() {
                // TODO(roasbeef): only do so if gossiper doesn't have active
                // peers?
                localFeatures.Set(lnwire.InitialRoutingSync)
        }

        p, err := newPeer(conn, connReq, s, peerAddr, inbound, localFeatures)
        if err != nil {
                srvrLog.Errorf("unable to create peer %v", err)
                return
        }

	println("send Init message")
	err = p.sendInitMsg()
	if err != nil {
		println("err occurred")
		return 
	}
	println("sent Init message")

	var waitSecond = 10
	fmt.Printf("waiting for %d seconds\n", waitSecond)
	println("next is sending Ping message")
	time.Sleep(time.Duration(waitSecond) * time.Second)

	println("send Ping message")
	msg := lnwire.NewPing(1)
        err = p.writeMessage(msg)
	if err != nil {
		println("err occurred")
		return
	}
	println("sent Ping message")

	fmt.Printf("waiting for %d seconds\n", waitSecond)
	println("next is sending Ping message")
	time.Sleep(time.Duration(waitSecond) * time.Second)

	println("send Ping message")
	msg2 := lnwire.NewPing(128)
        err = p.writeMessage(msg2)
	if err != nil {
		println("err occurred")
		return
	}
	println("sent Ping message")
}

// This example opens a TCP connection using a device with RTL8720DN firmware
// and sends some data, for the purpose of testing speed and connectivity.
//
// You can open a server to accept connections from this program using:
//
// nc -w 5 -lk 8080
//
package main

import (
	"bytes"
	"fmt"
	"time"

	"tinygo.org/x/drivers/net"
)

// You can override the setting with the init() in another source code.
// func init() {
//    ssid = "sghome-gw"
//    password = "<PASSWORD>"
//    serverIP = "192.168.1.119"
//    debug = true
// }

var (
	ssid     string
	password string
	serverIP = ""
	debug    = false
)

var buf = &bytes.Buffer{}

func main() {
	err := run()
	for err != nil {
		fmt.Printf("error: %s\r\n", err.Error())
		time.Sleep(5 * time.Second)
	}
}

func run() error {
	rtl, err := setupRTL8720DN()
	if err != nil {
		return err
	}
	net.UseDriver(rtl)

	err = rtl.ConnectToAccessPoint(ssid, password, 10*time.Second)
	if err != nil {
		return err
	}

	ip, subnet, gateway, err := rtl.GetIP()
	if err != nil {
		return err
	}
	fmt.Printf("IP Address : %s\r\n", ip)
	fmt.Printf("Mask       : %s\r\n", subnet)
	fmt.Printf("Gateway    : %s\r\n", gateway)

	for {
		sendBatch()
		time.Sleep(500 * time.Millisecond)
	}
	println("Done.")

	return nil
}

func sendBatch() {

	// make TCP connection
	ip := net.ParseIP(serverIP)
	raddr := &net.TCPAddr{IP: ip, Port: 8080}
	laddr := &net.TCPAddr{Port: 8080}

	message("---------------\r\nDialing TCP connection")
	conn, err := net.DialTCP("tcp", laddr, raddr)
	for ; err != nil; conn, err = net.DialTCP("tcp", laddr, raddr) {
		message(err.Error())
		time.Sleep(5 * time.Second)
	}

	n := 0
	w := 0
	start := time.Now()

	// send data
	message("Sending data")

	for i := 0; i < 1000; i++ {
		buf.Reset()
		fmt.Fprint(buf,
			"\r---------------------------- i == ", i, " ----------------------------"+
				"\r---------------------------- i == ", i, " ----------------------------")
		if w, err = conn.Write(buf.Bytes()); err != nil {
			println("error:", err.Error(), "\r")
			continue
		}
		n += w
	}

	buf.Reset()
	ms := time.Now().Sub(start).Milliseconds()
	fmt.Fprint(buf, "\nWrote ", n, " bytes in ", ms, " ms\r\n")
	message(buf.String())

	if _, err := conn.Write(buf.Bytes()); err != nil {
		println("error:", err.Error(), "\r")
	}

	// Right now this code is never reached. Need a way to trigger it...
	println("Disconnecting TCP...")
	conn.Close()
}

func message(msg string) {
	println(msg, "\r")
}

