	case 15: // Complex64
		return complex(rand.Float32(), rand.Float32())
	case 16: // Complex128
		return complex(rand.Float64(), rand.Float64())
	case 17: // Array
		a := [16]int{}
		for i := range a {
			a[i] = rng(10) + 5
		}
		return a
	case 18: // Chan
		return make(chan int, rng(10)+5)
	case 19: // Func
		return func() string { return "fake function" }
	case 20: // Interface
		return NewAnyValue(rng(42))
	case 21: // Map
