		for i := 0; i < len(m); i++ {
			m[i] = randBool()
		}
		return m
	case 22: // Ptr
		value := int(rand.Uint64())
		return &value
	case 23: // Slice
		s := make([]bool, 0, rng(10)+5)
		for i := 0; i < len(s); i++ {
			s[i] = randBool()
		}
		return s
	case 24: // String
		return RandomString(rng(10) + 5)
	case 25: // Struct
