	if err != nil {
		return os.IsExist(err)
	}
	return true
}

// judge the give path if a directory
func IsDir(path string) bool {
	s, err := os.Stat(path)
	if err != nil {
		return false
	}
	return s.IsDir()
}

// judge the give path if a file
func IsFile(path string) bool {
	return !IsDir(path)
}

