	}
	return out
}

func Append(input []bool) []int {
	var out []int
	for i, in := range input {
		if in {
			out = append(out, i)
		}
	}
	return out
}

func MaxAlloc(input []bool) []int {
	out := make([]int, 0, len(input))
	for i, in := range input {
		if in {
			out = append(out, i)
		}
	}
	return out
}

func ExactAlloc(input []bool) []int {
	count := 0
	for _, in := range input {
		if in {
			count++
		}
