// testRand returns a cryptographically random uint64.
func testRand() uint64 {
	var b [8]byte
	if _, err := rand.Read(b[:]); err != nil {
		log.Fatalf("crypto/rand failed: %v", err)
	}
	return binary.BigEndian.Uint64(b[:])
}

// testRandFloat returns a cryptographically random float64 in [0, 1).
func testRandFloat() float64 {
	return float64(testRand()>>11) / (1.0 << 53)
}

