// crIntn returns a cryptographically secure random integer in [0, n)
// using crypto/rand, replacing the insecure math/rand based helper.
func crIntn(n int, t *testing.T) int {
	if n <= 0 {
		return 0
	}
	var buf [8]byte
	if _, err := cr.Read(buf[:]); err != nil {
		t.Fatalf("error on read: %w", err)
	}
	v := int(uint64(buf[0]) | uint64(buf[1])<<8 | uint64(buf[2])<<16 |
		uint64(buf[3])<<24 | uint64(buf[4])<<32 | uint64(buf[5])<<40 |
		uint64(buf[6])<<48 | uint64(buf[7])<<56)
	return v % n
}

