func (a *prod) addVariantPriceRelation(variant *models.Variant) {
	money1 := float64(variant.CostAmount.Int64) * utils.RandFloat(1.2, 3)
	money2 := float64(variant.CostAmount.Int64) * utils.RandFloat(3, 3.4)

