func (a *prod) addStoreProductRelation(product *models.Product) {
	record := &models.StoreProduct{
		StoreID:   storeID,
		ProductID: product.ID,
	}
	if err := record.Insert(context.Background(), db); err != nil {
		panic(err)
	}
