	values := make(sort.IntSlice, 0, 100)
	var h Heap
	for i := 0; i < 100; i++ {
		cur := rand.Uint32() % 1000
		values = append(values, int(cur))
		h.Push(&element{value: cur})
	}

	values.Sort()
	for len(values) > 0 {
