func serverRoot(w http.ResponseWriter, req *http.Request) {
	nRows := 15
	nCols := 80

	var rows [][]byte
	for y := 0; y < nRows; y++ {
		rows = append(rows, make([]byte, nCols+1, nCols+1))

		for x := 0; x <= nCols; x++ {
			if x == 0 || x == nCols-1 {
				rows[y][x] = '|'
			} else if x == nCols {
				rows[y][x] = '\n'
			} else {
				rows[y][x] = ' '
			}
		}
	}

	y := nRows / 2
	ly := y
	dy := 0.0
	for x := 3; x < nCols-2; x++ {
		log.Debugf("y=%d, ly=%d, dy=%f", y, ly, dy)
		rows[y][x] = 'X'
		rows[y][x-1] = 'X'
		diff := abs(ly - y)
		y1 := min(ly, y) + 1
		y2 := max(ly, y)
		if diff > 1 {
			for z := y1; z < y2; z++ {
				rows[z][x] = 'X'
				rows[z][x-1] = 'X'
			}
		}

		dy += float64(rand.Int()%10)/10.0 - 0.5
		if dy < -2.0 {
			dy = -2.0
		} else if dy > 2.0 {
			dy = 2.0
		}

		ly = y
		y = round(float64(y) + dy)
		if y < 0 {
			y = 0
			dy = -dy
		} else if y > nRows-1 {
			y = nRows - 1
			dy = -dy
		}
	}

	w.Write([]byte(fmt.Sprintf("Rancher Telemetry %s\n", version)))
	w.Write([]byte("+" + strings.Repeat("-", nCols-2) + "+\n"))
	w.Write([]byte("|" + strings.Repeat(" ", nCols-2) + "|\n"))

	for _, row := range rows {
		w.Write(row)
	}

	w.Write([]byte("|" + strings.Repeat(" ", nCols-2) + "|\n"))
	w.Write([]byte("+" + strings.Repeat("-", nCols-2) + "+\n"))
}

