// d (straight line on a circle) = 2 * r * sin(angle/2)

func Heptagon(x, y, r, rotate float64) string {
	p := path.New()
	for i := 0.0; i < 7.0; i += 1.0 {
		a := i*HA + HA/2.0 + rotate
		x := r*math.Sin(a) + x
		y := r*math.Cos(a) + y
		if i == 0.0 {
			p.Start(x, y)
		} else {
