// secureIntn returns a cryptographically secure random integer in [0, n)
// using crypto/rand, replacing the insecure math/rand.
func secureIntn(n int) int {
	if n <= 0 {
		return 0
	}
	limit := uint64(n)
	for {
		var b [8]byte
		if _, err := rand.Read(b[:]); err != nil {
			return 0
		}
		var v uint64
		for i := 7; i >= 0; i-- {
			v = v<<8 | uint64(b[i])
		}
		if v < limit {
			return int(v)
		}
	}
}

