// cryptoRandIntn returns a cryptographically secure non-negative random number less than n using crypto/rand
func cryptoRandIntn(n int) int {
	if n <= 0 {
		return 0
	}
	mod := int32(math.MaxInt32 % n)
	var x int32
	for {
		if _, err := crand.Read((*[4]byte)(unsafe.Pointer(&x))); err != nil {
			panic(err)
		}
		if x >= 0 && x < mod {
			break
		}
	}
	return int(x % n)

