package main

import (
	"io"
	"os"

	"gopkg.in/gcfg.v1"
)

const (
	// The file we read from
	configFile = "config.gcfg"
	// The example file kept in version control. We'll copy and load from this
	// by default.
	configExample = "config.example.gcfg"
)

type Configuration struct {
	Server struct {
		Address         string
		ProfilerAddress string
		Logging         string
		URL             string
		Ttl             int
	}

	Minecraft struct {
		UserAgent        string
		SessionServerURL string
		ProfileURL       string
	}

	Cache map[string]*struct {
		Storage string
		Size    int
	}

	Redis map[string]*struct {
		Address  string
		Auth     string
		DB       int
		Prefix   string
		PoolSize int
	}
}

// Reads the configuration from the config file, copying a config into
// place from the example if one does not yet exist.
func (c *Configuration) load() error {
	err := c.ensureConfigExists()
	if err != nil {
		return err
	}

	return gcfg.ReadFileInto(c, configFile)
}

// Creates the config.json if it does not exist.
func (c *Configuration) ensureConfigExists() error {
	if _, err := os.Stat(configFile); os.IsNotExist(err) {
		return copyFile(configExample, configFile)
	}
	return nil

}

// Copies *only the contents* of one file to a new path.
func copyFile(src string, dest string) error {
	original, err := os.Open(src)
	if err != nil {
		return err
	}
	defer original.Close()

	destination, err := os.Create(dest)
	if err != nil {
		return err
	}
	defer destination.Close()

	// do the actual work
	_, err = io.Copy(destination, original)
	return err
}

