	mainAddress := uint16(0)
	programSize := uint16(0)
	m.Mem, mainAddress, programSize = svb.LoadProgram(c, b)

	// Calculate heap offset
	m.HeapOffset += programSize

	// Start repl
	repl(c, mainAddress)
}

